window.SYLLABUS_OLDER = {"versions":[{"id":"2022","label":"2022","until":"2022","numbered":false,"source":{"title":"Cambridge IGCSE Biology 0610, for examination in 2022","url":"https://www.cambridgeinternational.org/Images/556995-2022-syllabus.pdf"},"topics":[{"n":"1","title":"Characteristics and classification of living organisms","sections":[{"n":"1.1","title":"Characteristics of living organisms","core":[{"text":"Describe the characteristics of living organisms by defining the terms:\n– movement as an action by an organism causing a change of position or place\n– respiration as the chemical reactions in cells that break down nutrient molecules and release energy\n– sensitivity as the ability to detect and respond to changes in the environment\n– growth as a permanent increase in size\n– reproduction as the processes that make more of the same kind of organism\n– excretion as removal from organisms of toxic materials and substances in excess of requirements\n– nutrition as taking in of materials for energy, growth and development"}],"supplement":[{"text":"Define the terms:\n– movement as an action by an organism or part of an organism causing a change of position or place\n– respiration as the chemical reactions in cells that break down nutrient molecules and release energy for metabolism\n– sensitivity as the ability to detect or sense stimuli in the internal or external environment and to make appropriate responses\n– growth as a permanent increase in size and dry mass by an increase in cell number or cell size or both\n– excretion as removal from organisms of the waste products of metabolism (chemical reactions in cells including respiration), toxic materials, and substances in excess of requirements\n– nutrition as taking in of materials for energy, growth and development; plants require light, carbon dioxide, water and ions; animals need organic compounds and ions and usually need water"}]},{"n":"1.2","title":"Concept and use of a classification system","core":[{"text":"State that organisms can be classified into groups by the features that they share"},{"text":"Define species as a group of organisms that can reproduce to produce fertile offspring"},{"text":"Define and describe the binomial system of naming species as an internationally agreed system in which the scientific name of an organism is made up of two parts showing the genus and species"}],"supplement":[{"text":"Explain that classification systems aim to reflect evolutionary relationships"},{"text":"Explain that classification is traditionally based on studies of morphology and anatomy"},{"text":"Explain that the sequences of bases in DNA and of amino acids in proteins are used as a more accurate means of classification"},{"text":"Explain that organisms which share a more recent ancestor (are more closely related) have base sequences in DNA that are more similar than those that share only a distant ancestor"}]},{"n":"1.3","title":"Features of organisms","core":[{"text":"List the features in the cells of all living organisms, limited to cytoplasm, cell membrane and DNA as genetic material"},{"text":"List the main features used to place animals and plants into the appropriate kingdoms"},{"text":"List the main features used to place organisms into groups within the animal kingdom, limited to: –– the main groups of vertebrates: mammals, birds, reptiles, amphibians, fish –– the main groups of arthropods: myriapods, insects, arachnids, crustaceans"}],"supplement":[{"text":"List the features in the cells of all living organisms, limited to ribosomes for protein synthesis and enzymes involved in respiration"},{"text":"List the main features used to place all organisms into one of the five kingdoms: Animal, Plant, Fungus, Prokaryote, Protoctist"},{"text":"List the main features used to place organisms into groups within the plant kingdom, limited to ferns and flowering plants (dicotyledons and monocotyledons)"},{"text":"List the features of viruses, limited to protein coat and genetic material"}]},{"n":"1.4","title":"Dichotomous keys","core":[{"text":"Construct and use simple dichotomous keys based on easily identifiable features"}],"supplement":[]}]},{"n":"2","title":"Organisation of the organism","sections":[{"n":"2.1","title":"Cell structure and organisation","core":[{"text":"Describe and compare the structure of a plant cell with an animal cell, as seen under a light microscope, limited to cell wall, nucleus, cytoplasm, chloroplasts, vacuoles and location of the cell membrane"},{"text":"State the functions of the structures seen under the light microscope in the plant cell and in the animal cell"}],"supplement":[{"text":"State that the cytoplasm of all cells contains structures, limited to ribosomes on rough endoplasmic reticulum and vesicles"},{"text":"State that almost all cells, except prokaryotes, have mitochondria and rough endoplasmic reticulum"},{"text":"Identify mitochondria and rough endoplasmic reticulum in diagrams and images of cells"},{"text":"State that aerobic respiration occurs in mitochondria"},{"text":"State that cells with high rates of metabolism require large numbers of mitochondria to provide sufficient energy"}]},{"n":"2.2","title":"Levels of organisation","core":[{"text":"Relate the structure of the following to their functions:\n– ciliated cells – movement of mucus in the trachea and bronchi\n– root hair cells – absorption\n– xylem vessels – conduction and support\n– palisade mesophyll cells – photosynthesis\n– nerve cells – conduction of impulses\n– red blood cells – transport of oxygen\n– sperm and egg cells – reproduction"},{"text":"Define tissue as a group of cells with similar structures, working together to perform a shared function"},{"text":"Define organ as a structure made up of a group of tissues, working together to perform specific functions"},{"text":"Define organ system as a group of organs with related functions, working together to perform body functions"},{"text":"State examples of tissues, organs and organ systems from sections 6 to 16"},{"text":"Identify the different levels of organisation in drawings, diagrams and images of familiar material"}],"supplement":[{"text":"Identify the different levels of organisation in drawings, diagrams and images of unfamiliar material"}]},{"n":"2.3","title":"Size of specimens","core":[{"text":"Calculate magnification and size of biological specimens using millimetres as units"}],"supplement":[{"text":"Calculate magnification and size of biological specimens using millimetres and micrometres as units"}]}]},{"n":"3","title":"Movement in and out of cells","sections":[{"n":"3.1","title":"Diffusion","core":[{"text":"Define diffusion as the net movement of particles from a region of their higher concentration to a region of their lower concentration down a concentration gradient, as a result of their random movement"},{"text":"Describe the importance of diffusion of gases and solutes"},{"text":"State that substances move into and out of cells by diffusion through the cell membrane"}],"supplement":[{"text":"State that the energy for diffusion comes from the kinetic energy of random movement of molecules and ions"},{"text":"Investigate the factors that influence diffusion, limited to surface area, temperature, concentration gradients and distance"}]},{"n":"3.2","title":"Osmosis","core":[{"text":"State that water diffuses through partially permeable membranes by osmosis"},{"text":"State that water moves in and out of cells by osmosis through the cell membrane"},{"text":"Investigate and describe the effects on plant tissues of immersing them in solutions of different concentrations"},{"text":"State that plants are supported by the pressure of water inside the cells pressing outwards on the cell wall"}],"supplement":[{"text":"Define osmosis as the net movement of water molecules from a region of higher water potential (dilute solution) to a region of lower water potential (concentrated solution), through a partially permeable membrane"},{"text":"Explain the effects on plant tissues of immersing them in solutions of different concentrations by using the terms turgid, turgor pressure, plasmolysis and flaccid"},{"text":"Explain the importance of water potential and osmosis in the uptake of water by plants"},{"text":"Explain the importance of water potential and osmosis on animal cells and tissues"},{"text":"Explain how plants are supported by the turgor pressure within cells, in terms of water pressure acting against an inelastic cell wall"}]},{"n":"3.3","title":"Active transport","core":[{"text":"Define active transport as the movement of particles through a cell membrane from a region of lower concentration to a region of higher concentration using energy from respiration"}],"supplement":[{"text":"Discuss the importance of active transport as a process for movement across membranes:\n– e.g. ion uptake by root hairs and uptake of glucose by epithelial cells of villi and kidney tubules"},{"text":"Explain how protein molecules move particles across a membrane during active transport"}]}]},{"n":"4","title":"Biological molecules","sections":[{"n":"4.1","title":"Biological molecules","core":[{"text":"List the chemical elements that make up:\n– carbohydrates\n– fats\n– proteins"},{"text":"State that large molecules are made from smaller molecules, limited to:\n– starch and glycogen from glucose\n– cellulose from glucose\n– proteins from amino acids\n– fats and oils from fatty acids and glycerol"},{"text":"Describe the use of:\n– iodine solution to test for starch\n– Benedict’s solution to test for reducing sugars\n– biuret test for proteins\n– ethanol emulsion test for fats and oils\n– DCPIP test for vitamin C"},{"text":"State that water is important as a solvent"}],"supplement":[{"text":"Explain that different sequences of amino acids give different shapes to protein molecules"},{"text":"Relate the shape and structure of protein molecules to their function, limited to the active site of enzymes and the binding site of antibodies continued"},{"text":"Describe the structure of DNA as:\n– two strands coiled together to form a double helix\n– each strand contains chemicals called bases\n– cross-links between the strands are formed by pairs of bases\n– the bases always pair up in the same way: A with T, and C with G (full names are not required)"},{"text":"Describe the roles of water as a solvent in organisms with respect to digestion, excretion and transport"}]}]},{"n":"5","title":"Enzymes","sections":[{"n":"5.1","title":"Enzymes","core":[{"text":"Define the term catalyst as a substance that increases the rate of a chemical reaction and is not changed by the reaction"},{"text":"Define enzymes as proteins that function as biological catalysts"},{"text":"Describe why enzymes are important in all living organisms in terms of reaction speed necessary to sustain life"},{"text":"Describe enzyme action with reference to the complementary shape of an enzyme and its substrate and the formation of a product (knowledge of the term active site is not required)"},{"text":"Investigate and describe the effect of changes in temperature and pH on enzyme activity"}],"supplement":[{"text":"Explain enzyme action with reference to the active site, enzyme-substrate complex, substrate and product"},{"text":"Explain the specificity of enzymes in terms of the complementary shape and fit of the active site with the substrate"},{"text":"Explain the effect of changes in temperature on enzyme activity in terms of kinetic energy, shape and fit, frequency of effective collisions and denaturation"},{"text":"Explain the effect of changes in pH on enzyme activity in terms of shape and fit and denaturation"}]}]},{"n":"6","title":"Plant nutrition","sections":[{"n":"6.1","title":"Photosynthesis","core":[{"text":"Define photosynthesis as the process by which plants manufacture carbohydrates from raw materials using energy from light"},{"text":"State the word equation for photosynthesis: carbon dioxide + water → glucose + oxygen, in the presence of light and chlorophyll"},{"text":"Investigate the necessity for chlorophyll, light and carbon dioxide for photosynthesis, using appropriate controls"},{"text":"Investigate and describe the effects of varying light intensity, carbon dioxide concentration and temperature on the rate of photosynthesis, e.g. in submerged aquatic plants"}],"supplement":[{"text":"State the balanced chemical equation for photosynthesis light 6CO2 + 6H2O C6H12O6 + 6O2 chlorophyll"},{"text":"Explain that chlorophyll transfers light energy into chemical energy in molecules, for the synthesis of carbohydrates"},{"text":"Outline the subsequent use and storage of the carbohydrates made in photosynthesis"},{"text":"Define the term limiting factor as something present in the environment in such short supply that it restricts life processes"},{"text":"Identify and explain the limiting factors of photosynthesis in different environmental conditions"},{"text":"Describe the use of carbon dioxide enrichment, optimum light and optimum temperatures in glasshouses in temperate and tropical countries"},{"text":"Use hydrogencarbonate indicator solution to investigate the effect of gas exchange of an aquatic plant kept in the light and in the dark"}]},{"n":"6.2","title":"Leaf structure","core":[{"text":"Identify chloroplasts, cuticle, guard cells and stomata, upper and lower epidermis, palisade mesophyll, spongy mesophyll, vascular bundles, xylem and phloem in leaves of a dicotyledonous plant"}],"supplement":[{"text":"Explain how the internal structure of a leaf is adapted for photosynthesis"}]},{"n":"6.3","title":"Mineral requirements","core":[{"text":"Describe the importance of:\n– nitrate ions for making amino acids\n– magnesium ions for making chlorophyll"}],"supplement":[{"text":"Explain the effects of nitrate ion and magnesium ion deficiency on plant growth"}]}]},{"n":"7","title":"Human nutrition","sections":[{"n":"7.1","title":"Diet","core":[{"text":"State what is meant by the term balanced diet for humans"},{"text":"Explain how age, gender and activity affect the dietary needs of humans including during pregnancy and whilst breast-feeding"},{"text":"Describe the effects of malnutrition in relation to starvation, constipation, coronary heart disease, obesity and scurvy"},{"text":"List the principal sources of, and describe the dietary importance of:\n– carbohydrates\n– fats\n– proteins\n– vitamins, limited to C and D\n– mineral salts, limited to calcium and iron\n– fibre (roughage)\n– water"}],"supplement":[{"text":"Explain the causes and effects of vitamin D and iron deficiencies"},{"text":"Explain the causes and effects of protein-energy malnutrition, e.g. kwashiorkor and marasmus"}]},{"n":"7.2","title":"Alimentary canal","core":[{"text":"Define ingestion as the taking of substances, e.g. food and drink, into the body through the mouth"},{"text":"Define mechanical digestion as the breakdown of food into smaller pieces without chemical change to the food molecules"},{"text":"Define chemical digestion as the breakdown of large, insoluble molecules into small, soluble molecules"},{"text":"Define absorption as the movement of small food molecules and ions through the wall of the intestine into the blood"},{"text":"Define assimilation as the movement of digested food molecules into the cells of the body where they are used, becoming part of the cells"},{"text":"Define egestion as the passing out of food that has not been digested or absorbed, as faeces, through the anus"},{"text":"Describe diarrhoea as the loss of watery faeces"},{"text":"Outline the treatment of diarrhoea using oral rehydration therapy"},{"text":"Describe cholera as a disease caused by a bacterium"},{"text":"Identify the main regions of the alimentary canal and associated organs, limited to mouth, salivary glands, oesophagus, stomach, small intestine (duodenum and ileum), pancreas, liver, gall bladder and large intestine (colon, rectum, anus)"},{"text":"Describe the functions of the regions of the alimentary canal listed above, in relation to ingestion, digestion, absorption, assimilation and egestion of food"}],"supplement":[{"text":"Explain that the cholera bacterium produces a toxin that causes secretion of chloride ions into the small intestine, causing osmotic movement of water into the gut, causing diarrhoea, dehydration and loss of salts from blood"}]},{"n":"7.3","title":"Mechanical digestion","core":[{"text":"Identify the types of human teeth (incisors, canines, premolars and molars)"},{"text":"Describe the structure of human teeth, limited to enamel, dentine, pulp, nerves and cement, as well as the gums"},{"text":"Describe the functions of the types of human teeth in mechanical digestion of food"},{"text":"State the causes of dental decay in terms of a coating of bacteria and food on teeth, the bacteria respiring sugars in the food, producing acid which dissolves the enamel and dentine"},{"text":"Describe the proper care of teeth in terms of diet and regular brushing"}],"supplement":[]},{"n":"7.4","title":"Chemical digestion","core":[{"text":"State the significance of chemical digestion in the alimentary canal in producing small, soluble molecules that can be absorbed"},{"text":"State the functions of enzymes as follows:\n– amylase breaks down starch to simpler sugars\n– protease breaks down protein to amino acids\n– lipase breaks down fats to fatty acids and glycerol"},{"text":"State where, in the alimentary canal, amylase, protease and lipase are secreted"},{"text":"State the functions of the hydrochloric acid in gastric juice, limited to killing bacteria in food and giving an acid pH for enzymes"}],"supplement":[{"text":"Describe the digestion of starch in the alimentary canal:\n– amylase is secreted into the alimentary canal and breaks down starch to maltose\n– maltose is broken down by maltase to glucose on the membranes of the epithelium lining the small intestine"},{"text":"Describe pepsin and trypsin as two protease enzymes that function in different parts of the alimentary canal:\n– pepsin in the stomach\n– trypsin in the small intestine"},{"text":"Explain the functions of the hydrochloric acid in gastric juice, limited to the low pH:\n– denaturing enzymes in harmful microorganisms in food\n– giving the optimum pH for pepsin activity"},{"text":"Outline the role of bile in neutralising the acidic mixture of food and gastric juices entering the duodenum from the stomach, to provide a suitable pH for enzyme action"},{"text":"Outline the role of bile in emulsifying fats to increase the surface area for the chemical digestion of fat to fatty acids and glycerol by lipase"}]},{"n":"7.5","title":"Absorption","core":[{"text":"Identify the small intestine as the region for the absorption of digested food"},{"text":"State that water is absorbed in both the small intestine and the colon, but that most absorption of water happens in the small intestine"}],"supplement":[{"text":"Explain the significance of villi and microvilli in increasing the internal surface area of the small intestine"},{"text":"Describe the structure of a villus"},{"text":"Describe the roles of capillaries and lacteals in villi"}]}]},{"n":"8","title":"Transport in plants","sections":[{"n":"8.1","title":"Transport in plants","core":[{"text":"State the functions of xylem and phloem"},{"text":"Identify the position of xylem and phloem as seen in sections of roots, stems and leaves, limited to non-woody dicotyledonous plants"}],"supplement":[]},{"n":"8.2","title":"Water uptake","core":[{"text":"Identify root hair cells, as seen under the light microscope, and state their functions"},{"text":"State the pathway taken by water through root, stem and leaf as root hair cells, root cortex cells, xylem and mesophyll cells"},{"text":"Investigate, using a suitable stain, the pathway of water through the above-ground parts of a plant"}],"supplement":[{"text":"Explain that the large surface area of root hairs increases the rate of the absorption of water by osmosis and ions by active transport"}]},{"n":"8.3","title":"Transpiration","core":[{"text":"State that water is transported from the roots to leaves through the xylem vessels"},{"text":"Define transpiration as loss of water vapour from plant leaves by evaporation of water at the surfaces of the mesophyll cells followed by diffusion of water vapour through the stomata"},{"text":"Investigate and describe the effects of variation of temperature and humidity on transpiration rate"}],"supplement":[{"text":"Explain how water vapour loss is related to the large surface area of cell surfaces, interconnecting air spaces and stomata"},{"text":"Explain the mechanism by which water moves upwards in the xylem in terms of a transpiration pull that draws up a column of water molecules, held together by cohesion"},{"text":"Explain how and why wilting occurs"},{"text":"Explain the effects of variation of temperature and humidity on transpiration rate"}]},{"n":"8.4","title":"Translocation","core":[],"supplement":[{"text":"Define translocation in terms of the movement of sucrose and amino acids in phloem:\n– from regions of production (source)\n– to regions of storage OR to regions where they are used in respiration or growth (sink)"},{"text":"Explain that some parts of a plant may act as a source and a sink at different times during the life of a plant"}]}]},{"n":"9","title":"Transport in animals","sections":[{"n":"9.1","title":"Transport in animals","core":[{"text":"Describe the circulatory system as a system of blood vessels with a pump and valves to ensure one-way flow of blood"}],"supplement":[{"text":"Describe the single circulation of a fish"},{"text":"Describe the double circulation of a mammal"},{"text":"Explain the advantages of a double circulation"}]},{"n":"9.2","title":"Heart","core":[{"text":"Name and identify the structures of the mammalian heart, limited to the muscular wall, the septum, the left and right ventricles and atria, one-way valves and coronary arteries"},{"text":"State that blood is pumped away from the heart into arteries and returns to the heart in veins"},{"text":"State that the activity of the heart may be monitored by ECG, pulse rate and listening to sounds of valves closing"},{"text":"Investigate and state the effect of physical activity on the pulse rate"},{"text":"Describe coronary heart disease in terms of the blockage of coronary arteries and state the possible risk factors as diet, stress, smoking, genetic predisposition, age and gender"}],"supplement":[{"text":"Name and identify the atrioventricular and semilunar valves in the mammalian heart"},{"text":"Explain the relative thickness:\n– of the muscle wall of the left and right ventricles\n– of the muscle wall of the atria compared to that of the ventricles"},{"text":"Explain the importance of the septum in separating oxygenated and deoxygenated blood"},{"text":"Describe the functioning of the heart in terms of the contraction of muscles of the atria and ventricles and the action of the valves"},{"text":"Explain the effect of physical activity on the heart rate"},{"text":"Discuss the roles of diet and exercise in the prevention of coronary heart disease"},{"text":"Describe ways in which coronary heart disease may be treated, limited to drug treatment with aspirin and surgery (stents, angioplasty and by-pass)"}]},{"n":"9.3","title":"Blood and lymphatic vessels","core":[{"text":"Describe the structure and functions of arteries, veins and capillaries"},{"text":"Name the main blood vessels to and from the:\n– heart, limited to vena cava, aorta, pulmonary artery and pulmonary vein\n– lungs, limited to the pulmonary artery and pulmonary vein\n– kidney, limited to the renal artery and renal vein"}],"supplement":[{"text":"Explain how the structures of arteries, veins and capillaries are adapted for their functions"},{"text":"State the function of arterioles, venules and shunt vessels"},{"text":"Outline the lymphatic system in terms of lymphatic vessels and lymph nodes"},{"text":"Describe the function of the lymphatic system in the circulation of body fluids and the protection of the body from infection"}]},{"n":"9.4","title":"Blood","core":[{"text":"List the components of blood as red blood cells, white blood cells, platelets and plasma"},{"text":"Identify red and white blood cells, as seen under the light microscope, on prepared slides and in diagrams and photomicrographs"},{"text":"State the functions of the following components of blood:\n– red blood cells in transporting oxygen, including the role of haemoglobin\n– white blood cells in phagocytosis and antibody production\n– platelets in clotting (details are not required)\n– plasma in the transport of blood cells, ions, soluble nutrients, hormones and carbon dioxide"}],"supplement":[{"text":"Identify lymphocyte and phagocyte white blood cells, as seen under the light microscope, on prepared slides and in diagrams and photomicrographs"},{"text":"State the functions of:\n– lymphocytes – antibody production\n– phagocytes – phagocytosis"},{"text":"Describe the process of clotting as the conversion of fibrinogen to fibrin to form a mesh"},{"text":"State the roles of blood clotting as preventing blood loss and preventing the entry of pathogens"},{"text":"Describe the transfer of materials between capillaries and tissue fluid (details of the roles of water potential and hydrostatic pressure are not required)"}]}]},{"n":"10","title":"Diseases and immunity","sections":[{"n":"10.1","title":"Diseases and immunity","core":[{"text":"Define pathogen as a disease-causing organism"},{"text":"Define transmissible disease as a disease in which the pathogen can be passed from one host to another"},{"text":"State that the pathogen for a transmissible disease may be transmitted either through direct contact, e.g. through blood or other body fluids, or indirectly, e.g. from contaminated surfaces or food, from animals, or from the air"},{"text":"State that the body has defences:\n– mechanical barriers, limited to skin and hairs in the nose\n– chemical barriers, limited to mucus and stomach acid\n– cells, limited to phagocytosis and antibody production by white blood cells\n– which can be enhanced by vaccination"},{"text":"Explain the importance of hygienic food preparation, good personal hygiene, waste disposal and sewage treatment in controlling the spread of disease"}],"supplement":[{"text":"State that antibodies lock on to antigens leading to direct destruction of pathogens, or marking of pathogens for destruction by phagocytes"},{"text":"Explain how each pathogen has its own antigens, which have specific shapes, so specific antibodies which fit the specific shapes of the antigens are needed"},{"text":"Define active immunity as defence against a pathogen by antibody production in the body"},{"text":"Explain that active immunity is gained after an infection by a pathogen, or by vaccination"},{"text":"Explain the process of vaccination:\n– harmless pathogen given which has antigens\n– antigens trigger an immune response by lymphocytes which produce antibodies\n– memory cells are produced that give long-term immunity continued"},{"text":"Explain the role of vaccination in controlling the spread of diseases"},{"text":"Explain that passive immunity is short-term defence against a pathogen by antibodies acquired from another individual, e.g. mother to infant"},{"text":"State that memory cells are not produced in passive immunity"},{"text":"Explain the importance of passive immunity for breast-fed infants"},{"text":"State that some diseases are caused by the immune system targeting and destroying body cells, limited to type 1 diabetes"}]}]},{"n":"11","title":"Gas exchange in humans","sections":[{"n":"11.1","title":"Gas exchange in humans","core":[{"text":"List the features of gas exchange surfaces in humans, limited to large surface area, thin surface, good blood supply and good ventilation with air"},{"text":"Name and identify the lungs, diaphragm, ribs, intercostal muscles, larynx, trachea, bronchi, bronchioles, alveoli and associated capillaries"},{"text":"State the differences in composition between inspired and expired air, limited to oxygen, carbon dioxide and water vapour"},{"text":"Use limewater as a test for carbon dioxide to investigate the differences in composition between inspired and expired air"},{"text":"Investigate and describe the effects of physical activity on rate and depth of breathing"}],"supplement":[{"text":"Name and identify the internal and external intercostal muscles"},{"text":"State the functions of the cartilage in the trachea"},{"text":"Explain the role of the ribs, the internal and external intercostal muscles and the diaphragm in producing volume and pressure changes in the thorax leading to the ventilation of the lungs"},{"text":"Explain the differences in composition between inspired and expired air"},{"text":"Explain the link between physical activity and rate and depth of breathing in terms of the increased carbon dioxide concentration in the blood, detected by the brain, causing an increased rate of breathing"},{"text":"Explain the role of goblet cells, mucus and ciliated cells in protecting the gas exchange system from pathogens and particles"}]}]},{"n":"12","title":"Respiration","sections":[{"n":"12.1","title":"Respiration","core":[{"text":"State the uses of energy in the body of humans: muscle contraction, protein synthesis, cell division, active transport, growth, the passage of nerve impulses and the maintenance of a constant body temperature"},{"text":"State that respiration involves the action of enzymes in cells"}],"supplement":[]},{"n":"12.2","title":"Aerobic respiration","core":[{"text":"Define aerobic respiration as the chemical reactions in cells that use oxygen to break down nutrient molecules to release energy"},{"text":"State the word equation for aerobic respiration as glucose + oxygen → carbon dioxide + water"},{"text":"Investigate the uptake of oxygen by respiring organisms, such as arthropods and germinating seeds"}],"supplement":[{"text":"State the balanced chemical equation for aerobic respiration as C6H12O6 + 6O2 → 6CO2 + 6H2O"},{"text":"Investigate the effect of temperature on the rate of respiration of germinating seeds"}]},{"n":"12.3","title":"Anaerobic respiration","core":[{"text":"Define anaerobic respiration as the chemical reactions in cells that break down nutrient molecules to release energy without using oxygen"},{"text":"State the word equations for anaerobic respiration in muscles during vigorous exercise (glucose → lactic acid) and in the microorganism yeast (glucose → alcohol + carbon dioxide)"},{"text":"State that anaerobic respiration releases much less energy per glucose molecule than aerobic respiration"}],"supplement":[{"text":"State the balanced chemical equation for anaerobic respiration in the microorganism yeast as C6H12O6 → 2C2H5OH + 2CO2"},{"text":"State that lactic acid builds up in muscles and blood during vigorous exercise causing an oxygen debt"},{"text":"Outline how the oxygen debt is removed during recovery, limited to:\n– aerobic respiration of lactic acid in the liver\n– continuation, after exercise, of fast heart rate to transport lactic acid in blood from muscles to the liver\n– continuation, after exercise, of deeper breathing supplying oxygen for aerobic respiration of lactic acid"}]}]},{"n":"13","title":"Excretion in humans","sections":[{"n":"13.1","title":"Excretion in humans","core":[{"text":"State that urea is formed in the liver from excess amino acids"},{"text":"State that carbon dioxide is excreted through the lungs"},{"text":"State that the kidneys excrete urea and excess water and salts"},{"text":"Explain that the volume and concentration of urine produced is affected by water intake, temperature and exercise"},{"text":"Identify on drawings, diagrams and images, the ureters, bladder and urethra"}],"supplement":[{"text":"Describe the role of the liver in the assimilation of amino acids by converting them to proteins, including plasma proteins, e.g. fibrinogen"},{"text":"Define deamination as the removal of the nitrogen-containing part of amino acids to form urea"},{"text":"Explain the need for excretion, limited to toxicity of urea and carbon dioxide"},{"text":"Outline the structure of the kidney, limited to the cortex, medulla and ureter"},{"text":"Outline the structure and functioning of a kidney tubule, including:\n– the role of the glomerulus in the filtration from the blood of water, glucose, urea and salts\n– the role of the tubule in the reabsorption of all of the glucose, most of the water and some salts back into the blood, leading to the concentration of urea in the urine as well as loss of excess water and salts (details of these processes are not required)"},{"text":"Explain dialysis in terms of salt balance, the maintenance of glucose concentration and the removal of urea"},{"text":"Describe the use of dialysis in kidney machines"},{"text":"Discuss the advantages and disadvantages of kidney transplants, compared with dialysis"}]}]},{"n":"14","title":"Coordination and response","sections":[{"n":"14.1","title":"Nervous control in humans","core":[{"text":"Describe a nerve impulse as an electrical signal that passes along nerve cells called neurones"},{"text":"Describe the human nervous system in terms of:\n– the central nervous system consisting of brain and spinal cord\n– the peripheral nervous system\n– coordination and regulation of body functions"},{"text":"Identify motor (effector), relay (connector) and sensory neurones from diagrams"},{"text":"Describe a simple reflex arc in terms of receptor, sensory neurone, relay neurone, motor neurones and effector"},{"text":"Describe a reflex action as a means of automatically and rapidly integrating and coordinating stimuli with the responses of effectors (muscles and glands)"},{"text":"Define a synapse as a junction between two neurones"}],"supplement":[{"text":"Distinguish between voluntary and involuntary actions"},{"text":"Describe the structure of a synapse, including the presence of neurotransmitter containing vesicles, the synaptic cleft and neurotransmitter receptor molecules"},{"text":"Describe how an impulse triggers the release of a neurotransmitter from vesicles into the synaptic gap and how the neurotransmitter diffuses across to bind with receptor molecules, in the membrane of the neurone after the synaptic gap, causing the impulse to continue"},{"text":"State that in a reflex arc the synapses ensure that impulses travel in one direction only"},{"text":"State that many drugs, e.g. heroin, act upon synapses"}]},{"n":"14.2","title":"Sense organs","core":[{"text":"Define sense organs as groups of receptor cells responding to specific stimuli: light, sound, touch, temperature and chemicals"},{"text":"Identify the structures of the eye, limited to cornea, iris, pupil, lens, retina, optic nerve and blind spot"},{"text":"Describe the function of each part of the eye, limited to:\n– cornea – refracts light\n– iris – controls how much light enters pupil\n– lens – focuses light onto retina\n– retina – contains light receptors, some sensitive to light of different colours\n– optic nerve – carries impulses to the brain"},{"text":"Explain the pupil reflex in terms of light intensity and pupil diameter only"}],"supplement":[{"text":"Explain the pupil reflex in terms of light intensity and antagonistic action of circular and radial muscles in the iris"},{"text":"Explain accommodation to view near and distant objects in terms of the contraction and relaxation of the ciliary muscles, tension in the suspensory ligaments, shape of the lens and refraction of light"},{"text":"State the distribution of rods and cones in the retina of a human"},{"text":"Outline the function of rods and cones, limited to greater sensitivity of rods for night vision and three different kinds of cones absorbing light of different colours for colour vision"},{"text":"Identify the position of the fovea"}]},{"n":"14.3","title":"Hormones in humans","core":[{"text":"Define a hormone as a chemical substance, produced by a gland and carried by the blood, which alters the activity of one or more specific target organs"},{"text":"Identify specific endocrine glands and their secretions, limited to adrenal glands and adrenaline, pancreas and insulin, testes and testosterone and ovaries and oestrogen"},{"text":"Describe adrenaline as the hormone secreted in ‘fight or flight’ situations and its effects, limited to increased breathing and pulse rate and widened pupils"},{"text":"Give examples of situations in which adrenaline secretion increases"},{"text":"State the functions of insulin, oestrogen and testosterone"}],"supplement":[{"text":"Discuss the role of the hormone adrenaline in the chemical control of metabolic activity, including increasing the blood glucose concentration and pulse rate"},{"text":"Compare nervous and hormonal control systems in terms of speed and longevity of action"}]},{"n":"14.4","title":"Homeostasis","core":[{"text":"Define homeostasis as the maintenance of a constant internal environment"},{"text":"Name and identify on a diagram of the skin: hairs, hair erector muscles, sweat glands, receptors, sensory neurones, blood vessels and fatty tissue"},{"text":"Describe the maintenance of a constant internal body temperature in humans in terms of insulation, sweating, shivering and the role of the brain (limited to blood temperature receptors and coordination)"}],"supplement":[{"text":"Explain that homeostasis is the control of internal conditions within set limits"},{"text":"Explain the concept of control by negative feedback"},{"text":"Describe the control of the glucose concentration of the blood by the liver and the roles of insulin and glucagon from the pancreas"},{"text":"Outline the symptoms and treatment of type 1 diabetes (detail of β cells is not required)"},{"text":"Describe the maintenance of a constant internal body temperature in humans in terms of vasodilation and vasoconstriction of arterioles supplying skin surface capillaries"}]},{"n":"14.5","title":"Tropic responses","core":[{"text":"Define gravitropism as a response in which parts of a plant grow towards or away from gravity"},{"text":"Define phototropism as a response in which parts of a plant grow towards or away from the direction from which light is coming"},{"text":"Investigate gravitropism and phototropism in shoots and roots"}],"supplement":[{"text":"Explain phototropism and gravitropism of a shoot as examples of the chemical control of plant growth"},{"text":"Explain the role of auxin in controlling shoot growth, limited to:\n– auxin made in shoot tip (only)\n– auxin spreads through the plant from the shoot tip\n– auxin is unequally distributed in response to light and gravity\n– auxin stimulates cell elongation"},{"text":"Describe the use in weedkillers of the synthetic plant hormone 2,4-D"}]}]},{"n":"15","title":"Drugs","sections":[{"n":"15.1","title":"Drugs","core":[{"text":"Define a drug as any substance taken into the body that modifies or affects chemical reactions in the body"}],"supplement":[]},{"n":"15.2","title":"Medicinal drugs","core":[{"text":"Describe the use of antibiotics for the treatment of bacterial infection"},{"text":"State that some bacteria are resistant to antibiotics which reduces the effectiveness of antibiotics"},{"text":"State that antibiotics kill bacteria but do not affect viruses"}],"supplement":[{"text":"Explain how development of resistant bacteria such as MRSA can be minimised, limited to using antibiotics only when essential and ensuring treatment is completed"},{"text":"Explain why antibiotics kill bacteria, but do not affect viruses"}]},{"n":"15.3","title":"Misused drugs","core":[{"text":"Describe the effects of excessive alcohol consumption and abuse of heroin, limited to:\n– powerful depressant drugs\n– effect on reaction times and self-control\n– addiction and withdrawal symptoms\n– negative social implications, e.g. crime"},{"text":"State that injecting heroin can cause infections such as HIV"},{"text":"State that excessive alcohol consumption can cause liver damage"},{"text":"State that tobacco smoking can cause chronic obstructive pulmonary disease (COPD), lung cancer and coronary heart disease"},{"text":"Describe the effects on the gas exchange system of tobacco smoke and its major toxic components, limited to carbon monoxide, nicotine and tar"},{"text":"State that the liver is the site of break down of alcohol and other toxins"}],"supplement":[{"text":"Explain how heroin affects the nervous system, limited to its effect on the function of synapses"},{"text":"Discuss the evidence for the link between smoking and lung cancer"},{"text":"Discuss the use of hormones to improve sporting performance, limited to testosterone and anabolic steroids"}]}]},{"n":"16","title":"Reproduction","sections":[{"n":"16.1","title":"Asexual reproduction","core":[{"text":"Define asexual reproduction as a process resulting in the production of genetically identical offspring from one parent"},{"text":"Identify examples of asexual reproduction from information provided"}],"supplement":[{"text":"Discuss the advantages and disadvantages of asexual reproduction:\n– to a population of a species in the wild\n– to crop production"}]},{"n":"16.2","title":"Sexual reproduction","core":[{"text":"Define sexual reproduction as a process involving the fusion of the nuclei of two gametes (sex cells) to form a zygote and the production of offspring that are genetically different from each other"},{"text":"Define fertilisation as the fusion of gamete nuclei"}],"supplement":[{"text":"State that the nuclei of gametes are haploid and that the nucleus of a zygote is diploid"},{"text":"Discuss the advantages and disadvantages of sexual reproduction:\n– to a population of a species in the wild\n– to crop production"}]},{"n":"16.3","title":"Sexual reproduction in plants","core":[{"text":"Identify and draw, using a hand lens if necessary, the sepals, petals, stamens, filaments and anthers, carpels, style, stigma, ovary and ovules, of an insect-pollinated flower"},{"text":"State the functions of the sepals, petals, anthers, stigmas and ovaries"},{"text":"Use a hand lens to identify and describe the anthers and stigmas of a wind-pollinated flower"},{"text":"Distinguish between the pollen grains of insect-pollinated and wind-pollinated flowers"},{"text":"Define pollination as the transfer of pollen grains from the anther to the stigma"},{"text":"State that fertilisation occurs when a pollen nucleus fuses with a nucleus in an ovule"},{"text":"Describe the structural adaptations of insect-pollinated and wind-pollinated flowers"},{"text":"Investigate and state the environmental conditions that affect germination of seeds, limited to the requirement for water, oxygen and a suitable temperature"}],"supplement":[{"text":"Define self-pollination as the transfer of pollen grains from the anther of a flower to the stigma of the same flower or different flower on the same plant"},{"text":"Define cross-pollination as transfer of pollen grains from the anther of a flower to the stigma of a flower on a different plant of the same species"},{"text":"Discuss the implications to a species of self-pollination and cross-pollination in terms of variation, capacity to respond to changes in the environment and reliance on pollinators"},{"text":"Describe the growth of the pollen tube and its entry into the ovule followed by fertilisation (details of production of endosperm and development are not required)"}]},{"n":"16.4","title":"Sexual reproduction in humans","core":[{"text":"Identify and name on diagrams of the male reproductive system: the testes, scrotum, sperm ducts, prostate gland, urethra and penis, and state the functions of these parts"},{"text":"Identify and name on diagrams of the female reproductive system: the ovaries, oviducts, uterus, cervix and vagina, and state the functions of these parts"},{"text":"Describe fertilisation as the fusion of the nuclei from a male gamete (sperm) and a female gamete (egg cell/ovum)"},{"text":"State the adaptive features of sperm, limited to flagellum and the presence of enzymes"},{"text":"State the adaptive features of egg cells, limited to energy stores and a jelly coating that changes after fertilisation"},{"text":"State that in early development, the zygote forms an embryo which is a ball of cells that implants into the wall of the uterus"},{"text":"State the functions of the umbilical cord, placenta, amniotic sac and amniotic fluid"},{"text":"Outline the growth and development of the fetus in terms of increasing complexity in the early stages and increasing size towards the end of pregnancy"},{"text":"Describe the antenatal care of pregnant women, limited to special dietary needs and the harm from smoking and alcohol consumption"},{"text":"Outline the processes involved in labour and birth, limited to:\n– breaking of the amniotic sac\n– contraction of the muscles in the uterus wall\n– dilation of the cervix\n– passage through the vagina\n– tying and cutting the umbilical cord\n– delivery of the afterbirth"}],"supplement":[{"text":"Compare male and female gametes in terms of size, structure, motility and numbers"},{"text":"Explain the adaptive features of sperm, limited to flagellum, mitochondria and enzymes in the acrosome"},{"text":"Explain the adaptive features of egg cells, limited to energy stores and a jelly coating that changes after fertilisation"},{"text":"Describe the function of the placenta and umbilical cord in relation to exchange of dissolved nutrients, gases and excretory products and providing a barrier to toxins and pathogens (structural details are not required)"},{"text":"State that some toxins, e.g. nicotine, and pathogens, e.g. rubella virus, can pass across the placenta and affect the fetus"},{"text":"Discuss the advantages and disadvantages of breast-feeding compared with bottle-feeding using formula milk"}]},{"n":"16.5","title":"Sex hormones in humans","core":[{"text":"Describe the roles of testosterone and oestrogen in the development and regulation of secondary sexual characteristics during puberty"},{"text":"Describe the menstrual cycle in terms of changes in the ovaries and in the lining of the uterus"}],"supplement":[{"text":"Describe the sites of production of oestrogen and progesterone in the menstrual cycle and in pregnancy"},{"text":"Explain the role of hormones in controlling the menstrual cycle and pregnancy, limited to FSH, LH, progesterone and oestrogen"}]},{"n":"16.6","title":"Methods of birth control in humans","core":[{"text":"Outline the following methods of birth control:\n– natural, limited to abstinence, monitoring body temperature and cervical mucus\n– chemical, limited to IUD, IUS, contraceptive pill, implant and injection\n– barrier, limited to condom, femidom, diaphragm\n– surgical, limited to vasectomy and female sterilisation"}],"supplement":[{"text":"Outline the use of hormones in contraception and fertility treatments"},{"text":"Outline artificial insemination (AI)"},{"text":"Outline in vitro fertilisation (IVF)"},{"text":"Discuss the social implications of contraception and fertility treatments"}]},{"n":"16.7","title":"Sexually transmitted infections (STIs)","core":[{"text":"Define sexually transmitted infection as an infection that is transmitted via body fluids through sexual contact"},{"text":"State that human immunodeficiency virus (HIV) is an example of an STI"},{"text":"Explain how the spread of STIs is controlled"},{"text":"Describe the methods of transmission of HIV"},{"text":"State that HIV infection may lead to AIDS"}],"supplement":[{"text":"Outline how HIV affects the immune system, limited to decreased lymphocyte numbers and reduced ability to produce antibodies"}]}]},{"n":"17","title":"Inheritance","sections":[{"n":"17.1","title":"Inheritance","core":[{"text":"Define inheritance as the transmission of genetic information from generation to generation"}],"supplement":[]},{"n":"17.2","title":"Chromosomes, genes and proteins","core":[{"text":"Define chromosome as a thread-like structure of DNA, carrying genetic information in the form of genes"},{"text":"Define gene as a length of DNA that codes for a protein"},{"text":"Define allele as a version of a gene"},{"text":"Describe the inheritance of sex in humans with reference to XX and XY chromosomes"}],"supplement":[{"text":"Explain that the sequence of bases in a gene is the genetic code for putting together amino acids in the correct order to make a specific protein (knowledge of the details of nucleotide structure is not required)"},{"text":"Explain that DNA controls cell function by controlling the production of proteins (some of which are enzymes), antibodies and receptors for neurotransmitters"},{"text":"Explain how a protein is made, limited to:\n– the gene coding for the protein remains in the nucleus\n– mRNA molecules carry a copy of the gene to the cytoplasm\n– the mRNA passes through ribosomes\n– the ribosome assembles amino acids into protein molecules\n– the specific order of amino acids is determined by the sequence of bases in the mRNA (knowledge of the details of transcription or translation is not required)"},{"text":"Explain that all body cells in an organism contain the same genes, but many genes in a particular cell are not expressed because the cell only makes the specific proteins it needs"},{"text":"Define a haploid nucleus as a nucleus containing a single set of unpaired chromosomes, e.g. in gametes"},{"text":"Define a diploid nucleus as a nucleus containing two sets of chromosomes, e.g. in body cells"},{"text":"State that in a diploid cell, there is a pair of each type of chromosome and in a human diploid cell there are 23 pairs"}]},{"n":"17.3","title":"Mitosis","core":[{"text":"Define mitosis as nuclear division giving rise to genetically identical cells (details of stages are not required)"},{"text":"State the role of mitosis in growth, repair of damaged tissues, replacement of cells and asexual reproduction"}],"supplement":[{"text":"State that the exact duplication of chromosomes occurs before mitosis"},{"text":"State that during mitosis, the copies of chromosomes separate, maintaining the chromosome number (details of stages of mitosis are not required)"},{"text":"Describe stem cells as unspecialised cells that divide by mitosis to produce daughter cells that can become specialised for specific functions"}]},{"n":"17.4","title":"Meiosis","core":[{"text":"Define meiosis as nuclear division giving rise to cells that are genetically different (details of stages are not required)"},{"text":"State that meiosis is involved in the production of gametes"}],"supplement":[{"text":"Define meiosis as reduction division in which the chromosome number is halved from diploid to haploid resulting in genetically different cells (details of stages are not required)"},{"text":"Explain how meiosis produces variation by forming new combinations of maternal and paternal chromosomes (specific details are not required)"}]},{"n":"17.5","title":"Monohybrid inheritance","core":[{"text":"Define genotype as the genetic make-up of an organism in terms of the alleles present"},{"text":"Define phenotype as the observable features of an organism"},{"text":"Define homozygous as having two identical alleles of a particular gene"},{"text":"State that two identical homozygous individuals that breed together will be pure-breeding"},{"text":"Define heterozygous as having two different alleles of a particular gene"},{"text":"State that a heterozygous individual will not be pure-breeding"},{"text":"Define dominant as an allele that is expressed if it is present"},{"text":"Define recessive as an allele that is only expressed when there is no dominant allele of the gene present"},{"text":"Interpret pedigree diagrams for the inheritance of a given characteristic"},{"text":"Use genetic diagrams to predict the results of monohybrid crosses and calculate phenotypic ratios, limited to 1:1 and 3:1 ratios"},{"text":"Use Punnett squares in crosses which result in more than one genotype to work out and show the possible different genotypes"}],"supplement":[{"text":"Explain how to use a test cross to identify an unknown genotype"},{"text":"Explain codominance by reference to the inheritance of ABO blood groups – phenotypes being A, B, AB and O blood groups and alleles being IA, IB and IO"},{"text":"Define a sex-linked characteristic as a characteristic in which the gene responsible is located on a sex chromosome and that this makes it more common in one sex than in the other"},{"text":"Describe colour blindness as an example of sex linkage"},{"text":"Use genetic diagrams to predict the results of monohybrid crosses involving codominance or sex linkage and calculate phenotypic ratios"}]}]},{"n":"18","title":"Variation and selection","sections":[{"n":"18.1","title":"Variation","core":[{"text":"Define variation as differences between individuals of the same species"},{"text":"Distinguish between phenotypic variation and genetic variation"},{"text":"State that continuous variation results in a range of phenotypes between two extremes, e.g. height in humans"},{"text":"State that discontinuous variation results in a limited number of phenotypes with no intermediates, e.g. tongue rolling"},{"text":"Record and present the results of investigations into continuous and discontinuous variation"},{"text":"Define mutation as genetic change"},{"text":"State that mutation is the way in which new alleles are formed"},{"text":"State that ionising radiation and some chemicals increase the rate of mutation"}],"supplement":[{"text":"State that phenotypic variation is caused by both genetic and environmental factors"},{"text":"State that discontinuous variation is mostly caused by genes alone, e.g. A, B, AB and O blood groups in humans"},{"text":"Define gene mutation as a change in the base sequence of DNA"},{"text":"Describe the symptoms of sickle cell anaemia"},{"text":"Explain how a change in the base sequence of the gene for haemoglobin results in abnormal haemoglobin and sickle-shaped red blood cells"},{"text":"Use genetic diagrams to show how sickle cell anaemia is inherited"},{"text":"State that people who are heterozygous (HbS HbA) for the sickle cell allele have a resistance to malaria"},{"text":"Explain the distribution of the sickle cell allele in human populations with reference to the distribution of malaria (Teaching of human inherited conditions should be done with sensitivity at all times.)"}]},{"n":"18.2","title":"Adaptive features","core":[{"text":"Define adaptive feature as an inherited feature that helps an organism to survive and reproduce in its environment"},{"text":"Interpret images or other information about a species to describe its adaptive features"}],"supplement":[{"text":"Define adaptive feature as the inherited functional features of an organism that increase its fitness"},{"text":"Define fitness as the probability of an organism surviving and reproducing in the environment in which it is found"},{"text":"Explain the adaptive features of hydrophytes and xerophytes to their environments"}]},{"n":"18.3","title":"Selection","core":[{"text":"Describe natural selection with reference to:\n– variation within populations\n– production of many offspring\n– competition for resources\n– struggle for survival\n– reproduction by individuals that are better adapted to the environment than others\n– passing on of their alleles to the next generation"},{"text":"Describe selective breeding with reference to:\n– selection by humans of individuals with desirable features\n– crossing these individuals to produce the next generation\n– selection of offspring showing the desirable features"}],"supplement":[{"text":"Describe evolution as the change in adaptive features of a population over time as the result of natural selection"},{"text":"Define the process of adaptation as the process, resulting from natural selection, by which populations become more suited to their environment over many generations"},{"text":"Describe the development of strains of antibiotic resistant bacteria as an example of evolution by natural selection"},{"text":"State the differences between natural and artificial selection"},{"text":"Outline how selective breeding by artificial selection is carried out over many generations to improve crop plants and domesticated animals"}]}]},{"n":"19","title":"Organisms and their environment","sections":[{"n":"19.1","title":"Energy flow","core":[{"text":"State that the Sun is the principal source of energy input to biological systems"}],"supplement":[{"text":"Describe the flow of energy through living organisms including light energy from the Sun and chemical energy in organisms and its eventual transfer to the environment"}]},{"n":"19.2","title":"Food chains and food webs","core":[{"text":"Define a food chain as showing the transfer of energy from one organism to the next, beginning with a producer"},{"text":"State that energy is transferred between organisms in a food chain by ingestion"},{"text":"Construct simple food chains"},{"text":"Define a food web as a network of interconnected food chains"},{"text":"Define producer as an organism that makes its own organic nutrients, usually using energy from sunlight, through photosynthesis"},{"text":"Define consumer as an organism that gets its energy by feeding on other organisms"},{"text":"State that consumers may be classed as primary, secondary and tertiary according to their position in a food chain"},{"text":"Define herbivore as an animal that gets its energy by eating plants"},{"text":"Define carnivore as an animal that gets its energy by eating other animals"},{"text":"Define decomposer as an organism that gets its energy from dead or waste organic material"},{"text":"Interpret food chains and food webs in terms of identifying producers and consumers"},{"text":"Use food chains and food webs to describe the impacts humans have through over-harvesting of food species and through introducing foreign species to a habitat"},{"text":"Draw, describe and interpret pyramids of numbers"}],"supplement":[{"text":"Describe how energy is transferred between trophic levels"},{"text":"Define trophic level as the position of an organism in a food chain, food web, pyramid of numbers or pyramid of biomass"},{"text":"Explain why the transfer of energy from one trophic level to another is inefficient"},{"text":"Explain why food chains usually have fewer than five trophic levels continued"},{"text":"Explain why there is a greater efficiency in supplying plants as human food, and that there is a relative inefficiency in feeding crop plants to livestock that will be used as food"},{"text":"Identify producers, primary consumers, secondary consumers, tertiary consumers and quaternary consumers as the trophic levels in food webs, food chains, pyramids of numbers and pyramids of biomass"},{"text":"Draw, describe and interpret pyramids of biomass"},{"text":"Discuss the advantages of using a pyramid of biomass rather than a pyramid of numbers to represent a food chain"}]},{"n":"19.3","title":"Nutrient cycles","core":[{"text":"Describe the carbon cycle, limited to photosynthesis, respiration, feeding, decomposition, fossilisation and combustion"},{"text":"Discuss the effects of the combustion of fossil fuels and the cutting down of forests on the carbon dioxide concentrations in the atmosphere"},{"text":"Describe the water cycle, limited to evaporation, transpiration, condensation and precipitation"}],"supplement":[{"text":"Describe the nitrogen cycle in terms of:\n– decomposition of plant and animal protein to ammonium ions\n– nitrification\n– nitrogen fixation by lightning and bacteria\n– absorption of nitrate ions by plants\n– production of amino acids and proteins\n– feeding and digestion of proteins\n– deamination\n– denitrification"},{"text":"State the roles of microorganisms in the nitrogen cycle, limited to decomposition, nitrification, nitrogen fixation and denitrification (generic names of individual bacteria, e.g. Rhizobium, are not required)"}]},{"n":"19.4","title":"Population size","core":[{"text":"Define population as a group of organisms of one species, living in the same area, at the same time"},{"text":"Identify and state the factors affecting the rate of population growth for a population of an organism, limited to food supply, predation and disease"},{"text":"Discuss the increase in human population size over the past 250 years and its social and environmental implications"},{"text":"Interpret graphs and diagrams of human population growth"}],"supplement":[{"text":"Define community as all of the populations of different species in an ecosystem"},{"text":"Define ecosystem as a unit containing the community of organisms and their environment, interacting together, e.g. a decomposing log, or a lake"},{"text":"Identify the lag, exponential (log), stationary and death phases in the sigmoid population growth curve for a population growing in an environment with limited resources"},{"text":"Explain the factors that lead to each phase in the sigmoid curve of population growth, making reference, where appropriate, to the role of limiting factors"}]}]},{"n":"20","title":"Biotechnology and genetic engineering","sections":[{"n":"20.1","title":"Biotechnology and genetic engineering","core":[{"text":"State that bacteria are useful in biotechnology and genetic engineering due to their rapid reproduction rate and their ability to make complex molecules"}],"supplement":[{"text":"Discuss why bacteria are useful in biotechnology and genetic engineering, limited to:\n– lack of ethical concerns over their manipulation and growth\n– genetic code shared with all other organisms\n– presence of plasmids"}]},{"n":"20.2","title":"Biotechnology","core":[{"text":"Describe the role of anaerobic respiration in yeast during production of ethanol for biofuels"},{"text":"Describe the role of anaerobic respiration in yeast during bread-making"},{"text":"Investigate and describe the use of pectinase in fruit juice production"},{"text":"Investigate and describe the use of biological washing powders that contain enzymes"}],"supplement":[{"text":"Investigate and explain the use of lactase to produce lactose-free milk"},{"text":"Describe the role of the fungus Penicillium in the production of the antibiotic penicillin"},{"text":"Explain how fermenters are used in the production of penicillin"}]},{"n":"20.3","title":"Genetic engineering","core":[{"text":"Define genetic engineering as changing the genetic material of an organism by removing, changing or inserting individual genes"},{"text":"State examples of genetic engineering:\n– the insertion of human genes into bacteria to produce human insulin\n– the insertion of genes into crop plants to confer resistance to herbicides\n– the insertion of genes into crop plants to confer resistance to insect pests\n– the insertion of genes into crop plants to provide additional vitamins"}],"supplement":[{"text":"Outline genetic engineering using bacterial production of a human protein as an example, limited to:\n– isolation of the DNA making up a human gene using restriction enzymes, forming sticky ends\n– cutting of bacterial plasmid DNA with the same restriction enzymes, forming complementary sticky ends\n– insertion of human DNA into bacterial plasmid DNA using DNA ligase to form a recombinant plasmid\n– insertion of plasmid into bacteria (specific detail is not required)\n– replication of bacteria containing recombinant plasmids which make human protein as they express the gene"},{"text":"Discuss the advantages and disadvantages of genetically modifying crops, such as soya, maize and rice"}]}]},{"n":"21","title":"Human influences on ecosystems","sections":[{"n":"21.1","title":"Food supply","core":[{"text":"State how modern technology has resulted in increased food production in terms of:\n– agricultural machinery to use larger areas of land and improve efficiency\n– chemical fertilisers to improve yields\n– insecticides to improve quality and yield\n– herbicides to reduce competition with weeds\n– selective breeding to improve production by crop plants and livestock, e.g. cattle, fish and poultry"},{"text":"Describe the negative impacts to an ecosystem of large-scale monocultures of crop plants"},{"text":"Describe the negative impacts to an ecosystem of intensive livestock production"}],"supplement":[{"text":"Discuss the social, environmental and economic implications of providing sufficient food for an increasing human global population"},{"text":"Discuss the problems which contribute to famine including unequal distribution of food, drought and flooding, increasing population and poverty"}]},{"n":"21.2","title":"Habitat destruction","core":[{"text":"Describe the reasons for habitat destruction, limited to:\n– increased area for food crop growth, livestock production and housing\n– extraction of natural resources\n– marine pollution"},{"text":"State that through altering food webs and food chains, humans can have a negative impact on habitats"},{"text":"List the undesirable effects of deforestation as an example of habitat destruction, to include extinction, loss of soil, flooding and increase of carbon dioxide in the atmosphere"}],"supplement":[{"text":"Explain the undesirable effects of deforestation on the environment"}]},{"n":"21.3","title":"Pollution","core":[{"text":"State the sources and effects of pollution of land and water, e.g. rivers, lakes and the sea, by insecticides, herbicides and by nuclear fall-out"},{"text":"State the sources and effects of pollution of water (rivers, lakes and the sea) by chemical waste, discarded rubbish, untreated sewage and fertilisers"},{"text":"State the sources and effects of pollution of the air by methane and carbon dioxide, limited to the enhanced greenhouse effect and climate change"}],"supplement":[{"text":"Explain the process of eutrophication of water in terms of:\n– increased availability of nitrate and other ions\n– increased growth of producers\n– increased decomposition after death of producers\n– increased aerobic respiration by decomposers\n– reduction in dissolved oxygen\n– death of organisms requiring dissolved oxygen in water"},{"text":"Discuss the effects of non-biodegradable plastics in the environment, in both aquatic and terrestrial ecosystems"},{"text":"Discuss the causes and effects on the environment of acid rain"},{"text":"State the measures that are taken to reduce sulfur dioxide pollution and reduce the impact of acid rain"},{"text":"Explain how increases in carbon dioxide and methane concentrations in the atmosphere cause an enhanced greenhouse effect that leads to climate change"},{"text":"Describe the negative impacts of female contraceptive hormones in water courses, limited to reduced sperm count in men and feminisation of aquatic organisms"}]},{"n":"21.4","title":"Conservation","core":[{"text":"Define a sustainable resource as one which is produced as rapidly as it is removed from the environment so that it does not run out"},{"text":"Explain the need to conserve non-renewable resources, limited to fossil fuels"},{"text":"State that some resources can be maintained, limited to forests and fish stocks"},{"text":"State that products can be reused or recycled, limited to paper, glass, plastic and metal"},{"text":"Outline how sewage is treated to make the water that it contains safe to return to the environment or for human use"},{"text":"Explain why organisms become endangered or extinct, limited to climate change, habitat destruction, hunting, pollution and introduced species"},{"text":"Describe how endangered species can be conserved, limited to monitoring and protecting species and habitats, education, captive breeding programmes and seed banks"}],"supplement":[{"text":"Define the term sustainable development as development providing for the needs of an increasing human population without harming the environment"},{"text":"Explain how forests and fish stocks can be sustained using education, legal quotas and restocking"},{"text":"Explain that sustainable development requires:\n– management of conflicting demands\n– planning and cooperation at local, national and international levels"},{"text":"Explain the risks to a species if the population size drops, reducing variation (knowledge of genetic drift is not required)"},{"text":"Explain reasons for conservation programmes, to include:\n– reducing extinction\n– protecting vulnerable environments\n– maintaining ecosystem functions, limited to nutrient cycling and resource provision, e.g. food, drugs, fuel and genes"}]}]}]},{"id":"2020-2021","label":"2020–2021","until":"2021","numbered":false,"source":{"title":"Cambridge IGCSE Biology 0610, for examination in 2020 and 2021 (version 2)","url":"https://www.cambridgeinternational.org/Images/414443-2020-2021-syllabus.pdf"},"topics":[{"n":"1","title":"Characteristics and classification of living organisms","sections":[{"n":"1.1","title":"Characteristics of living organisms","core":[{"text":"Describe the characteristics of living organisms by defining the terms:\n– movement as an action by an organism causing a change of position or place\n– respiration as the chemical reactions in cells that break down nutrient molecules and release energy\n– sensitivity as the ability to detect and respond to changes in the environment\n– growth as a permanent increase in size\n– reproduction as the processes that make more of the same kind of organism\n– excretion as removal from organisms of toxic materials and substances in excess of requirements\n– nutrition as taking in of materials for energy, growth and development"}],"supplement":[{"text":"Define the terms:\n– movement as an action by an organism or part of an organism causing a change of position or place\n– respiration as the chemical reactions in cells that break down nutrient molecules and release energy for metabolism\n– sensitivity as the ability to detect or sense stimuli in the internal or external environment and to make appropriate responses\n– growth as a permanent increase in size and dry mass by an increase in cell number or cell size or both\n– excretion as removal from organisms of the waste products of metabolism (chemical reactions in cells including respiration), toxic materials, and substances in excess of requirements\n– nutrition as taking in of materials for energy, growth and development; plants require light, carbon dioxide, water and ions; animals need organic compounds and ions and usually need water"}]},{"n":"1.2","title":"Concept and use of a classification system","core":[{"text":"State that organisms can be classified into groups by the features that they share"},{"text":"Define species as a group of organisms that can reproduce to produce fertile offspring"},{"text":"Define and describe the binomial system of naming species as an internationally agreed system in which the scientific name of an organism is made up of two parts showing the genus and species"}],"supplement":[{"text":"Explain that classification systems aim to reflect evolutionary relationships"},{"text":"Explain that classification is traditionally based on studies of morphology and anatomy"},{"text":"Explain that the sequences of bases in DNA and of amino acids in proteins are used as a more accurate means of classification"},{"text":"Explain that organisms which share a more recent ancestor (are more closely related) have base sequences in DNA that are more similar than those that share only a distant ancestor"}]},{"n":"1.3","title":"Features of organisms","core":[{"text":"List the features in the cells of all living organisms, limited to cytoplasm, cell membrane and DNA as genetic material"},{"text":"List the main features used to place animals and plants into the appropriate kingdoms"},{"text":"List the main features used to place organisms into groups within the animal kingdom, limited to: –– the main groups of vertebrates: mammals, birds, reptiles, amphibians, fish –– the main groups of arthropods: myriapods, insects, arachnids, crustaceans"}],"supplement":[{"text":"List the features in the cells of all living organisms, limited to ribosomes for protein synthesis and enzymes involved in respiration"},{"text":"List the main features used to place all organisms into one of the five kingdoms: Animal, Plant, Fungus, Prokaryote, Protoctist"},{"text":"List the main features used to place organisms into groups within the plant kingdom, limited to ferns and flowering plants (dicotyledons and monocotyledons)"},{"text":"List the features of viruses, limited to protein coat and genetic material"}]},{"n":"1.4","title":"Dichotomous keys","core":[{"text":"Construct and use simple dichotomous keys based on easily identifiable features"}],"supplement":[]}]},{"n":"2","title":"Organisation of the organism","sections":[{"n":"2.1","title":"Cell structure and organisation","core":[{"text":"Describe and compare the structure of a plant cell with an animal cell, as seen under a light microscope, limited to cell wall, nucleus, cytoplasm, chloroplasts, vacuoles and location of the cell membrane"},{"text":"State the functions of the structures seen under the light microscope in the plant cell and in the animal cell"}],"supplement":[{"text":"State that the cytoplasm of all cells contains structures, limited to ribosomes on rough endoplasmic reticulum and vesicles"},{"text":"State that almost all cells, except prokaryotes, have mitochondria and rough endoplasmic reticulum"},{"text":"Identify mitochondria and rough endoplasmic reticulum in diagrams and images of cells"},{"text":"State that aerobic respiration occurs in mitochondria"},{"text":"State that cells with high rates of metabolism require large numbers of mitochondria to provide sufficient energy"}]},{"n":"2.2","title":"Levels of organisation","core":[{"text":"Relate the structure of the following to their functions:\n– ciliated cells – movement of mucus in the trachea and bronchi\n– root hair cells – absorption\n– xylem vessels – conduction and support\n– palisade mesophyll cells – photosynthesis\n– nerve cells – conduction of impulses\n– red blood cells – transport of oxygen\n– sperm and egg cells – reproduction"},{"text":"Define tissue as a group of cells with similar structures, working together to perform a shared function"},{"text":"Define organ as a structure made up of a group of tissues, working together to perform specific functions"},{"text":"Define organ system as a group of organs with related functions, working together to perform body functions"},{"text":"State examples of tissues, organs and organ systems from sections 6 to 16"},{"text":"Identify the different levels of organisation in drawings, diagrams and images of familiar material"}],"supplement":[{"text":"Identify the different levels of organisation in drawings, diagrams and images of unfamiliar material"}]},{"n":"2.3","title":"Size of specimens","core":[{"text":"Calculate magnification and size of biological specimens using millimetres as units"}],"supplement":[{"text":"Calculate magnification and size of biological specimens using millimetres and micrometres as units"}]}]},{"n":"3","title":"Movement in and out of cells","sections":[{"n":"3.1","title":"Diffusion","core":[{"text":"Define diffusion as the net movement of particles from a region of their higher concentration to a region of their lower concentration down a concentration gradient, as a result of their random movement"},{"text":"Describe the importance of diffusion of gases and solutes"},{"text":"State that substances move into and out of cells by diffusion through the cell membrane"}],"supplement":[{"text":"State that the energy for diffusion comes from the kinetic energy of random movement of molecules and ions"},{"text":"Investigate the factors that influence diffusion, limited to surface area, temperature, concentration gradients and distance"}]},{"n":"3.2","title":"Osmosis","core":[{"text":"State that water diffuses through partially permeable membranes by osmosis"},{"text":"State that water moves in and out of cells by osmosis through the cell membrane"},{"text":"Investigate and describe the effects on plant tissues of immersing them in solutions of different concentrations"},{"text":"State that plants are supported by the pressure of water inside the cells pressing outwards on the cell wall"}],"supplement":[{"text":"Define osmosis as the net movement of water molecules from a region of higher water potential (dilute solution) to a region of lower water potential (concentrated solution), through a partially permeable membrane"},{"text":"Explain the effects on plant tissues of immersing them in solutions of different concentrations by using the terms turgid, turgor pressure, plasmolysis and flaccid"},{"text":"Explain the importance of water potential and osmosis in the uptake of water by plants"},{"text":"Explain the importance of water potential and osmosis on animal cells and tissues"},{"text":"Explain how plants are supported by the turgor pressure within cells, in terms of water pressure acting against an inelastic cell wall"}]},{"n":"3.3","title":"Active transport","core":[{"text":"Define active transport as the movement of particles through a cell membrane from a region of lower concentration to a region of higher concentration using energy from respiration"}],"supplement":[{"text":"Discuss the importance of active transport as a process for movement across membranes:\n– e.g. ion uptake by root hairs and uptake of glucose by epithelial cells of villi and kidney tubules"},{"text":"Explain how protein molecules move particles across a membrane during active transport"}]}]},{"n":"4","title":"Biological molecules","sections":[{"n":"4.1","title":"Biological molecules","core":[{"text":"List the chemical elements that make up:\n– carbohydrates\n– fats\n– proteins"},{"text":"State that large molecules are made from smaller molecules, limited to:\n– starch and glycogen from glucose\n– cellulose from glucose\n– proteins from amino acids\n– fats and oils from fatty acids and glycerol"},{"text":"Describe the use of:\n– iodine solution to test for starch\n– Benedict’s solution to test for reducing sugars\n– biuret test for proteins\n– ethanol emulsion test for fats and oils\n– DCPIP test for vitamin C"},{"text":"State that water is important as a solvent"}],"supplement":[{"text":"Explain that different sequences of amino acids give different shapes to protein molecules"},{"text":"Relate the shape and structure of protein molecules to their function, limited to the active site of enzymes and the binding site of antibodies continued"},{"text":"Describe the structure of DNA as:\n– two strands coiled together to form a double helix\n– each strand contains chemicals called bases\n– cross-links between the strands are formed by pairs of bases\n– the bases always pair up in the same way: A with T, and C with G (full names are not required)"},{"text":"Describe the roles of water as a solvent in organisms with respect to digestion, excretion and transport"}]}]},{"n":"5","title":"Enzymes","sections":[{"n":"5.1","title":"Enzymes","core":[{"text":"Define the term catalyst as a substance that increases the rate of a chemical reaction and is not changed by the reaction"},{"text":"Define enzymes as proteins that function as biological catalysts"},{"text":"Describe why enzymes are important in all living organisms in terms of reaction speed necessary to sustain life"},{"text":"Describe enzyme action with reference to the complementary shape of an enzyme and its substrate and the formation of a product (knowledge of the term active site is not required)"},{"text":"Investigate and describe the effect of changes in temperature and pH on enzyme activity"}],"supplement":[{"text":"Explain enzyme action with reference to the active site, enzyme-substrate complex, substrate and product"},{"text":"Explain the specificity of enzymes in terms of the complementary shape and fit of the active site with the substrate"},{"text":"Explain the effect of changes in temperature on enzyme activity in terms of kinetic energy, shape and fit, frequency of effective collisions and denaturation"},{"text":"Explain the effect of changes in pH on enzyme activity in terms of shape and fit and denaturation"}]}]},{"n":"6","title":"Plant nutrition","sections":[{"n":"6.1","title":"Photosynthesis","core":[{"text":"Define photosynthesis as the process by which plants manufacture carbohydrates from raw materials using energy from light"},{"text":"State the word equation for photosynthesis: carbon dioxide + water → glucose + oxygen, in the presence of light and chlorophyll"},{"text":"Investigate the necessity for chlorophyll, light and carbon dioxide for photosynthesis, using appropriate controls"},{"text":"Investigate and describe the effects of varying light intensity, carbon dioxide concentration and temperature on the rate of photosynthesis, e.g. in submerged aquatic plants"}],"supplement":[{"text":"State the balanced chemical equation for photosynthesis light 6CO2 + 6H2O C6H12O6 + 6O2 chlorophyll"},{"text":"Explain that chlorophyll transfers light energy into chemical energy in molecules, for the synthesis of carbohydrates"},{"text":"Outline the subsequent use and storage of the carbohydrates made in photosynthesis"},{"text":"Define the term limiting factor as something present in the environment in such short supply that it restricts life processes"},{"text":"Identify and explain the limiting factors of photosynthesis in different environmental conditions"},{"text":"Describe the use of carbon dioxide enrichment, optimum light and optimum temperatures in glasshouses in temperate and tropical countries"},{"text":"Use hydrogencarbonate indicator solution to investigate the effect of gas exchange of an aquatic plant kept in the light and in the dark"}]},{"n":"6.2","title":"Leaf structure","core":[{"text":"Identify chloroplasts, cuticle, guard cells and stomata, upper and lower epidermis, palisade mesophyll, spongy mesophyll, vascular bundles, xylem and phloem in leaves of a dicotyledonous plant"}],"supplement":[{"text":"Explain how the internal structure of a leaf is adapted for photosynthesis"}]},{"n":"6.3","title":"Mineral requirements","core":[{"text":"Describe the importance of:\n– nitrate ions for making amino acids\n– magnesium ions for making chlorophyll"}],"supplement":[{"text":"Explain the effects of nitrate ion and magnesium ion deficiency on plant growth"}]}]},{"n":"7","title":"Human nutrition","sections":[{"n":"7.1","title":"Diet","core":[{"text":"State what is meant by the term balanced diet for humans"},{"text":"Explain how age, gender and activity affect the dietary needs of humans including during pregnancy and whilst breast-feeding"},{"text":"Describe the effects of malnutrition in relation to starvation, constipation, coronary heart disease, obesity and scurvy"},{"text":"List the principal sources of, and describe the dietary importance of:\n– carbohydrates\n– fats\n– proteins\n– vitamins, limited to C and D\n– mineral salts, limited to calcium and iron\n– fibre (roughage)\n– water"}],"supplement":[{"text":"Explain the causes and effects of vitamin D and iron deficiencies"},{"text":"Explain the causes and effects of protein-energy malnutrition, e.g. kwashiorkor and marasmus"}]},{"n":"7.2","title":"Alimentary canal","core":[{"text":"Define ingestion as the taking of substances, e.g. food and drink, into the body through the mouth"},{"text":"Define mechanical digestion as the breakdown of food into smaller pieces without chemical change to the food molecules"},{"text":"Define chemical digestion as the breakdown of large, insoluble molecules into small, soluble molecules"},{"text":"Define absorption as the movement of small food molecules and ions through the wall of the intestine into the blood"},{"text":"Define assimilation as the movement of digested food molecules into the cells of the body where they are used, becoming part of the cells"},{"text":"Define egestion as the passing out of food that has not been digested or absorbed, as faeces, through the anus"},{"text":"Describe diarrhoea as the loss of watery faeces"},{"text":"Outline the treatment of diarrhoea using oral rehydration therapy"},{"text":"Describe cholera as a disease caused by a bacterium"},{"text":"Identify the main regions of the alimentary canal and associated organs, limited to mouth, salivary glands, oesophagus, stomach, small intestine (duodenum and ileum), pancreas, liver, gall bladder and large intestine (colon, rectum, anus)"},{"text":"Describe the functions of the regions of the alimentary canal listed above, in relation to ingestion, digestion, absorption, assimilation and egestion of food"}],"supplement":[{"text":"Explain that the cholera bacterium produces a toxin that causes secretion of chloride ions into the small intestine, causing osmotic movement of water into the gut, causing diarrhoea, dehydration and loss of salts from blood"}]},{"n":"7.3","title":"Mechanical digestion","core":[{"text":"Identify the types of human teeth (incisors, canines, premolars and molars)"},{"text":"Describe the structure of human teeth, limited to enamel, dentine, pulp, nerves and cement, as well as the gums"},{"text":"Describe the functions of the types of human teeth in mechanical digestion of food"},{"text":"State the causes of dental decay in terms of a coating of bacteria and food on teeth, the bacteria respiring sugars in the food, producing acid which dissolves the enamel and dentine"},{"text":"Describe the proper care of teeth in terms of diet and regular brushing"}],"supplement":[]},{"n":"7.4","title":"Chemical digestion","core":[{"text":"State the significance of chemical digestion in the alimentary canal in producing small, soluble molecules that can be absorbed"},{"text":"State the functions of enzymes as follows:\n– amylase breaks down starch to simpler sugars\n– protease breaks down protein to amino acids\n– lipase breaks down fats to fatty acids and glycerol"},{"text":"State where, in the alimentary canal, amylase, protease and lipase are secreted"},{"text":"State the functions of the hydrochloric acid in gastric juice, limited to killing bacteria in food and giving an acid pH for enzymes"}],"supplement":[{"text":"Describe the digestion of starch in the alimentary canal:\n– amylase is secreted into the alimentary canal and breaks down starch to maltose\n– maltose is broken down by maltase to glucose on the membranes of the epithelium lining the small intestine"},{"text":"Describe pepsin and trypsin as two protease enzymes that function in different parts of the alimentary canal:\n– pepsin in the stomach\n– trypsin in the small intestine"},{"text":"Explain the functions of the hydrochloric acid in gastric juice, limited to the low pH:\n– denaturing enzymes in harmful microorganisms in food\n– giving the optimum pH for pepsin activity"},{"text":"Outline the role of bile in neutralising the acidic mixture of food and gastric juices entering the duodenum from the stomach, to provide a suitable pH for enzyme action"},{"text":"Outline the role of bile in emulsifying fats to increase the surface area for the chemical digestion of fat to fatty acids and glycerol by lipase"}]},{"n":"7.5","title":"Absorption","core":[{"text":"Identify the small intestine as the region for the absorption of digested food"},{"text":"State that water is absorbed in both the small intestine and the colon, but that most absorption of water happens in the small intestine"}],"supplement":[{"text":"Explain the significance of villi and microvilli in increasing the internal surface area of the small intestine"},{"text":"Describe the structure of a villus"},{"text":"Describe the roles of capillaries and lacteals in villi"}]}]},{"n":"8","title":"Transport in plants","sections":[{"n":"8.1","title":"Transport in plants","core":[{"text":"State the functions of xylem and phloem"},{"text":"Identify the position of xylem and phloem as seen in sections of roots, stems and leaves, limited to non-woody dicotyledonous plants"}],"supplement":[]},{"n":"8.2","title":"Water uptake","core":[{"text":"Identify root hair cells, as seen under the light microscope, and state their functions"},{"text":"State the pathway taken by water through root, stem and leaf as root hair cell, root cortex cells, xylem and mesophyll cells"},{"text":"Investigate, using a suitable stain, the pathway of water through the above-ground parts of a plant"}],"supplement":[{"text":"Explain that the large surface area of root hairs increases the rate of the absorption of water by osmosis and ions by active transport"}]},{"n":"8.3","title":"Transpiration","core":[{"text":"State that water is transported from the roots to leaves through the xylem vessels"},{"text":"Define transpiration as loss of water vapour from plant leaves by evaporation of water at the surfaces of the mesophyll cells followed by diffusion of water vapour through the stomata"},{"text":"Investigate and describe the effects of variation of temperature and humidity on transpiration rate"}],"supplement":[{"text":"Explain how water vapour loss is related to the large surface area of cell surfaces, interconnecting air spaces and stomata"},{"text":"Explain the mechanism by which water moves upwards in the xylem in terms of a transpiration pull that draws up a column of water molecules, held together by cohesion"},{"text":"Explain how and why wilting occurs"},{"text":"Explain the effects of variation of temperature and humidity on transpiration rate"}]},{"n":"8.4","title":"Translocation","core":[],"supplement":[{"text":"Define translocation in terms of the movement of sucrose and amino acids in phloem:\n– from regions of production (source)\n– to regions of storage OR to regions where they are used in respiration or growth (sink)"},{"text":"Explain that some parts of a plant may act as a source and a sink at different times during the life of a plant"}]}]},{"n":"9","title":"Transport in animals","sections":[{"n":"9.1","title":"Transport in animals","core":[{"text":"Describe the circulatory system as a system of blood vessels with a pump and valves to ensure one-way flow of blood"}],"supplement":[{"text":"Describe the single circulation of a fish"},{"text":"Describe the double circulation of a mammal"},{"text":"Explain the advantages of a double circulation"}]},{"n":"9.2","title":"Heart","core":[{"text":"Name and identify the structures of the mammalian heart, limited to the muscular wall, the septum, the left and right ventricles and atria, one-way valves and coronary arteries"},{"text":"State that blood is pumped away from the heart into arteries and returns to the heart in veins"},{"text":"State that the activity of the heart may be monitored by ECG, pulse rate and listening to sounds of valves closing"},{"text":"Investigate and state the effect of physical activity on the pulse rate"},{"text":"Describe coronary heart disease in terms of the blockage of coronary arteries and state the possible risk factors as diet, stress, smoking, genetic predisposition, age and gender"}],"supplement":[{"text":"Name and identify the atrioventricular and semilunar valves in the mammalian heart"},{"text":"Explain the relative thickness:\n– of the muscle wall of the left and right ventricles\n– of the muscle wall of the atria compared to that of the ventricles"},{"text":"Explain the importance of the septum in separating oxygenated and deoxygenated blood"},{"text":"Describe the functioning of the heart in terms of the contraction of muscles of the atria and ventricles and the action of the valves"},{"text":"Explain the effect of physical activity on the heart rate"},{"text":"Discuss the roles of diet and exercise in the prevention of coronary heart disease"},{"text":"Describe ways in which coronary heart disease may be treated, limited to drug treatment with aspirin and surgery (stents, angioplasty and by-pass)"}]},{"n":"9.3","title":"Blood and lymphatic vessels","core":[{"text":"Describe the structure and functions of arteries, veins and capillaries"},{"text":"Name the main blood vessels to and from the:\n– heart, limited to vena cava, aorta, pulmonary artery and pulmonary vein\n– lungs, limited to the pulmonary artery and pulmonary vein\n– kidney, limited to the renal artery and renal vein"}],"supplement":[{"text":"Explain how the structures of arteries, veins and capillaries are adapted for their functions"},{"text":"State the function of arterioles, venules and shunt vessels"},{"text":"Outline the lymphatic system in terms of lymphatic vessels and lymph nodes"},{"text":"Describe the function of the lymphatic system in the circulation of body fluids and the protection of the body from infection"}]},{"n":"9.4","title":"Blood","core":[{"text":"List the components of blood as red blood cells, white blood cells, platelets and plasma"},{"text":"Identify red and white blood cells, as seen under the light microscope, on prepared slides and in diagrams and photomicrographs"},{"text":"State the functions of the following components of blood:\n– red blood cells in transporting oxygen, including the role of haemoglobin\n– white blood cells in phagocytosis and antibody production\n– platelets in clotting (details are not required)\n– plasma in the transport of blood cells, ions, soluble nutrients, hormones and carbon dioxide"}],"supplement":[{"text":"Identify lymphocyte and phagocyte white blood cells, as seen under the light microscope, on prepared slides and in diagrams and photomicrographs"},{"text":"State the functions of:\n– lymphocytes – antibody production\n– phagocytes – phagocytosis"},{"text":"Describe the process of clotting as the conversion of fibrinogen to fibrin to form a mesh"},{"text":"State the roles of blood clotting as preventing blood loss and preventing the entry of pathogens"},{"text":"Describe the transfer of materials between capillaries and tissue fluid (details of the roles of water potential and hydrostatic pressure are not required)"}]}]},{"n":"10","title":"Diseases and immunity","sections":[{"n":"10.1","title":"Diseases and immunity","core":[{"text":"Define pathogen as a disease-causing organism"},{"text":"Define transmissible disease as a disease in which the pathogen can be passed from one host to another"},{"text":"State that the pathogen for a transmissible disease may be transmitted either through direct contact, e.g. through blood or other body fluids, or indirectly, e.g. from contaminated surfaces or food, from animals, or from the air"},{"text":"State that the body has defences:\n– mechanical barriers, limited to skin and hairs in the nose\n– chemical barriers, limited to mucus and stomach acid\n– cells, limited to phagocytosis and antibody production by white blood cells\n– which can be enhanced by vaccination"},{"text":"Explain the importance of hygienic food preparation, good personal hygiene, waste disposal and sewage treatment in controlling the spread of disease"}],"supplement":[{"text":"State that antibodies lock on to antigens leading to direct destruction of pathogens, or marking of pathogens for destruction by phagocytes"},{"text":"Explain how each pathogen has its own antigens, which have specific shapes, so specific antibodies which fit the specific shapes of the antigens are needed"},{"text":"Define active immunity as defence against a pathogen by antibody production in the body"},{"text":"Explain that active immunity is gained after an infection by a pathogen, or by vaccination"},{"text":"Explain the process of vaccination:\n– harmless pathogen given which has antigens\n– antigens trigger an immune response by lymphocytes which produce antibodies\n– memory cells are produced that give long-term immunity continued"},{"text":"Explain the role of vaccination in controlling the spread of diseases"},{"text":"Explain that passive immunity is short-term defence against a pathogen by antibodies acquired from another individual, e.g. mother to infant"},{"text":"State that memory cells are not produced in passive immunity"},{"text":"Explain the importance of passive immunity for breast-fed infants"},{"text":"State that some diseases are caused by the immune system targeting and destroying body cells, limited to Type 1 diabetes"}]}]},{"n":"11","title":"Gas exchange in humans","sections":[{"n":"11.1","title":"Gas exchange in humans","core":[{"text":"List the features of gas exchange surfaces in humans, limited to large surface area, thin surface, good blood supply and good ventilation with air"},{"text":"Name and identify the lungs, diaphragm, ribs, intercostal muscles, larynx, trachea, bronchi, bronchioles, alveoli and associated capillaries"},{"text":"State the differences in composition between inspired and expired air, limited to oxygen, carbon dioxide and water vapour"},{"text":"Use limewater as a test for carbon dioxide to investigate the differences in composition between inspired and expired air"},{"text":"Investigate and describe the effects of physical activity on rate and depth of breathing"}],"supplement":[{"text":"Name and identify the internal and external intercostal muscles"},{"text":"State the functions of the cartilage in the trachea"},{"text":"Explain the role of the ribs, the internal and external intercostal muscles and the diaphragm in producing volume and pressure changes in the thorax leading to the ventilation of the lungs"},{"text":"Explain the differences in composition between inspired and expired air"},{"text":"Explain the link between physical activity and rate and depth of breathing in terms of the increased carbon dioxide concentration in the blood, detected by the brain, causing an increased rate of breathing"},{"text":"Explain the role of goblet cells, mucus and ciliated cells in protecting the gas exchange system from pathogens and particles"}]}]},{"n":"12","title":"Respiration","sections":[{"n":"12.1","title":"Respiration","core":[{"text":"State the uses of energy in the body of humans: muscle contraction, protein synthesis, cell division, active transport, growth, the passage of nerve impulses and the maintenance of a constant body temperature"},{"text":"State that respiration involves the action of enzymes in cells"}],"supplement":[]},{"n":"12.2","title":"Aerobic respiration","core":[{"text":"Define aerobic respiration as the chemical reactions in cells that use oxygen to break down nutrient molecules to release energy"},{"text":"State the word equation for aerobic respiration as glucose + oxygen → carbon dioxide + water"},{"text":"Investigate the uptake of oxygen by respiring organisms, such as arthropods and germinating seeds"}],"supplement":[{"text":"State the balanced chemical equation for aerobic respiration as C6H12O6 + 6O2 → 6CO2 + 6H2O"},{"text":"Investigate the effect of temperature on the rate of respiration of germinating seeds"}]},{"n":"12.3","title":"Anaerobic respiration","core":[{"text":"Define anaerobic respiration as the chemical reactions in cells that break down nutrient molecules to release energy without using oxygen"},{"text":"State the word equations for anaerobic respiration in muscles during vigorous exercise (glucose → lactic acid) and the microorganism yeast (glucose → alcohol + carbon dioxide)"},{"text":"State that anaerobic respiration releases much less energy per glucose molecule than aerobic respiration"}],"supplement":[{"text":"State the balanced chemical equation for anaerobic respiration in the microorganism yeast as C6H12O6 → 2C2H5OH + 2CO2"},{"text":"State that lactic acid builds up in muscles and blood during vigorous exercise causing an oxygen debt"},{"text":"Outline how the oxygen debt is removed during recovery, limited to:\n– aerobic respiration of lactic acid in the liver\n– continuation, after exercise, of fast heart rate to transport lactic acid in blood from muscles to the liver\n– continuation, after exercise, of deeper breathing supplying oxygen for aerobic respiration of lactic acid"}]}]},{"n":"13","title":"Excretion in humans","sections":[{"n":"13.1","title":"Excretion in humans","core":[{"text":"State that urea is formed in the liver from excess amino acids"},{"text":"State that carbon dioxide is excreted through the lungs"},{"text":"State that the kidneys excrete urea and excess water and salts"},{"text":"Explain that the volume and concentration of urine produced is affected by water intake, temperature and exercise"},{"text":"Identify on drawings, diagrams and images, the ureters, bladder and urethra"}],"supplement":[{"text":"Describe the role of the liver in the assimilation of amino acids by converting them to proteins, including plasma proteins, e.g. fibrinogen"},{"text":"Define deamination as the removal of the nitrogen-containing part of amino acids to form urea"},{"text":"Explain the need for excretion, limited to toxicity of urea and carbon dioxide"},{"text":"Outline the structure of the kidney, limited to the cortex, medulla and ureter"},{"text":"Outline the structure and functioning of a kidney tubule, including:\n– the role of the glomerulus in the filtration from the blood of water, glucose, urea and salts\n– the role of the tubule in the reabsorption of all of the glucose, most of the water and some salts back into the blood, leading to the concentration of urea in the urine as well as loss of excess water and salts (details of these processes are not required)"},{"text":"Explain dialysis in terms of salt balance, the maintenance of glucose concentration and the removal of urea"},{"text":"Describe the use of dialysis in kidney machines"},{"text":"Discuss the advantages and disadvantages of kidney transplants, compared with dialysis"}]}]},{"n":"14","title":"Coordination and response","sections":[{"n":"14.1","title":"Nervous control in humans","core":[{"text":"Describe a nerve impulse as an electrical signal that passes along nerve cells called neurones"},{"text":"Describe the human nervous system in terms of:\n– the central nervous system consisting of brain and spinal cord\n– the peripheral nervous system\n– coordination and regulation of body functions"},{"text":"Identify motor (effector), relay (connector) and sensory neurones from diagrams"},{"text":"Describe a simple reflex arc in terms of receptor, sensory neurone, relay neurone, motor neurones and effector"},{"text":"Describe a reflex action as a means of automatically and rapidly integrating and coordinating stimuli with the responses of effectors (muscles and glands)"},{"text":"Define a synapse as a junction between two neurones"}],"supplement":[{"text":"Distinguish between voluntary and involuntary actions"},{"text":"Describe the structure of a synapse, including the presence of neurotransmitter containing vesicles, the synaptic cleft and neurotransmitter receptor molecules"},{"text":"Describe how an impulse triggers the release of a neurotransmitter from vesicles into the synaptic gap and how the neurotransmitter diffuses across to bind with receptor molecules, in the membrane of the neurone after the synaptic gap, causing the impulse to continue"},{"text":"State that in a reflex arc the synapses ensure that impulses travel in one direction only"},{"text":"State that many drugs, e.g. heroin, act upon synapses"}]},{"n":"14.2","title":"Sense organs","core":[{"text":"Define sense organs as groups of receptor cells responding to specific stimuli: light, sound, touch, temperature and chemicals"},{"text":"Identify the structures of the eye, limited to cornea, iris, pupil, lens, retina, optic nerve and blind spot"},{"text":"Describe the function of each part of the eye, limited to:\n– cornea – refracts light\n– iris – controls how much light enters pupil\n– lens – focuses light onto retina\n– retina – contains light receptors, some sensitive to light of different colours\n– optic nerve – carries impulses to the brain"},{"text":"Explain the pupil reflex in terms of light intensity and pupil diameter only"}],"supplement":[{"text":"Explain the pupil reflex in terms of light intensity and antagonistic action of circular and radial muscles in the iris"},{"text":"Explain accommodation to view near and distant objects in terms of the contraction and relaxation of the ciliary muscles, tension in the suspensory ligaments, shape of the lens and refraction of light"},{"text":"State the distribution of rods and cones in the retina of a human"},{"text":"Outline the function of rods and cones, limited to greater sensitivity of rods for night vision and three different kinds of cones absorbing light of different colours for colour vision"},{"text":"Identify the position of the fovea"}]},{"n":"14.3","title":"Hormones in humans","core":[{"text":"Define a hormone as a chemical substance, produced by a gland and carried by the blood, which alters the activity of one or more specific target organs"},{"text":"Identify specific endocrine glands and their secretions, limited to adrenal glands and adrenaline, pancreas and insulin, testes and testosterone and ovaries and oestrogen"},{"text":"Describe adrenaline as the hormone secreted in ‘fight or flight’ situations and its effects, limited to increased breathing and pulse rate and widened pupils"},{"text":"Give examples of situations in which adrenaline secretion increases"},{"text":"State the functions of insulin, oestrogen and testosterone"}],"supplement":[{"text":"Discuss the role of the hormone adrenaline in the chemical control of metabolic activity, including increasing the blood glucose concentration and pulse rate"},{"text":"Compare nervous and hormonal control systems in terms of speed and longevity of action"}]},{"n":"14.4","title":"Homeostasis","core":[{"text":"Define homeostasis as the maintenance of a constant internal environment"},{"text":"Name and identify on a diagram of the skin: hairs, hair erector muscles, sweat glands, receptors, sensory neurones, blood vessels and fatty tissue"},{"text":"Describe the maintenance of a constant internal body temperature in humans in terms of insulation, sweating, shivering and the role of the brain (limited to blood temperature receptors and coordination)"}],"supplement":[{"text":"Explain that homeostasis is the control of internal conditions within set limits"},{"text":"Explain the concept of control by negative feedback"},{"text":"Describe the control of the glucose concentration of the blood by the liver and the roles of insulin and glucagon from the pancreas"},{"text":"Outline the symptoms and treatment of Type 1 diabetes (detail of β cells is not required)"},{"text":"Describe the maintenance of a constant internal body temperature in humans in terms of vasodilation and vasoconstriction of arterioles supplying skin surface capillaries"}]},{"n":"14.5","title":"Tropic responses","core":[{"text":"Define gravitropism as a response in which parts of a plant grow towards or away from gravity"},{"text":"Define phototropism as a response in which parts of a plant grow towards or away from the direction from which light is coming"},{"text":"Investigate gravitropism and phototropism in shoots and roots"}],"supplement":[{"text":"Explain phototropism and gravitropism of a shoot as examples of the chemical control of plant growth"},{"text":"Explain the role of auxin in controlling shoot growth, limited to:\n– auxin made in shoot tip (only)\n– auxin spreads through the plant from the shoot tip\n– auxin is unequally distributed in response to light and gravity\n– auxin stimulates cell elongation"},{"text":"Describe the use in weedkillers of the synthetic plant hormone 2,4-D"}]}]},{"n":"15","title":"Drugs","sections":[{"n":"15.1","title":"Drugs","core":[{"text":"Define a drug as any substance taken into the body that modifies or affects chemical reactions in the body"}],"supplement":[]},{"n":"15.2","title":"Medicinal drugs","core":[{"text":"Describe the use of antibiotics for the treatment of bacterial infection"},{"text":"State that some bacteria are resistant to antibiotics which reduces the effectiveness of antibiotics"},{"text":"State that antibiotics kill bacteria but do not affect viruses"}],"supplement":[{"text":"Explain how development of resistant bacteria such as MRSA can be minimised, limited to using antibiotics only when essential and ensuring treatment is completed"},{"text":"Explain why antibiotics kill bacteria, but do not affect viruses"}]},{"n":"15.3","title":"Misused drugs","core":[{"text":"Describe the effects of excessive alcohol consumption and abuse of heroin, limited to:\n– powerful depressant drugs\n– effect on reaction times and self-control\n– addiction and withdrawal symptoms\n– negative social implications, e.g. crime"},{"text":"State that injecting heroin can cause infections such as HIV"},{"text":"State that excessive alcohol consumption can cause liver damage"},{"text":"State that tobacco smoking can cause chronic obstructive pulmonary disease (COPD), lung cancer and coronary heart disease"},{"text":"Describe the effects on the gas exchange system of tobacco smoke and its major toxic components, limited to carbon monoxide, nicotine and tar"},{"text":"State that the liver is the site of break down of alcohol and other toxins"}],"supplement":[{"text":"Explain how heroin affects the nervous system, limited to its effect on the function of synapses"},{"text":"Discuss the evidence for the link between smoking and lung cancer"},{"text":"Discuss the use of hormones to improve sporting performance, limited to testosterone and anabolic steroids"}]}]},{"n":"16","title":"Reproduction","sections":[{"n":"16.1","title":"Asexual reproduction","core":[{"text":"Define asexual reproduction as a process resulting in the production of genetically identical offspring from one parent"},{"text":"Identify examples of asexual reproduction from information provided"}],"supplement":[{"text":"Discuss the advantages and disadvantages of asexual reproduction:\n– to a population of a species in the wild\n– to crop production"}]},{"n":"16.2","title":"Sexual reproduction","core":[{"text":"Define sexual reproduction as a process involving the fusion of the nuclei of two gametes (sex cells) to form a zygote and the production of offspring that are genetically different from each other"},{"text":"Define fertilisation as the fusion of gamete nuclei"}],"supplement":[{"text":"State that the nuclei of gametes are haploid and that the nucleus of a zygote is diploid"},{"text":"Discuss the advantages and disadvantages of sexual reproduction:\n– to a population of a species in the wild\n– to crop production"}]},{"n":"16.3","title":"Sexual reproduction in plants","core":[{"text":"Identify and draw, using a hand lens if necessary, the sepals, petals, stamens, filaments and anthers, carpels, style, stigma, ovary and ovules, of an insect-pollinated flower"},{"text":"State the functions of the sepals, petals, anthers, stigmas and ovaries"},{"text":"Use a hand lens to identify and describe the anthers and stigmas of a wind-pollinated flower"},{"text":"Distinguish between the pollen grains of insect-pollinated and wind-pollinated flowers"},{"text":"Define pollination as the transfer of pollen grains from the anther to the stigma"},{"text":"State that fertilisation occurs when a pollen nucleus fuses with a nucleus in an ovule"},{"text":"Describe the structural adaptations of insect-pollinated and wind-pollinated flowers"},{"text":"Investigate and state the environmental conditions that affect germination of seeds, limited to the requirement for water, oxygen and a suitable temperature"}],"supplement":[{"text":"Define self-pollination as the transfer of pollen grains from the anther of a flower to the stigma of the same flower or different flower on the same plant"},{"text":"Define cross-pollination as transfer of pollen grains from the anther of a flower to the stigma of a flower on a different plant of the same species"},{"text":"Discuss the implications to a species of self-pollination and cross-pollination in terms of variation, capacity to respond to changes in the environment and reliance on pollinators"},{"text":"Describe the growth of the pollen tube and its entry into the ovule followed by fertilisation (details of production of endosperm and development are not required)"}]},{"n":"16.4","title":"Sexual reproduction in humans","core":[{"text":"Identify and name on diagrams of the male reproductive system: the testes, scrotum, sperm ducts, prostate gland, urethra and penis, and state the functions of these parts"},{"text":"Identify and name on diagrams of the female reproductive system: the ovaries, oviducts, uterus, cervix and vagina, and state the functions of these parts"},{"text":"Describe fertilisation as the fusion of the nuclei from a male gamete (sperm) and a female gamete (egg cell/ovum)"},{"text":"State the adaptive features of sperm, limited to flagellum and the presence of enzymes"},{"text":"State the adaptive features of egg cells, limited to energy stores and a jelly coating that changes after fertilisation"},{"text":"State that in early development, the zygote forms an embryo which is a ball of cells that implants into the wall of the uterus"},{"text":"State the functions of the umbilical cord, placenta, amniotic sac and amniotic fluid"},{"text":"Outline the growth and development of the fetus in terms of increasing complexity in the early stages and increasing size towards the end of pregnancy"},{"text":"Describe the antenatal care of pregnant women, limited to special dietary needs and the harm from smoking and alcohol consumption"},{"text":"Outline the processes involved in labour and birth, limited to:\n– breaking of the amniotic sac\n– contraction of the muscles in the uterus wall\n– dilation of the cervix\n– passage through the vagina\n– tying and cutting the umbilical cord\n– delivery of the afterbirth"}],"supplement":[{"text":"Compare male and female gametes in terms of size, structure, motility and numbers"},{"text":"Explain the adaptive features of sperm, limited to flagellum, mitochondria and enzymes in the acrosome"},{"text":"Explain the adaptive features of egg cells, limited to energy stores and the jelly coat that changes at fertilisation"},{"text":"Describe the function of the placenta and umbilical cord in relation to exchange of dissolved nutrients, gases and excretory products and providing a barrier to toxins and pathogens (structural details are not required)"},{"text":"State that some toxins, e.g. nicotine, and pathogens, e.g. rubella virus, can pass across the placenta and affect the fetus"},{"text":"Discuss the advantages and disadvantages of breast-feeding compared with bottle-feeding using formula milk"}]},{"n":"16.5","title":"Sex hormones in humans","core":[{"text":"Describe the roles of testosterone and oestrogen in the development and regulation of secondary sexual characteristics during puberty"},{"text":"Describe the menstrual cycle in terms of changes in the ovaries and in the lining of the uterus"}],"supplement":[{"text":"Describe the sites of production of oestrogen and progesterone in the menstrual cycle and in pregnancy"},{"text":"Explain the role of hormones in controlling the menstrual cycle and pregnancy, limited to FSH, LH, progesterone and oestrogen"}]},{"n":"16.6","title":"Methods of birth control in humans","core":[{"text":"Outline the following methods of birth control:\n– natural, limited to abstinence, monitoring body temperature and cervical mucus\n– chemical, limited to IUD, IUS, contraceptive pill, implant and injection\n– barrier, limited to condom, femidom, diaphragm\n– surgical, limited to vasectomy and female sterilisation"}],"supplement":[{"text":"Outline the use of hormones in contraception and fertility treatments"},{"text":"Outline artificial insemination (AI)"},{"text":"Outline in vitro fertilisation (IVF)"},{"text":"Discuss the social implications of contraception and fertility treatments"}]},{"n":"16.7","title":"Sexually transmitted infections (STIs)","core":[{"text":"Define sexually transmitted infection as an infection that is transmitted via body fluids through sexual contact"},{"text":"State that human immunodeficiency virus (HIV) is an example of an STI"},{"text":"Explain how the spread of STIs is controlled"},{"text":"Describe the methods of transmission of HIV"},{"text":"State that HIV infection may lead to AIDS"}],"supplement":[{"text":"Outline how HIV affects the immune system, limited to decreased lymphocyte numbers and reduced ability to produce antibodies"}]}]},{"n":"17","title":"Inheritance","sections":[{"n":"17.1","title":"Inheritance","core":[{"text":"Define inheritance as the transmission of genetic information from generation to generation"}],"supplement":[]},{"n":"17.2","title":"Chromosomes, genes and proteins","core":[{"text":"Define chromosome as a thread-like structure of DNA, carrying genetic information in the form of genes"},{"text":"Define gene as a length of DNA that codes for a protein"},{"text":"Define allele as a version of a gene"},{"text":"Describe the inheritance of sex in humans with reference to XX and XY chromosomes"}],"supplement":[{"text":"Explain that the sequence of bases in a gene is the genetic code for putting together amino acids in the correct order to make a specific protein (knowledge of the details of nucleotide structure is not required)"},{"text":"Explain that DNA controls cell function by controlling the production of proteins (some of which are enzymes), antibodies and receptors for neurotransmitters"},{"text":"Explain how a protein is made, limited to:\n– the gene coding for the protein remains in the nucleus\n– mRNA molecules carry a copy of the gene to the cytoplasm\n– the mRNA passes through ribosomes\n– the ribosome assembles amino acids into protein molecules\n– the specific order of amino acids is determined by the sequence of bases in the mRNA (knowledge of the details of transcription or translation is not required)"},{"text":"Explain that all body cells in an organism contain the same genes, but many genes in a particular cell are not expressed because the cell only makes the specific proteins it needs"},{"text":"Define a haploid nucleus as a nucleus containing a single set of unpaired chromosomes, e.g. in gametes"},{"text":"Define a diploid nucleus as a nucleus containing two sets of chromosomes, e.g. in body cells"},{"text":"State that in a diploid cell, there is a pair of each type of chromosome and in a human diploid cell there are 23 pairs"}]},{"n":"17.3","title":"Mitosis","core":[{"text":"Define mitosis as nuclear division giving rise to genetically identical cells (details of stages are not required)"},{"text":"State the role of mitosis in growth, repair of damaged tissues, replacement of cells and asexual reproduction"}],"supplement":[{"text":"State that the exact duplication of chromosomes occurs before mitosis"},{"text":"State that during mitosis, the copies of chromosomes separate, maintaining the chromosome number (details of stages of mitosis are not required)"},{"text":"Describe stem cells as unspecialised cells that divide by mitosis to produce daughter cells that can become specialised for specific functions"}]},{"n":"17.4","title":"Meiosis","core":[{"text":"Define meiosis as nuclear division giving rise to cells that are genetically different (details of stages are not required)"},{"text":"State that meiosis is involved in the production of gametes"}],"supplement":[{"text":"Define meiosis as reduction division in which the chromosome number is halved from diploid to haploid resulting in genetically different cells (details of stages are not required)"},{"text":"Explain how meiosis produces variation by forming new combinations of maternal and paternal chromosomes (specific details are not required)"}]},{"n":"17.5","title":"Monohybrid inheritance","core":[{"text":"Define genotype as the genetic make-up of an organism in terms of the alleles present"},{"text":"Define phenotype as the observable features of an organism"},{"text":"Define homozygous as having two identical alleles of a particular gene"},{"text":"State that two identical homozygous individuals that breed together will be pure-breeding"},{"text":"Define heterozygous as having two different alleles of a particular gene"},{"text":"State that a heterozygous individual will not be pure-breeding"},{"text":"Define dominant as an allele that is expressed if it is present"},{"text":"Define recessive as an allele that is only expressed when there is no dominant allele of the gene present"},{"text":"Interpret pedigree diagrams for the inheritance of a given characteristic"},{"text":"Use genetic diagrams to predict the results of monohybrid crosses and calculate phenotypic ratios, limited to 1:1 and 3:1 ratios"},{"text":"Use Punnett squares in crosses which result in more than one genotype to work out and show the possible different genotypes"}],"supplement":[{"text":"Explain how to use a test cross to identify an unknown genotype"},{"text":"Explain co-dominance by reference to the inheritance of ABO blood groups – phenotypes being A, B, AB and O blood groups and alleles being IA, IB and IO"},{"text":"Define a sex-linked characteristic as a characteristic in which the gene responsible is located on a sex chromosome and that this makes it more common in one sex than in the other"},{"text":"Describe colour blindness as an example of sex linkage"},{"text":"Use genetic diagrams to predict the results of monohybrid crosses involving co-dominance or sex linkage and calculate phenotypic ratios"}]}]},{"n":"18","title":"Variation and selection","sections":[{"n":"18.1","title":"Variation","core":[{"text":"Define variation as differences between individuals of the same species"},{"text":"Distinguish between phenotypic variation and genetic variation"},{"text":"State that continuous variation results in a range of phenotypes between two extremes, e.g. height in humans"},{"text":"State that discontinuous variation results in a limited number of phenotypes with no intermediates, e.g. tongue rolling"},{"text":"Record and present the results of investigations into continuous and discontinuous variation"},{"text":"Define mutation as genetic change"},{"text":"State that mutation is the way in which new alleles are formed"},{"text":"State that ionising radiation and some chemicals increase the rate of mutation"}],"supplement":[{"text":"State that phenotypic variation is caused by both genetic and environmental factors"},{"text":"State that discontinuous variation is mostly caused by genes alone, e.g. A, B, AB and O blood groups in humans"},{"text":"Define gene mutation as a change in the base sequence of DNA"},{"text":"Describe the symptoms of sickle-cell anaemia"},{"text":"Explain how a change in the base sequence of the gene for haemoglobin results in abnormal haemoglobin and sickle-shaped red blood cells"},{"text":"Use genetic diagrams to show how sickle-cell anaemia is inherited"},{"text":"State that people who are heterozygous (HbS HbA) for the sickle-cell allele have a resistance to malaria"},{"text":"Explain the distribution of the sickle-cell allele in human populations with reference to the distribution of malaria (Teaching of human inherited conditions should be done with sensitivity at all times.)"}]},{"n":"18.2","title":"Adaptive features","core":[{"text":"Define adaptive feature as an inherited feature that helps an organism to survive and reproduce in its environment"},{"text":"Interpret images or other information about a species to describe its adaptive features"}],"supplement":[{"text":"Define adaptive feature as the inherited functional features of an organism that increase its fitness"},{"text":"Define fitness as the probability of an organism surviving and reproducing in the environment in which it is found"},{"text":"Explain the adaptive features of hydrophytes and xerophytes to their environments"}]},{"n":"18.3","title":"Selection","core":[{"text":"Describe natural selection with reference to:\n– variation within populations\n– production of many offspring\n– competition for resources\n– struggle for survival\n– reproduction by individuals that are better adapted to the environment than others\n– passing on of their alleles to the next generation"},{"text":"Describe selective breeding with reference to:\n– selection by humans of individuals with desirable features\n– crossing these individuals to produce the next generation\n– selection of offspring showing the desirable features"}],"supplement":[{"text":"Describe evolution as the change in adaptive features of a population over time as the result of natural selection"},{"text":"Define the process of adaptation as the process, resulting from natural selection, by which populations become more suited to their environment over many generations"},{"text":"Describe the development of strains of antibiotic resistant bacteria as an example of evolution by natural selection"},{"text":"State the differences between natural and artificial selection"},{"text":"Outline how selective breeding by artificial selection is carried out over many generations to improve crop plants and domesticated animals"}]}]},{"n":"19","title":"Organisms and their environment","sections":[{"n":"19.1","title":"Energy flow","core":[{"text":"State that the Sun is the principal source of energy input to biological systems"}],"supplement":[{"text":"Describe the flow of energy through living organisms including light energy from the Sun and chemical energy in organisms and its eventual transfer to the environment"}]},{"n":"19.2","title":"Food chains and food webs","core":[{"text":"Define a food chain as showing the transfer of energy from one organism to the next, beginning with a producer"},{"text":"State that energy is transferred between organisms in a food chain by ingestion"},{"text":"Construct simple food chains"},{"text":"Define a food web as a network of interconnected food chains"},{"text":"Define producer as an organism that makes its own organic nutrients, usually using energy from sunlight, through photosynthesis"},{"text":"Define consumer as an organism that gets its energy by feeding on other organisms"},{"text":"State that consumers may be classed as primary, secondary and tertiary according to their position in a food chain"},{"text":"Define herbivore as an animal that gets its energy by eating plants"},{"text":"Define carnivore as an animal that gets its energy by eating other animals"},{"text":"Define decomposer as an organism that gets its energy from dead or waste organic material"},{"text":"Interpret food chains and food webs in terms of identifying producers and consumers"},{"text":"Use food chains and food webs to describe the impacts humans have through over-harvesting of food species and through introducing foreign species to a habitat"},{"text":"Draw, describe and interpret pyramids of numbers"}],"supplement":[{"text":"Describe how energy is transferred between trophic levels"},{"text":"Define trophic level as the position of an organism in a food chain, food web, pyramid of numbers or pyramid of biomass"},{"text":"Explain why the transfer of energy from one trophic level to another is inefficient"},{"text":"Explain why food chains usually have fewer than five trophic levels continued"},{"text":"Explain why there is a greater efficiency in supplying plants as human food, and that there is a relative inefficiency in feeding crop plants to livestock that will be used as food"},{"text":"Identify producers, primary consumers, secondary consumers, tertiary consumers and quaternary consumers as the trophic levels in food webs, food chains, pyramids of numbers and pyramids of biomass"},{"text":"Draw, describe and interpret pyramids of biomass"},{"text":"Discuss the advantages of using a pyramid of biomass rather than a pyramid of numbers to represent a food chain"}]},{"n":"19.3","title":"Nutrient cycles","core":[{"text":"Describe the carbon cycle, limited to photosynthesis, respiration, feeding, decomposition, fossilisation and combustion"},{"text":"Discuss the effects of the combustion of fossil fuels and the cutting down of forests on the carbon dioxide concentrations in the atmosphere"},{"text":"Describe the water cycle, limited to evaporation, transpiration, condensation and precipitation"}],"supplement":[{"text":"Describe the nitrogen cycle in terms of:\n– decomposition of plant and animal protein to ammonium ions\n– nitrification\n– nitrogen fixation by lightning and bacteria\n– absorption of nitrate ions by plants\n– production of amino acids and proteins\n– feeding and digestion of proteins\n– deamination\n– denitrification"},{"text":"State the roles of microorganisms in the nitrogen cycle, limited to decomposition, nitrification, nitrogen fixation and denitrification (generic names of individual bacteria, e.g. Rhizobium, are not required)"}]},{"n":"19.4","title":"Population size","core":[{"text":"Define population as a group of organisms of one species, living in the same area, at the same time"},{"text":"Identify and state the factors affecting the rate of population growth for a population of an organism, limited to food supply, predation and disease"},{"text":"Discuss the increase in human population size over the past 250 years and its social and environmental implications"},{"text":"Interpret graphs and diagrams of human population growth"}],"supplement":[{"text":"Define community as all of the populations of different species in an ecosystem"},{"text":"Define ecosystem as a unit containing the community of organisms and their environment, interacting together, e.g. a decomposing log, or a lake"},{"text":"Identify the lag, exponential (log), stationary and death phases in the sigmoid population growth curve for a population growing in an environment with limited resources"},{"text":"Explain the factors that lead to each phase in the sigmoid curve of population growth, making reference, where appropriate, to the role of limiting factors"}]}]},{"n":"20","title":"Biotechnology and genetic engineering","sections":[{"n":"20.1","title":"Biotechnology and genetic engineering","core":[{"text":"State that bacteria are useful in biotechnology and genetic engineering due to their rapid reproduction rate and their ability to make complex molecules"}],"supplement":[{"text":"Discuss why bacteria are useful in biotechnology and genetic engineering, limited to:\n– lack of ethical concerns over their manipulation and growth\n– genetic code shared with all other organisms\n– presence of plasmids"}]},{"n":"20.2","title":"Biotechnology","core":[{"text":"Describe the role of anaerobic respiration in yeast during production of ethanol for biofuels"},{"text":"Describe the role of anaerobic respiration in yeast during bread-making"},{"text":"Investigate and describe the use of pectinase in fruit juice production"},{"text":"Investigate and describe the use of biological washing powders that contain enzymes"}],"supplement":[{"text":"Investigate and explain the use of lactase to produce lactose-free milk"},{"text":"Describe the role of the fungus Penicillium in the production of the antibiotic penicillin"},{"text":"Explain how fermenters are used in the production of penicillin"}]},{"n":"20.3","title":"Genetic engineering","core":[{"text":"Define genetic engineering as changing the genetic material of an organism by removing, changing or inserting individual genes"},{"text":"State examples of genetic engineering:\n– the insertion of human genes into bacteria to produce human insulin\n– the insertion of genes into crop plants to confer resistance to herbicides\n– the insertion of genes into crop plants to confer resistance to insect pests\n– the insertion of genes into crop plants to provide additional vitamins"}],"supplement":[{"text":"Outline genetic engineering using bacterial production of a human protein as an example, limited to:\n– isolation of the DNA making up a human gene using restriction enzymes, forming sticky ends\n– cutting of bacterial plasmid DNA with the same restriction enzymes, forming complementary sticky ends\n– insertion of human DNA into bacterial plasmid DNA using DNA ligase to form a recombinant plasmid\n– insertion of plasmid into bacteria (specific detail is not required)\n– replication of bacteria containing recombinant plasmids which make human protein as they express the gene"},{"text":"Discuss the advantages and disadvantages of genetically modifying crops, such as soya, maize and rice"}]}]},{"n":"21","title":"Human influences on ecosystems","sections":[{"n":"21.1","title":"Food supply","core":[{"text":"State how modern technology has resulted in increased food production in terms of:\n– agricultural machinery to use larger areas of land and improve efficiency\n– chemical fertilisers to improve yields\n– insecticides to improve quality and yield\n– herbicides to reduce competition with weeds\n– selective breeding to improve production by crop plants and livestock, e.g. cattle, fish and poultry"},{"text":"Describe the negative impacts to an ecosystem of large-scale monocultures of crop plants"},{"text":"Describe the negative impacts to an ecosystem of intensive livestock production"}],"supplement":[{"text":"Discuss the social, environmental and economic implications of providing sufficient food for an increasing human global population"},{"text":"Discuss the problems which contribute to famine including unequal distribution of food, drought and flooding, increasing population and poverty"}]},{"n":"21.2","title":"Habitat destruction","core":[{"text":"Describe the reasons for habitat destruction, limited to:\n– increased area for food crop growth, livestock production and housing\n– extraction of natural resources\n– marine pollution"},{"text":"State that through altering food webs and food chains, humans can have a negative impact on habitats"},{"text":"List the undesirable effects of deforestation as an example of habitat destruction, to include extinction, loss of soil, flooding and increase of carbon dioxide in the atmosphere"}],"supplement":[{"text":"Explain the undesirable effects of deforestation on the environment"}]},{"n":"21.3","title":"Pollution","core":[{"text":"State the sources and effects of pollution of land and water, e.g. rivers, lakes and the sea, by insecticides, herbicides and by nuclear fall-out"},{"text":"State the sources and effects of pollution of water (rivers, lakes and the sea) by chemical waste, discarded rubbish, untreated sewage and fertilisers"},{"text":"State the sources and effects of pollution of the air by methane and carbon dioxide, limited to the enhanced greenhouse effect and climate change"}],"supplement":[{"text":"Explain the process of eutrophication of water in terms of:\n– increased availability of nitrate and other ions\n– increased growth of producers\n– increased decomposition after death of producers\n– increased aerobic respiration by decomposers\n– reduction in dissolved oxygen\n– death of organisms requiring dissolved oxygen in water"},{"text":"Discuss the effects of non-biodegradable plastics in the environment, in both aquatic and terrestrial ecosystems"},{"text":"Discuss the causes and effects on the environment of acid rain"},{"text":"State the measures that are taken to reduce sulfur dioxide pollution and reduce the impact of acid rain"},{"text":"Explain how increases in carbon dioxide and methane concentrations in the atmosphere cause an enhanced greenhouse effect that leads to climate change"},{"text":"Describe the negative impacts of female contraceptive hormones in water courses, limited to reduced sperm count in men and feminisation of aquatic organisms"}]},{"n":"21.4","title":"Conservation","core":[{"text":"Define a sustainable resource as one which is produced as rapidly as it is removed from the environment so that it does not run out"},{"text":"Explain the need to conserve non-renewable resources, limited to fossil fuels"},{"text":"State that some resources can be maintained, limited to forests and fish stocks"},{"text":"State that products can be reused or recycled, limited to paper, glass, plastic and metal"},{"text":"Outline how sewage is treated to make the water that it contains safe to return to the environment or for human use"},{"text":"Explain why organisms become endangered or extinct, limited to climate change, habitat destruction, hunting, pollution and introduced species"},{"text":"Describe how endangered species can be conserved, limited to monitoring and protecting species and habitats, education, captive breeding programmes and seed banks"}],"supplement":[{"text":"Define the term sustainable development as development providing for the needs of an increasing human population without harming the environment"},{"text":"Explain how forests and fish stocks can be sustained using education, legal quotas and restocking"},{"text":"Explain that sustainable development requires:\n– management of conflicting demands\n– planning and co-operation at local, national and international levels"},{"text":"Explain the risks to a species if the population size drops, reducing variation (knowledge of genetic drift is not required)"},{"text":"Explain reasons for conservation programmes, to include:\n– reducing extinction\n– protecting vulnerable environments\n– maintaining ecosystem functions, limited to nutrient cycling and resource provision, e.g. food, drugs, fuel and genes"}]}]}]},{"id":"2019","label":"2019","until":"2019","numbered":false,"source":{"title":"Cambridge IGCSE Biology 0610, for examination in 2019 (version 3)","url":"http://www.cambridgeinternational.org/Images/329744-2019-syllabus.pdf","via":"web.archive.org, 2 June 2018"},"topics":[{"n":"1","title":"Characteristics and classification of living organisms","sections":[{"n":"1.1","title":"Characteristics of living organisms","core":[{"text":"Describe the characteristics of living organisms by defining the terms:\n– movement as an action by an organism causing a change of position or place\n– respiration as the chemical reactions in cells that break down nutrient molecules and release energy\n– sensitivity as the ability to detect and respond to changes in the environment\n– growth as a permanent increase in size\n– reproduction as the processes that make more of the same kind of organism\n– excretion as removal from organisms of toxic materials and substances in excess of requirements\n– nutrition as taking in of materials for energy, growth and development"}],"supplement":[{"text":"Define the terms:\n– movement as an action by an organism or part of an organism causing a change of position or place\n– respiration as the chemical reactions in cells that break down nutrient molecules and release energy for metabolism\n– sensitivity as the ability to detect or sense stimuli in the internal or external environment and to make appropriate responses\n– growth as a permanent increase in size and dry mass by an increase in cell number or cell size or both\n– excretion as removal from organisms of the waste products of metabolism (chemical reactions in cells including respiration), toxic materials, and substances in excess of requirements\n– nutrition as taking in of materials for energy, growth and development; plants require light, carbon dioxide, water and ions; animals need organic compounds and ions and usually need water"}]},{"n":"1.2","title":"Concept and use of a classification system","core":[{"text":"State that organisms can be classified into groups by the features that they share"},{"text":"Define species as a group of organisms that can reproduce to produce fertile offspring"},{"text":"Define and describe the binomial system of naming species as an internationally agreed system in which the scientific name of an organism is made up of two parts showing the genus and species"}],"supplement":[{"text":"Explain that classification systems aim to reflect evolutionary relationships"},{"text":"Explain that classification is traditionally based on studies of morphology and anatomy"},{"text":"Explain that the sequences of bases in DNA and of amino acids in proteins are used as a more accurate means of classification"},{"text":"Explain that organisms which share a more recent ancestor (are more closely related) have base sequences in DNA that are more similar than those that share only a distant ancestor"}]},{"n":"1.3","title":"Features of organisms","core":[{"text":"List the features in the cells of all living organisms, limited to cytoplasm, cell membrane and DNA as genetic material"},{"text":"List the main features used to place animals and plants into the appropriate kingdoms"},{"text":"List the main features used to place organisms into groups within the animal kingdom, limited to: –– the main groups of vertebrates: mammals, birds, reptiles, amphibians, fish –– the main groups of arthropods: myriapods, insects, arachnids, crustaceans"}],"supplement":[{"text":"List the features in the cells of all living organisms, limited to ribosomes for protein synthesis and enzymes involved in respiration"},{"text":"List the main features used to place all organisms into one of the five kingdoms: Animal, Plant, Fungus, Prokaryote, Protoctist"},{"text":"List the main features used to place organisms into groups within the plant kingdom, limited to ferns and flowering plants (dicotyledons and monocotyledons)"},{"text":"List the features of viruses, limited to protein coat and genetic material"}]},{"n":"1.4","title":"Dichotomous keys","core":[{"text":"Construct and use simple dichotomous keys based on easily identifiable features"}],"supplement":[]}]},{"n":"2","title":"Organisation of the organism","sections":[{"n":"2.1","title":"Cell structure and organisation","core":[{"text":"Describe and compare the structure of a plant cell with an animal cell, as seen under a light microscope, limited to cell wall, nucleus, cytoplasm, chloroplasts, vacuoles and location of the cell membrane"},{"text":"State the functions of the structures seen under the light microscope in the plant cell and in the animal cell"}],"supplement":[{"text":"State that the cytoplasm of all cells contains structures, limited to ribosomes on rough endoplasmic reticulum and vesicles"},{"text":"State that almost all cells, except prokaryotes, have mitochondria and rough endoplasmic reticulum"},{"text":"Identify mitochondria and rough endoplasmic reticulum in diagrams and images of cells"},{"text":"State that aerobic respiration occurs in mitochondria"},{"text":"State that cells with high rates of metabolism require large numbers of mitochondria to provide sufficient energy"}]},{"n":"2.2","title":"Levels of organisation","core":[{"text":"Relate the structure of the following to their functions:\n– ciliated cells – movement of mucus in the trachea and bronchi\n– root hair cells – absorption\n– xylem vessels – conduction and support\n– palisade mesophyll cells – photosynthesis\n– nerve cells – conduction of impulses\n– red blood cells – transport of oxygen\n– sperm and egg cells – reproduction"},{"text":"Define tissue as a group of cells with similar structures, working together to perform a shared function"},{"text":"Define organ as a structure made up of a group of tissues, working together to perform specific functions"},{"text":"Define organ system as a group of organs with related functions, working together to perform body functions"},{"text":"State examples of tissues, organs and organ systems from sections 6 to 16"},{"text":"Identify the different levels of organisation in drawings, diagrams and images of familiar material"}],"supplement":[{"text":"Identify the different levels of organisation in drawings, diagrams and images of unfamiliar material"}]},{"n":"2.3","title":"Size of specimens","core":[{"text":"Calculate magnification and size of biological specimens using millimetres as units"}],"supplement":[{"text":"Calculate magnification and size of biological specimens using millimetres and micrometres as units"}]}]},{"n":"3","title":"Movement in and out of cells","sections":[{"n":"3.1","title":"Diffusion","core":[{"text":"Define diffusion as the net movement of particles from a region of their higher concentration to a region of their lower concentration down a concentration gradient, as a result of their random movement"},{"text":"Describe the importance of diffusion of gases and solutes"},{"text":"State that substances move into and out of cells by diffusion through the cell membrane"}],"supplement":[{"text":"State that the energy for diffusion comes from the kinetic energy of random movement of molecules and ions"},{"text":"Investigate the factors that influence diffusion, limited to surface area, temperature, concentration gradients and distance"}]},{"n":"3.2","title":"Osmosis","core":[{"text":"State that water diffuses through partially permeable membranes by osmosis"},{"text":"State that water moves in and out of cells by osmosis through the cell membrane"},{"text":"Investigate and describe the effects on plant tissues of immersing them in solutions of different concentrations"},{"text":"State that plants are supported by the pressure of water inside the cells pressing outwards on the cell wall"}],"supplement":[{"text":"Define osmosis as the net movement of water molecules from a region of higher water potential (dilute solution) to a region of lower water potential (concentrated solution), through a partially permeable membrane"},{"text":"Explain the effects on plant tissues of immersing them in solutions of different concentrations by using the terms turgid, turgor pressure, plasmolysis and flaccid"},{"text":"Explain the importance of water potential and osmosis in the uptake of water by plants"},{"text":"Explain the importance of water potential and osmosis on animal cells and tissues"},{"text":"Explain how plants are supported by the turgor pressure within cells, in terms of water pressure acting against an inelastic cell wall"}]},{"n":"3.3","title":"Active transport","core":[{"text":"Define active transport as the movement of particles through a cell membrane from a region of lower concentration to a region of higher concentration using energy from respiration"}],"supplement":[{"text":"Discuss the importance of active transport as a process for movement across membranes:\n– e.g. ion uptake by root hairs and uptake of glucose by epithelial cells of villi and kidney tubules"},{"text":"Explain how protein molecules move particles across a membrane during active transport"}]}]},{"n":"4","title":"Biological molecules","sections":[{"n":"4.1","title":"Biological molecules","core":[{"text":"List the chemical elements that make up:\n– carbohydrates\n– fats\n– proteins"},{"text":"State that large molecules are made from smaller molecules, limited to:\n– starch and glycogen from glucose\n– cellulose from glucose\n– proteins from amino acids\n– fats and oils from fatty acids and glycerol"},{"text":"Describe the use of:\n– iodine solution to test for starch\n– Benedict’s solution to test for reducing sugars\n– biuret test for proteins\n– ethanol emulsion test for fats and oils\n– DCPIP test for vitamin C"},{"text":"State that water is important as a solvent"}],"supplement":[{"text":"Explain that different sequences of amino acids give different shapes to protein molecules"},{"text":"Relate the shape and structure of protein molecules to their function, limited to the active site of enzymes and the binding site of antibodies continued"},{"text":"Describe the structure of DNA as:\n– two strands coiled together to form a double helix\n– each strand contains chemicals called bases\n– cross-links between the strands are formed by pairs of bases\n– the bases always pair up in the same way: A with T, and C with G (full names are not required)"},{"text":"Describe the roles of water as a solvent in organisms with respect to digestion, excretion and transport"}]}]},{"n":"5","title":"Enzymes","sections":[{"n":"5.1","title":"Enzymes","core":[{"text":"Define the term catalyst as a substance that increases the rate of a chemical reaction and is not changed by the reaction"},{"text":"Define enzymes as proteins that function as biological catalysts"},{"text":"Describe why enzymes are important in all living organisms in terms of reaction speed necessary to sustain life"},{"text":"Describe enzyme action with reference to the complementary shape of an enzyme and its substrate and the formation of a product (knowledge of the term active site is not required)"},{"text":"Investigate and describe the effect of changes in temperature and pH on enzyme activity"}],"supplement":[{"text":"Explain enzyme action with reference to the active site, enzyme-substrate complex, substrate and product"},{"text":"Explain the specificity of enzymes in terms of the complementary shape and fit of the active site with the substrate"},{"text":"Explain the effect of changes in temperature on enzyme activity in terms of kinetic energy, shape and fit, frequency of effective collisions and denaturation"},{"text":"Explain the effect of changes in pH on enzyme activity in terms of shape and fit and denaturation"}]}]},{"n":"6","title":"Plant nutrition","sections":[{"n":"6.1","title":"Photosynthesis","core":[{"text":"Define photosynthesis as the process by which plants manufacture carbohydrates from raw materials using energy from light"},{"text":"State the word equation for photosynthesis: carbon dioxide + water → glucose + oxygen, in the presence of light and chlorophyll"},{"text":"Investigate the necessity for chlorophyll, light and carbon dioxide for photosynthesis, using appropriate controls"},{"text":"Investigate and describe the effects of varying light intensity, carbon dioxide concentration and temperature on the rate of photosynthesis, e.g. in submerged aquatic plants"}],"supplement":[{"text":"State the balanced chemical equation for photosynthesis 6CO + 6H O → light C H O + 6O 2 2 chlorophyll 6 12 6 2"},{"text":"Explain that chlorophyll transfers light energy into chemical energy in molecules, for the synthesis of carbohydrates"},{"text":"Outline the subsequent use and storage of the carbohydrates made in photosynthesis"},{"text":"Define the term limiting factor as something present in the environment in such short supply that it restricts life processes"},{"text":"Identify and explain the limiting factors of photosynthesis in different environmental conditions"},{"text":"Describe the use of carbon dioxide enrichment, optimum light and optimum temperatures in glasshouses in temperate and tropical countries"},{"text":"Use hydrogencarbonate indicator solution to investigate the effect of gas exchange of an aquatic plant kept in the light and in the dark"}]},{"n":"6.2","title":"Leaf structure","core":[{"text":"Identify chloroplasts, cuticle, guard cells and stomata, upper and lower epidermis, palisade mesophyll, spongy mesophyll, vascular bundles, xylem and phloem in leaves of a dicotyledonous plant"}],"supplement":[{"text":"Explain how the internal structure of a leaf is adapted for photosynthesis"}]},{"n":"6.3","title":"Mineral requirements","core":[{"text":"Describe the importance of:\n– nitrate ions for making amino acids\n– magnesium ions for making chlorophyll"}],"supplement":[{"text":"Explain the effects of nitrate ion and magnesium ion deficiency on plant growth"}]}]},{"n":"7","title":"Human nutrition","sections":[{"n":"7.1","title":"Diet","core":[{"text":"State what is meant by the term balanced diet for humans"},{"text":"Explain how age, gender and activity affect the dietary needs of humans including during pregnancy and whilst breast-feeding"},{"text":"Describe the effects of malnutrition in relation to starvation, constipation, coronary heart disease, obesity and scurvy"},{"text":"List the principal sources of, and describe the dietary importance of:\n– carbohydrates\n– fats\n– proteins\n– vitamins, limited to C and D\n– mineral salts, limited to calcium and iron\n– fibre (roughage)\n– water"}],"supplement":[{"text":"Explain the causes and effects of vitamin D and iron deficiencies"},{"text":"Explain the causes and effects of protein-energy malnutrition, e.g. kwashiorkor and marasmus"}]},{"n":"7.2","title":"Alimentary canal","core":[{"text":"Define ingestion as the taking of substances, e.g. food and drink, into the body through the mouth"},{"text":"Define mechanical digestion as the breakdown of food into smaller pieces without chemical change to the food molecules"},{"text":"Define chemical digestion as the breakdown of large, insoluble molecules into small, soluble molecules"},{"text":"Define absorption as the movement of small food molecules and ions through the wall of the intestine into the blood"},{"text":"Define assimilation as the movement of digested food molecules into the cells of the body where they are used, becoming part of the cells"},{"text":"Define egestion as the passing out of food that has not been digested or absorbed, as faeces, through the anus"},{"text":"Describe diarrhoea as the loss of watery faeces"},{"text":"Outline the treatment of diarrhoea using oral rehydration therapy"},{"text":"Describe cholera as a disease caused by a bacterium"},{"text":"Identify the main regions of the alimentary canal and associated organs, limited to mouth, salivary glands, oesophagus, stomach, small intestine (duodenum and ileum), pancreas, liver, gall bladder and large intestine (colon, rectum, anus)"},{"text":"Describe the functions of the regions of the alimentary canal listed above, in relation to ingestion, digestion, absorption, assimilation and egestion of food"}],"supplement":[{"text":"Explain that the cholera bacterium produces a toxin that causes secretion of chloride ions into the small intestine, causing osmotic movement of water into the gut, causing diarrhoea, dehydration and loss of salts from blood"}]},{"n":"7.3","title":"Mechanical digestion","core":[{"text":"Identify the types of human teeth (incisors, canines, premolars and molars)"},{"text":"Describe the structure of human teeth, limited to enamel, dentine, pulp, nerves and cement, as well as the gums"},{"text":"Describe the functions of the types of human teeth in mechanical digestion of food"},{"text":"State the causes of dental decay in terms of a coating of bacteria and food on teeth, the bacteria respiring sugars in the food, producing acid which dissolves the enamel and dentine"},{"text":"Describe the proper care of teeth in terms of diet and regular brushing"}],"supplement":[]},{"n":"7.4","title":"Chemical digestion","core":[{"text":"State the significance of chemical digestion in the alimentary canal in producing small, soluble molecules that can be absorbed"},{"text":"State the functions of enzymes as follows:\n– amylase breaks down starch to simpler sugars\n– protease breaks down protein to amino acids\n– lipase breaks down fats to fatty acids and glycerol"},{"text":"State where, in the alimentary canal, amylase, protease and lipase are secreted"},{"text":"State the functions of the hydrochloric acid in gastric juice, limited to killing bacteria in food and giving an acid pH for enzymes"}],"supplement":[{"text":"Describe the digestion of starch in the alimentary canal:\n– amylase is secreted into the alimentary canal and breaks down starch to maltose\n– maltose is broken down by maltase to glucose on the membranes of the epithelium lining the small intestine"},{"text":"Describe pepsin and trypsin as two protease enzymes that function in different parts of the alimentary canal:\n– pepsin in the stomach\n– trypsin in the small intestine"},{"text":"Explain the functions of the hydrochloric acid in gastric juice, limited to the low pH:\n– denaturing enzymes in harmful microorganisms in food\n– giving the optimum pH for pepsin activity"},{"text":"Outline the role of bile in neutralising the acidic mixture of food and gastric juices entering the duodenum from the stomach, to provide a suitable pH for enzyme action"},{"text":"Outline the role of bile in emulsifying fats to increase the surface area for the chemical digestion of fat to fatty acids and glycerol by lipase"}]},{"n":"7.5","title":"Absorption","core":[{"text":"Identify the small intestine as the region for the absorption of digested food"},{"text":"State that water is absorbed in both the small intestine and the colon, but that most absorption of water happens in the small intestine"}],"supplement":[{"text":"Explain the significance of villi and microvilli in increasing the internal surface area of the small intestine"},{"text":"Describe the structure of a villus"},{"text":"Describe the roles of capillaries and lacteals in villi"}]}]},{"n":"8","title":"Transport in plants","sections":[{"n":"8.1","title":"Transport in plants","core":[{"text":"State the functions of xylem and phloem"},{"text":"Identify the position of xylem and phloem as seen in sections of roots, stems and leaves, limited to non-woody dicotyledonous plants"}],"supplement":[]},{"n":"8.2","title":"Water uptake","core":[{"text":"Identify root hair cells, as seen under the light microscope, and state their functions"},{"text":"State the pathway taken by water through root, stem and leaf as root hair cell, root cortex cells, xylem and mesophyll cells"},{"text":"Investigate, using a suitable stain, the pathway of water through the above-ground parts of a plant"}],"supplement":[{"text":"Explain that the large surface area of root hairs increases the rate of the absorption of water by osmosis and ions by active transport"}]},{"n":"8.3","title":"Transpiration","core":[{"text":"State that water is transported from the roots to leaves through the xylem vessels"},{"text":"Define transpiration as loss of water vapour from plant leaves by evaporation of water at the surfaces of the mesophyll cells followed by diffusion of water vapour through the stomata"},{"text":"Investigate and describe the effects of variation of temperature and humidity on transpiration rate"}],"supplement":[{"text":"Explain how water vapour loss is related to the large surface area of cell surfaces, interconnecting air spaces and stomata"},{"text":"Explain the mechanism by which water moves upwards in the xylem in terms of a transpiration pull that draws up a column of water molecules, held together by cohesion"},{"text":"Explain how and why wilting occurs"},{"text":"Explain the effects of variation of temperature and humidity on transpiration rate"}]},{"n":"8.4","title":"Translocation","core":[],"supplement":[{"text":"Define translocation in terms of the movement of sucrose and amino acids in phloem:\n– from regions of production (source)\n– to regions of storage OR to regions where they are used in respiration or growth (sink)"},{"text":"Explain that some parts of a plant may act as a source and a sink at different times during the life of a plant"}]}]},{"n":"9","title":"Transport in animals","sections":[{"n":"9.1","title":"Transport in animals","core":[{"text":"Describe the circulatory system as a system of blood vessels with a pump and valves to ensure one-way flow of blood"}],"supplement":[{"text":"Describe the single circulation of a fish"},{"text":"Describe the double circulation of a mammal"},{"text":"Explain the advantages of a double circulation"}]},{"n":"9.2","title":"Heart","core":[{"text":"Name and identify the structures of the mammalian heart, limited to the muscular wall, the septum, the left and right ventricles and atria, one-way valves and coronary arteries"},{"text":"State that blood is pumped away from the heart into arteries and returns to the heart in veins"},{"text":"State that the activity of the heart may be monitored by ECG, pulse rate and listening to sounds of valves closing"},{"text":"Investigate and state the effect of physical activity on the pulse rate"},{"text":"Describe coronary heart disease in terms of the blockage of coronary arteries and state the possible risk factors as diet, stress, smoking, genetic predisposition, age and gender"}],"supplement":[{"text":"Name and identify the atrioventricular and semilunar valves in the mammalian heart"},{"text":"Explain the relative thickness:\n– of the muscle wall of the left and right ventricles\n– of the muscle wall of the atria compared to that of the ventricles"},{"text":"Explain the importance of the septum in separating oxygenated and deoxygenated blood"},{"text":"Describe the functioning of the heart in terms of the contraction of muscles of the atria and ventricles and the action of the valves"},{"text":"Explain the effect of physical activity on the heart rate"},{"text":"Discuss the roles of diet and exercise in the prevention of coronary heart disease"},{"text":"Describe ways in which coronary heart disease may be treated, limited to drug treatment with aspirin and surgery (stents, angioplasty and by-pass)"}]},{"n":"9.3","title":"Blood and lymphatic vessels","core":[{"text":"Describe the structure and functions of arteries, veins and capillaries"},{"text":"Name the main blood vessels to and from the:\n– heart, limited to vena cava, aorta, pulmonary artery and pulmonary vein\n– lungs, limited to the pulmonary artery and pulmonary vein\n– kidney, limited to the renal artery and renal vein"}],"supplement":[{"text":"Explain how the structures of arteries, veins and capillaries are adapted for their functions"},{"text":"State the function of arterioles, venules and shunt vessels"},{"text":"Outline the lymphatic system in terms of lymphatic vessels and lymph nodes"},{"text":"Describe the function of the lymphatic system in the circulation of body fluids and the protection of the body from infection"}]},{"n":"9.4","title":"Blood","core":[{"text":"List the components of blood as red blood cells, white blood cells, platelets and plasma"},{"text":"Identify red and white blood cells, as seen under the light microscope, on prepared slides and in diagrams and photomicrographs"},{"text":"State the functions of the following components of blood:\n– red blood cells in transporting oxygen, including the role of haemoglobin\n– white blood cells in phagocytosis and antibody production\n– platelets in clotting (details are not required)\n– plasma in the transport of blood cells, ions, soluble nutrients, hormones and carbon dioxide"}],"supplement":[{"text":"Identify lymphocyte and phagocyte white blood cells, as seen under the light microscope, on prepared slides and in diagrams and photomicrographs"},{"text":"State the functions of:\n– lymphocytes – antibody production\n– phagocytes – phagocytosis"},{"text":"Describe the process of clotting as the conversion of fibrinogen to fibrin to form a mesh"},{"text":"State the roles of blood clotting as preventing blood loss and preventing the entry of pathogens"},{"text":"Describe the transfer of materials between capillaries and tissue fluid (details of the roles of water potential and hydrostatic pressure are not required)"}]}]},{"n":"10","title":"Diseases and immunity","sections":[{"n":"10.1","title":"Diseases and immunity","core":[{"text":"Define pathogen as a disease-causing organism"},{"text":"Define transmissible disease as a disease in which the pathogen can be passed from one host to another"},{"text":"State that the pathogen for a transmissible disease may be transmitted either through direct contact, e.g. through blood or other body fluids, or indirectly, e.g. from contaminated surfaces or food, from animals, or from the air"},{"text":"State that the body has defences:\n– mechanical barriers, limited to skin and hairs in the nose\n– chemical barriers, limited to mucus and stomach acid\n– cells, limited to phagocytosis and antibody production by white blood cells\n– which can be enhanced by vaccination"},{"text":"Explain the importance of hygienic food preparation, good personal hygiene, waste disposal and sewage treatment in controlling the spread of disease"}],"supplement":[{"text":"State that antibodies lock on to antigens leading to direct destruction of pathogens, or marking of pathogens for destruction by phagocytes"},{"text":"Explain how each pathogen has its own antigens, which have specific shapes, so specific antibodies which fit the specific shapes of the antigens are needed"},{"text":"Define active immunity as defence against a pathogen by antibody production in the body"},{"text":"Explain that active immunity is gained after an infection by a pathogen, or by vaccination"},{"text":"Explain the process of vaccination:\n– harmless pathogen given which has antigens\n– antigens trigger an immune response by lymphocytes which produce antibodies\n– memory cells are produced that give long-term immunity continued"},{"text":"Explain the role of vaccination in controlling the spread of diseases"},{"text":"Explain that passive immunity is short-term defence against a pathogen by antibodies acquired from another individual, e.g. mother to infant"},{"text":"State that memory cells are not produced in passive immunity"},{"text":"Explain the importance of passive immunity for breast-fed infants"},{"text":"State that some diseases are caused by the immune system targeting and destroying body cells, limited to Type 1 diabetes"}]}]},{"n":"11","title":"Gas exchange in humans","sections":[{"n":"11.1","title":"Gas exchange in humans","core":[{"text":"List the features of gas exchange surfaces in humans, limited to large surface area, thin surface, good blood supply and good ventilation with air"},{"text":"Name and identify the lungs, diaphragm, ribs, intercostal muscles, larynx, trachea, bronchi, bronchioles, alveoli and associated capillaries"},{"text":"State the differences in composition between inspired and expired air, limited to oxygen, carbon dioxide and water vapour"},{"text":"Use limewater as a test for carbon dioxide to investigate the differences in composition between inspired and expired air"},{"text":"Investigate and describe the effects of physical activity on rate and depth of breathing"}],"supplement":[{"text":"Name and identify the internal and external intercostal muscles"},{"text":"State the functions of the cartilage in the trachea"},{"text":"Explain the role of the ribs, the internal and external intercostal muscles and the diaphragm in producing volume and pressure changes in the thorax leading to the ventilation of the lungs"},{"text":"Explain the differences in composition between inspired and expired air"},{"text":"Explain the link between physical activity and rate and depth of breathing in terms of the increased carbon dioxide concentration in the blood, detected by the brain, causing an increased rate of breathing"},{"text":"Explain the role of goblet cells, mucus and ciliated cells in protecting the gas exchange system from pathogens and particles"}]}]},{"n":"12","title":"Respiration","sections":[{"n":"12.1","title":"Respiration","core":[{"text":"State the uses of energy in the body of humans: muscle contraction, protein synthesis, cell division, active transport, growth, the passage of nerve impulses and the maintenance of a constant body temperature"},{"text":"State that respiration involves the action of enzymes in cells"}],"supplement":[]},{"n":"12.2","title":"Aerobic respiration","core":[{"text":"Define aerobic respiration as the chemical reactions in cells that use oxygen to break down nutrient molecules to release energy"},{"text":"State the word equation for aerobic respiration as glucose + oxygen → carbon dioxide + water"},{"text":"Investigate the uptake of oxygen by respiring organisms, such as arthropods and germinating seeds"}],"supplement":[{"text":"State the balanced chemical equation for aerobic respiration as C6H12O6 + 6O2 → 6CO2 + 6H2O"},{"text":"Investigate the effect of temperature on the rate of respiration of germinating seeds"}]},{"n":"12.3","title":"Anaerobic respiration","core":[{"text":"Define anaerobic respiration as the chemical reactions in cells that break down nutrient molecules to release energy without using oxygen"},{"text":"State the word equations for anaerobic respiration in muscles during vigorous exercise (glucose → lactic acid) and the microorganism yeast (glucose → alcohol + carbon dioxide)"},{"text":"State that anaerobic respiration releases much less energy per glucose molecule than aerobic respiration"}],"supplement":[{"text":"State the balanced chemical equation for anaerobic respiration in the microorganism yeast as C6H12O6 → 2C2H5OH + 2CO2"},{"text":"State that lactic acid builds up in muscles and blood during vigorous exercise causing an oxygen debt"},{"text":"Outline how the oxygen debt is removed during recovery, limited to:\n– aerobic respiration of lactic acid in the liver\n– continuation, after exercise, of fast heart rate to transport lactic acid in blood from muscles to the liver\n– continuation, after exercise, of deeper breathing supplying oxygen for aerobic respiration of lactic acid"}]}]},{"n":"13","title":"Excretion in humans","sections":[{"n":"13.1","title":"Excretion in humans","core":[{"text":"State that urea is formed in the liver from excess amino acids"},{"text":"State that carbon dioxide is excreted through the lungs"},{"text":"State that the kidneys excrete urea and excess water and salts"},{"text":"Explain that the volume and concentration of urine produced is affected by water intake, temperature and exercise"},{"text":"Identify on drawings, diagrams and images, the ureters, bladder and urethra"}],"supplement":[{"text":"Describe the role of the liver in the assimilation of amino acids by converting them to proteins, including plasma proteins, e.g. fibrinogen"},{"text":"Define deamination as the removal of the nitrogen-containing part of amino acids to form urea"},{"text":"Explain the need for excretion, limited to toxicity of urea and carbon dioxide"},{"text":"Outline the structure of the kidney, limited to the cortex, medulla and ureter"},{"text":"Outline the structure and functioning of a kidney tubule, including:\n– the role of the glomerulus in the filtration from the blood of water, glucose, urea and salts\n– the role of the tubule in the reabsorption of all of the glucose, most of the water and some salts back into the blood, leading to the concentration of urea in the urine as well as loss of excess water and salts (details of these processes are not required)"},{"text":"Explain dialysis in terms of salt balance, the maintenance of glucose concentration and the removal of urea"},{"text":"Describe the use of dialysis in kidney machines"},{"text":"Discuss the advantages and disadvantages of kidney transplants, compared with dialysis"}]}]},{"n":"14","title":"Coordination and response","sections":[{"n":"14.1","title":"Nervous control in humans","core":[{"text":"Describe a nerve impulse as an electrical signal that passes along nerve cells called neurones"},{"text":"Describe the human nervous system in terms of:\n– the central nervous system consisting of brain and spinal cord\n– the peripheral nervous system\n– coordination and regulation of body functions"},{"text":"Identify motor (effector), relay (connector) and sensory neurones from diagrams"},{"text":"Describe a simple reflex arc in terms of receptor, sensory neurone, relay neurone, motor neurones and effector"},{"text":"Describe a reflex action as a means of automatically and rapidly integrating and coordinating stimuli with the responses of effectors (muscles and glands)"},{"text":"Define a synapse as a junction between two neurones"}],"supplement":[{"text":"Distinguish between voluntary and involuntary actions"},{"text":"Describe the structure of a synapse, including the presence of neurotransmitter containing vesicles, the synaptic cleft and neurotransmitter receptor molecules"},{"text":"Describe how an impulse triggers the release of a neurotransmitter from vesicles into the synaptic gap and how the neurotransmitter diffuses across to bind with receptor molecules, in the membrane of the neurone after the synaptic gap, causing the impulse to continue"},{"text":"State that in a reflex arc the synapses ensure that impulses travel in one direction only"},{"text":"State that many drugs, e.g. heroin, act upon synapses"}]},{"n":"14.2","title":"Sense organs","core":[{"text":"Define sense organs as groups of receptor cells responding to specific stimuli: light, sound, touch, temperature and chemicals"},{"text":"Identify the structures of the eye, limited to cornea, iris, pupil, lens, retina, optic nerve and blind spot"},{"text":"Describe the function of each part of the eye, limited to:\n– cornea – refracts light\n– iris – controls how much light enters pupil\n– lens – focuses light onto retina\n– retina – contains light receptors, some sensitive to light of different colours\n– optic nerve – carries impulses to the brain"},{"text":"Explain the pupil reflex in terms of light intensity and pupil diameter only"}],"supplement":[{"text":"Explain the pupil reflex in terms of light intensity and antagonistic action of circular and radial muscles in the iris"},{"text":"Explain accommodation to view near and distant objects in terms of the contraction and relaxation of the ciliary muscles, tension in the suspensory ligaments, shape of the lens and refraction of light"},{"text":"State the distribution of rods and cones in the retina of a human"},{"text":"Outline the function of rods and cones, limited to greater sensitivity of rods for night vision and three different kinds of cones absorbing light of different colours for colour vision"},{"text":"Identify the position of the fovea"}]},{"n":"14.3","title":"Hormones in humans","core":[{"text":"Define a hormone as a chemical substance, produced by a gland and carried by the blood, which alters the activity of one or more specific target organs"},{"text":"Identify specific endocrine glands and their secretions, limited to adrenal glands and adrenaline, pancreas and insulin, testes and testosterone and ovaries and oestrogen"},{"text":"Describe adrenaline as the hormone secreted in ‘fight or flight’ situations and its effects, limited to increased breathing and pulse rate and widened pupils"},{"text":"Give examples of situations in which adrenaline secretion increases"},{"text":"State the functions of insulin, oestrogen and testosterone"}],"supplement":[{"text":"Discuss the role of the hormone adrenaline in the chemical control of metabolic activity, including increasing the blood glucose concentration and pulse rate"},{"text":"Compare nervous and hormonal control systems in terms of speed and longevity of action"}]},{"n":"14.4","title":"Homeostasis","core":[{"text":"Define homeostasis as the maintenance of a constant internal environment"},{"text":"Name and identify on a diagram of the skin: hairs, hair erector muscles, sweat glands, receptors, sensory neurones, blood vessels and fatty tissue"},{"text":"Describe the maintenance of a constant internal body temperature in humans in terms of insulation, sweating, shivering and the role of the brain (limited to blood temperature receptors and coordination)"}],"supplement":[{"text":"Explain that homeostasis is the control of internal conditions within set limits"},{"text":"Explain the concept of control by negative feedback"},{"text":"Describe the control of the glucose concentration of the blood by the liver and the roles of insulin and glucagon from the pancreas"},{"text":"Outline the symptoms and treatment of Type 1 diabetes (detail of β cells is not required)"},{"text":"Describe the maintenance of a constant internal body temperature in humans in terms of vasodilation and vasoconstriction of arterioles supplying skin surface capillaries"}]},{"n":"14.5","title":"Tropic responses","core":[{"text":"Define gravitropism as a response in which parts of a plant grow towards or away from gravity"},{"text":"Define phototropism as a response in which parts of a plant grow towards or away from the direction from which light is coming"},{"text":"Investigate gravitropism and phototropism in shoots and roots"}],"supplement":[{"text":"Explain phototropism and gravitropism of a shoot as examples of the chemical control of plant growth"},{"text":"Explain the role of auxin in controlling shoot growth, limited to:\n– auxin made in shoot tip (only)\n– auxin spreads through the plant from the shoot tip\n– auxin is unequally distributed in response to light and gravity\n– auxin stimulates cell elongation"},{"text":"Describe the use in weedkillers of the synthetic plant hormone 2,4-D"}]}]},{"n":"15","title":"Drugs","sections":[{"n":"15.1","title":"Drugs","core":[{"text":"Define a drug as any substance taken into the body that modifies or affects chemical reactions in the body"}],"supplement":[]},{"n":"15.2","title":"Medicinal drugs","core":[{"text":"Describe the use of antibiotics for the treatment of bacterial infection"},{"text":"State that some bacteria are resistant to antibiotics which reduces the effectiveness of antibiotics"},{"text":"State that antibiotics kill bacteria but do not affect viruses"}],"supplement":[{"text":"Explain how development of resistant bacteria such as MRSA can be minimised, limited to using antibiotics only when essential and ensuring treatment is completed"},{"text":"Explain why antibiotics kill bacteria, but do not affect viruses"}]},{"n":"15.3","title":"Misused drugs","core":[{"text":"Describe the effects of excessive alcohol consumption and abuse of heroin, limited to:\n– powerful depressant drugs\n– effect on reaction times and self-control\n– addiction and withdrawal symptoms\n– negative social implications, e.g. crime"},{"text":"State that injecting heroin can cause infections such as HIV"},{"text":"State that excessive alcohol consumption can cause liver damage"},{"text":"State that tobacco smoking can cause chronic obstructive pulmonary disease (COPD), lung cancer and coronary heart disease"},{"text":"Describe the effects on the gas exchange system of tobacco smoke and its major toxic components, limited to carbon monoxide, nicotine and tar"},{"text":"State that the liver is the site of break down of alcohol and other toxins"}],"supplement":[{"text":"Explain how heroin affects the nervous system, limited to its effect on the function of synapses"},{"text":"Discuss the evidence for the link between smoking and lung cancer"},{"text":"Discuss the use of hormones to improve sporting performance, limited to testosterone and anabolic steroids"}]}]},{"n":"16","title":"Reproduction","sections":[{"n":"16.1","title":"Asexual reproduction","core":[{"text":"Define asexual reproduction as a process resulting in the production of genetically identical offspring from one parent"},{"text":"Identify examples of asexual reproduction from information provided"}],"supplement":[{"text":"Discuss the advantages and disadvantages of asexual reproduction:\n– to a population of a species in the wild\n– to crop production"}]},{"n":"16.2","title":"Sexual reproduction","core":[{"text":"Define sexual reproduction as a process involving the fusion of the nuclei of two gametes (sex cells) to form a zygote and the production of offspring that are genetically different from each other"},{"text":"Define fertilisation as the fusion of gamete nuclei"}],"supplement":[{"text":"State that the nuclei of gametes are haploid and that the nucleus of a zygote is diploid"},{"text":"Discuss the advantages and disadvantages of sexual reproduction:\n– to a population of a species in the wild\n– to crop production"}]},{"n":"16.3","title":"Sexual reproduction in plants","core":[{"text":"Identify and draw, using a hand lens if necessary, the sepals, petals, stamens, filaments and anthers, carpels, style, stigma, ovary and ovules, of an insect-pollinated flower"},{"text":"State the functions of the sepals, petals, anthers, stigmas and ovaries"},{"text":"Use a hand lens to identify and describe the anthers and stigmas of a wind-pollinated flower"},{"text":"Distinguish between the pollen grains of insect-pollinated and wind-pollinated flowers"},{"text":"Define pollination as the transfer of pollen grains from the anther to the stigma"},{"text":"State that fertilisation occurs when a pollen nucleus fuses with a nucleus in an ovule"},{"text":"Describe the structural adaptations of insect-pollinated and wind-pollinated flowers"},{"text":"Investigate and state the environmental conditions that affect germination of seeds, limited to the requirement for water, oxygen and a suitable temperature"}],"supplement":[{"text":"Define self-pollination as the transfer of pollen grains from the anther of a flower to the stigma of the same flower or different flower on the same plant"},{"text":"Define cross-pollination as transfer of pollen grains from the anther of a flower to the stigma of a flower on a different plant of the same species"},{"text":"Discuss the implications to a species of self-pollination and cross-pollination in terms of variation, capacity to respond to changes in the environment and reliance on pollinators"},{"text":"Describe the growth of the pollen tube and its entry into the ovule followed by fertilisation (details of production of endosperm and development are not required)"}]},{"n":"16.4","title":"Sexual reproduction in humans","core":[{"text":"Identify and name on diagrams of the male reproductive system: the testes, scrotum, sperm ducts, prostate gland, urethra and penis, and state the functions of these parts"},{"text":"Identify and name on diagrams of the female reproductive system: the ovaries, oviducts, uterus, cervix and vagina, and state the functions of these parts"},{"text":"Describe fertilisation as the fusion of the nuclei from a male gamete (sperm) and a female gamete (egg cell/ovum)"},{"text":"State the adaptive features of sperm, limited to flagellum and the presence of enzymes"},{"text":"State the adaptive features of egg cells, limited to energy stores and a jelly coating that changes after fertilisation"},{"text":"State that in early development, the zygote forms an embryo which is a ball of cells that implants into the wall of the uterus"},{"text":"State the functions of the umbilical cord, placenta, amniotic sac and amniotic fluid"},{"text":"Outline the growth and development of the fetus in terms of increasing complexity in the early stages and increasing size towards the end of pregnancy"},{"text":"Describe the ante-natal care of pregnant women, limited to special dietary needs and the harm from smoking and alcohol consumption"},{"text":"Outline the processes involved in labour and birth, limited to:\n– breaking of the amniotic sac\n– contraction of the muscles in the uterus wall\n– dilation of the cervix\n– passage through the vagina\n– tying and cutting the umbilical cord\n– delivery of the afterbirth"}],"supplement":[{"text":"Compare male and female gametes in terms of size, structure, motility and numbers"},{"text":"Explain the adaptive features of sperm, limited to flagellum, mitochondria and enzymes in the acrosome"},{"text":"Explain the adaptive features of egg cells, limited to energy stores and the jelly coat that changes at fertilisation"},{"text":"Describe the function of the placenta and umbilical cord in relation to exchange of dissolved nutrients, gases and excretory products and providing a barrier to toxins and pathogens (structural details are not required)"},{"text":"State that some toxins, e.g. nicotine, and pathogens, e.g. rubella virus, can pass across the placenta and affect the fetus"},{"text":"Discuss the advantages and disadvantages of breast-feeding compared with bottle-feeding using formula milk"}]},{"n":"16.5","title":"Sex hormones in humans","core":[{"text":"Describe the roles of testosterone and oestrogen in the development and regulation of secondary sexual characteristics during puberty"},{"text":"Describe the menstrual cycle in terms of changes in the ovaries and in the lining of the uterus"}],"supplement":[{"text":"Describe the sites of production of oestrogen and progesterone in the menstrual cycle and in pregnancy"},{"text":"Explain the role of hormones in controlling the menstrual cycle and pregnancy, limited to FSH, LH, progesterone and oestrogen"}]},{"n":"16.6","title":"Methods of birth control in humans","core":[{"text":"Outline the following methods of birth control:\n– natural, limited to abstinence, monitoring body temperature and cervical mucus\n– chemical, limited to IUD, IUS, contraceptive pill, implant and injection\n– barrier, limited to condom, femidom, diaphragm\n– surgical, limited to vasectomy and female sterilisation"}],"supplement":[{"text":"Outline the use of hormones in contraception and fertility treatments"},{"text":"Outline artificial insemination (AI)"},{"text":"Outline in vitro fertilisation (IVF)"},{"text":"Discuss the social implications of contraception and fertility treatments"}]},{"n":"16.7","title":"Sexually transmitted infections (STIs)","core":[{"text":"Define sexually transmitted infection as an infection that is transmitted via body fluids through sexual contact"},{"text":"State that human immunodeficiency virus (HIV) is an example of an STI"},{"text":"Explain how the spread of STIs is controlled"},{"text":"Describe the methods of transmission of HIV"},{"text":"State that HIV infection may lead to AIDS"}],"supplement":[{"text":"Outline how HIV affects the immune system, limited to decreased lymphocyte numbers and reduced ability to produce antibodies"}]}]},{"n":"17","title":"Inheritance","sections":[{"n":"17.1","title":"Inheritance","core":[{"text":"Define inheritance as the transmission of genetic information from generation to generation"}],"supplement":[]},{"n":"17.2","title":"Chromosomes, genes and proteins","core":[{"text":"Define chromosome as a thread-like structure of DNA, carrying genetic information in the form of genes"},{"text":"Define gene as a length of DNA that codes for a protein"},{"text":"Define allele as a version of a gene"},{"text":"Describe the inheritance of sex in humans with reference to XX and XY chromosomes"}],"supplement":[{"text":"Explain that the sequence of bases in a gene is the genetic code for putting together amino acids in the correct order to make a specific protein (knowledge of the details of nucleotide structure is not required)"},{"text":"Explain that DNA controls cell function by controlling the production of proteins (some of which are enzymes), antibodies and receptors for neurotransmitters"},{"text":"Explain how a protein is made, limited to:\n– the gene coding for the protein remains in the nucleus\n– mRNA molecules carry a copy of the gene to the cytoplasm\n– the mRNA passes through ribosomes\n– the ribosome assembles amino acids into protein molecules\n– the specific order of amino acids is determined by the sequence of bases in the mRNA (knowledge of the details of transcription or translation is not required)"},{"text":"Explain that all body cells in an organism contain the same genes, but many genes in a particular cell are not expressed because the cell only makes the specific proteins it needs continued"},{"text":"Define a haploid nucleus as a nucleus containing a single set of unpaired chromosomes, e.g. in gametes"},{"text":"Define a diploid nucleus as a nucleus containing two sets of chromosomes, e.g. in body cells"},{"text":"State that in a diploid cell, there is a pair of each type of chromosome and in a human diploid cell there are 23 pairs"}]},{"n":"17.3","title":"Mitosis","core":[{"text":"Define mitosis as nuclear division giving rise to genetically identical cells (details of stages are not required)"},{"text":"State the role of mitosis in growth, repair of damaged tissues, replacement of cells and asexual reproduction"}],"supplement":[{"text":"State that the exact duplication of chromosomes occurs before mitosis"},{"text":"State that during mitosis, the copies of chromosomes separate, maintaining the chromosome number (details of stages of mitosis are not required)"},{"text":"Describe stem cells as unspecialised cells that divide by mitosis to produce daughter cells that can become specialised for specific functions"}]},{"n":"17.4","title":"Meiosis","core":[{"text":"Define meiosis as nuclear division giving rise to cells that are genetically different (details of stages are not required)"},{"text":"State that meiosis is involved in the production of gametes"}],"supplement":[{"text":"Define meiosis as reduction division in which the chromosome number is halved from diploid to haploid resulting in genetically different cells (details of stages are not required)"},{"text":"Explain how meiosis produces variation by forming new combinations of maternal and paternal chromosomes (specific details are not required)"}]},{"n":"17.5","title":"Monohybrid inheritance","core":[{"text":"Define genotype as the genetic make-up of an organism in terms of the alleles present"},{"text":"Define phenotype as the observable features of an organism"},{"text":"Define homozygous as having two identical alleles of a particular gene"},{"text":"State that two identical homozygous individuals that breed together will be pure-breeding"},{"text":"Define heterozygous as having two different alleles of a particular gene"},{"text":"State that a heterozygous individual will not be pure-breeding"},{"text":"Define dominant as an allele that is expressed if it is present"},{"text":"Define recessive as an allele that is only expressed when there is no dominant allele of the gene present"},{"text":"Interpret pedigree diagrams for the inheritance of a given characteristic"},{"text":"Use genetic diagrams to predict the results of monohybrid crosses and calculate phenotypic ratios, limited to 1:1 and 3:1 ratios"},{"text":"Use Punnett squares in crosses which result in more than one genotype to work out and show the possible different genotypes"}],"supplement":[{"text":"Explain how to use a test cross to identify an unknown genotype"},{"text":"Explain co-dominance by reference to the inheritance of ABO blood groups – phenotypes being A, B, AB and O blood groups and alleles being IA, IB and Io"},{"text":"Define a sex-linked characteristic as a characteristic in which the gene responsible is located on a sex chromosome and that this makes it more common in one sex than in the other"},{"text":"Describe colour blindness as an example of sex linkage"},{"text":"Use genetic diagrams to predict the results of monohybrid crosses involving co-dominance or sex linkage and calculate phenotypic ratios"}]}]},{"n":"18","title":"Variation and selection","sections":[{"n":"18.1","title":"Variation","core":[{"text":"Define variation as differences between individuals of the same species"},{"text":"Distinguish between phenotypic variation and genetic variation"},{"text":"State that continuous variation results in a range of phenotypes between two extremes, e.g. height in humans"},{"text":"State that discontinuous variation results in a limited number of phenotypes with no intermediates, e.g. tongue rolling"},{"text":"Record and present the results of investigations into continuous and discontinuous variation"},{"text":"Define mutation as genetic change"},{"text":"State that mutation is the way in which new alleles are formed"},{"text":"State that ionising radiation and some chemicals increase the rate of mutation"}],"supplement":[{"text":"State that phenotypic variation is caused by both genetic and environmental factors"},{"text":"State that discontinuous variation is mostly caused by genes alone, e.g. A, B, AB and O blood groups in humans"},{"text":"Define gene mutation as a change in the base sequence of DNA"},{"text":"Describe the symptoms of sickle-cell anaemia"},{"text":"Explain how a change in the base sequence of the gene for haemoglobin results in abnormal haemoglobin and sickle-shaped red blood cells"},{"text":"Use genetic diagrams to show how sickle-cell anaemia is inherited"},{"text":"State that people who are heterozygous (HbS HbA) for the sickle-cell allele have a resistance to malaria"},{"text":"Explain the distribution of the sickle-cell allele in human populations with reference to the distribution of malaria (Teaching of human inherited conditions should be done with sensitivity at all times.)"}]},{"n":"18.2","title":"Adaptive features","core":[{"text":"Define adaptive feature as an inherited feature that helps an organism to survive and reproduce in its environment"},{"text":"Interpret images or other information about a species to describe its adaptive features"}],"supplement":[{"text":"Define adaptive feature as the inherited functional features of an organism that increase its fitness"},{"text":"Define fitness as the probability of an organism surviving and reproducing in the environment in which it is found"},{"text":"Explain the adaptive features of hydrophytes and xerophytes to their environments"}]},{"n":"18.3","title":"Selection","core":[{"text":"Describe natural selection with reference to:\n– variation within populations\n– production of many offspring\n– competition for resources\n– struggle for survival\n– reproduction by individuals that are better adapted to the environment than others\n– passing on of their alleles to the next generation"},{"text":"Describe selective breeding with reference to:\n– selection by humans of individuals with desirable features\n– crossing these individuals to produce the next generation\n– selection of offspring showing the desirable features"}],"supplement":[{"text":"Describe evolution as the change in adaptive features of a population over time as the result of natural selection"},{"text":"Define the process of adaptation as the process, resulting from natural selection, by which populations become more suited to their environment over many generations"},{"text":"Describe the development of strains of antibiotic resistant bacteria as an example of evolution by natural selection"},{"text":"State the differences between natural and artificial selection"},{"text":"Outline how selective breeding by artificial selection is carried out over many generations to improve crop plants and domesticated animals"}]}]},{"n":"19","title":"Organisms and their environment","sections":[{"n":"19.1","title":"Energy flow","core":[{"text":"State that the Sun is the principal source of energy input to biological systems"}],"supplement":[{"text":"Describe the flow of energy through living organisms including light energy from the sun and chemical energy in organisms and its eventual transfer to the environment"}]},{"n":"19.2","title":"Food chains and food webs","core":[{"text":"Define a food chain as showing the transfer of energy from one organism to the next, beginning with a producer"},{"text":"State that energy is transferred between organisms in a food chain by ingestion"},{"text":"Construct simple food chains"},{"text":"Define a food web as a network of interconnected food chains"},{"text":"Define producer as an organism that makes its own organic nutrients, usually using energy from sunlight, through photosynthesis"},{"text":"Define consumer as an organism that gets its energy by feeding on other organisms"},{"text":"State that consumers may be classed as primary, secondary and tertiary according to their position in a food chain"},{"text":"Define herbivore as an animal that gets its energy by eating plants"},{"text":"Define carnivore as an animal that gets its energy by eating other animals"},{"text":"Define decomposer as an organism that gets its energy from dead or waste organic material"},{"text":"Interpret food chains and food webs in terms of identifying producers and consumers"},{"text":"Use food chains and food webs to describe the impacts humans have through over-harvesting of food species and through introducing foreign species to a habitat"},{"text":"Draw, describe and interpret pyramids of numbers"}],"supplement":[{"text":"Describe how energy is transferred between trophic levels"},{"text":"Define trophic level as the position of an organism in a food chain, food web, pyramid of numbers or pyramid of biomass"},{"text":"Explain why the transfer of energy from one trophic level to another is inefficient"},{"text":"Explain why food chains usually have fewer than five trophic levels continued"},{"text":"Explain why there is a greater efficiency in supplying plants as human food, and that there is a relative inefficiency in feeding crop plants to livestock that will be used as food"},{"text":"Identify producers, primary consumers, secondary consumers, tertiary consumers and quaternary consumers as the trophic levels in food webs, food chains, pyramids of numbers and pyramids of biomass"},{"text":"Draw, describe and interpret pyramids of biomass"},{"text":"Discuss the advantages of using a pyramid of biomass rather than a pyramid of numbers to represent a food chain"}]},{"n":"19.3","title":"Nutrient cycles","core":[{"text":"Describe the carbon cycle, limited to photosynthesis, respiration, feeding, decomposition, fossilisation and combustion"},{"text":"Discuss the effects of the combustion of fossil fuels and the cutting down of forests on the carbon dioxide concentrations in the atmosphere"},{"text":"Describe the water cycle, limited to evaporation, transpiration, condensation and precipitation"}],"supplement":[{"text":"Describe the nitrogen cycle in terms of:\n– decomposition of plant and animal protein to ammonium ions\n– nitrification\n– nitrogen fixation by lightning and bacteria\n– absorption of nitrate ions by plants\n– production of amino acids and proteins\n– feeding and digestion of proteins\n– deamination\n– denitrification"},{"text":"State the roles of microorganisms in the nitrogen cycle, limited to decomposition, nitrification, nitrogen fixation and denitrification (generic names of individual bacteria, e.g. Rhizobium, are not required)"}]},{"n":"19.4","title":"Population size","core":[{"text":"Define population as a group of organisms of one species, living in the same area, at the same time"},{"text":"Identify and state the factors affecting the rate of population growth for a population of an organism, limited to food supply, predation and disease"},{"text":"Discuss the increase in human population size over the past 250 years and its social and environmental implications"},{"text":"Interpret graphs and diagrams of human population growth"}],"supplement":[{"text":"Define community as all of the populations of different species in an ecosystem"},{"text":"Define ecosystem as a unit containing the community of organisms and their environment, interacting together, e.g. a decomposing log, or a lake"},{"text":"Identify the lag, exponential (log), stationary and death phases in the sigmoid population growth curve for a population growing in an environment with limited resources"},{"text":"Explain the factors that lead to each phase in the sigmoid curve of population growth, making reference, where appropriate, to the role of limiting factors"}]}]},{"n":"20","title":"Biotechnology and genetic engineering","sections":[{"n":"20.1","title":"Biotechnology and genetic engineering","core":[{"text":"State that bacteria are useful in biotechnology and genetic engineering due to their rapid reproduction rate and their ability to make complex molecules"}],"supplement":[{"text":"Discuss why bacteria are useful in biotechnology and genetic engineering, limited to:\n– lack of ethical concerns over their manipulation and growth\n– genetic code shared with all other organisms\n– presence of plasmids"}]},{"n":"20.2","title":"Biotechnology","core":[{"text":"Describe the role of anaerobic respiration in yeast during production of ethanol for biofuels"},{"text":"Describe the role of anaerobic respiration in yeast during bread-making"},{"text":"Investigate and describe the use of pectinase in fruit juice production"},{"text":"Investigate and describe the use of biological washing powders that contain enzymes"}],"supplement":[{"text":"Investigate and explain the use of lactase to produce lactose-free milk"},{"text":"Describe the role of the fungus Penicillium in the production of the antibiotic penicillin"},{"text":"Explain how fermenters are used in the production of penicillin"}]},{"n":"20.3","title":"Genetic engineering","core":[{"text":"Define genetic engineering as changing the genetic material of an organism by removing, changing or inserting individual genes"},{"text":"State examples of genetic engineering:\n– the insertion of human genes into bacteria to produce human insulin\n– the insertion of genes into crop plants to confer resistance to herbicides\n– the insertion of genes into crop plants to confer resistance to insect pests\n– the insertion of genes into crop plants to provide additional vitamins"}],"supplement":[{"text":"Outline genetic engineering using bacterial production of a human protein as an example, limited to:\n– isolation of the DNA making up a human gene using restriction enzymes, forming sticky ends\n– cutting of bacterial plasmid DNA with the same restriction enzymes, forming complementary sticky ends\n– insertion of human DNA into bacterial plasmid DNA using DNA ligase to form a recombinant plasmid\n– insertion of plasmid into bacteria (specific detail is not required)\n– replication of bacteria containing recombinant plasmids which make human protein as they express the gene"},{"text":"Discuss the advantages and disadvantages of genetically modifying crops, such as soya, maize and rice"}]}]},{"n":"21","title":"Human influences on ecosystems","sections":[{"n":"21.1","title":"Food supply","core":[{"text":"State how modern technology has resulted in increased food production in terms of:\n– agricultural machinery to use larger areas of land and improve efficiency\n– chemical fertilisers to improve yields\n– insecticides to improve quality and yield\n– herbicides to reduce competition with weeds\n– selective breeding to improve production by crop plants and livestock, e.g. cattle, fish and poultry"},{"text":"Describe the negative impacts to an ecosystem of large-scale monocultures of crop plants"},{"text":"Describe the negative impacts to an ecosystem of intensive livestock production"}],"supplement":[{"text":"Discuss the social, environmental and economic implications of providing sufficient food for an increasing human global population"},{"text":"Discuss the problems which contribute to famine including unequal distribution of food, drought and flooding, increasing population and poverty"}]},{"n":"21.2","title":"Habitat destruction","core":[{"text":"Describe the reasons for habitat destruction, limited to:\n– increased area for food crop growth, livestock production and housing\n– extraction of natural resources\n– marine pollution"},{"text":"State that through altering food webs and food chains, humans can have a negative impact on habitats"},{"text":"List the undesirable effects of deforestation as an example of habitat destruction, to include extinction, loss of soil, flooding and increase of carbon dioxide in the atmosphere"}],"supplement":[{"text":"Explain the undesirable effects of deforestation on the environment"}]},{"n":"21.3","title":"Pollution","core":[{"text":"State the sources and effects of pollution of land and water, e.g. rivers, lakes and the sea, by insecticides, herbicides and by nuclear fall-out"},{"text":"State the sources and effects of pollution of water (rivers, lakes and the sea) by chemical waste, discarded rubbish, untreated sewage and fertilisers"},{"text":"State the sources and effects of pollution of the air by methane and carbon dioxide, limited to the enhanced greenhouse effect and climate change"}],"supplement":[{"text":"Explain the process of eutrophication of water in terms of:\n– increased availability of nitrate and other ions\n– increased growth of producers\n– increased decomposition after death of producers\n– increased aerobic respiration by decomposers\n– reduction in dissolved oxygen\n– death of organisms requiring dissolved oxygen in water"},{"text":"Discuss the effects of non-biodegradable plastics in the environment, in both aquatic and terrestrial ecosystems"},{"text":"Discuss the causes and effects on the environment of acid rain"},{"text":"State the measures that are taken to reduce sulfur dioxide pollution and reduce the impact of acid rain"},{"text":"Explain how increases in carbon dioxide and methane concentrations in the atmosphere cause an enhanced greenhouse effect that leads to climate change"},{"text":"Describe the negative impacts of female contraceptive hormones in water courses, limited to reduced sperm count in men and feminisation of aquatic organisms"}]},{"n":"21.4","title":"Conservation","core":[{"text":"Define a sustainable resource as one which is produced as rapidly as it is removed from the environment so that it does not run out"},{"text":"Explain the need to conserve non-renewable resources, limited to fossil fuels"},{"text":"State that some resources can be maintained, limited to forests and fish stocks"},{"text":"State that products can be reused or recycled, limited to paper, glass, plastic and metal"},{"text":"Outline how sewage is treated to make the water that it contains safe to return to the environment or for human use"},{"text":"Explain why organisms become endangered or extinct, limited to climate change, habitat destruction, hunting, pollution and introduced species"},{"text":"Describe how endangered species can be conserved, limited to monitoring and protecting species and habitats, education, captive breeding programmes and seed banks"}],"supplement":[{"text":"Define the term sustainable development as development providing for the needs of an increasing human population without harming the environment"},{"text":"Explain how forests and fish stocks can be sustained using education, legal quotas and re‑stocking"},{"text":"Explain that sustainable development requires:\n– management of conflicting demands\n– planning and co-operation at local, national and international levels"},{"text":"Explain the risks to a species if the population size drops, reducing variation (knowledge of genetic drift is not required)"},{"text":"Explain reasons for conservation programmes, to include:\n– reducing extinction\n– protecting vulnerable environments\n– maintaining ecosystem functions, limited to nutrient cycling and resource provision, e.g. food, drugs, fuel and genes"}]}]}]},{"id":"2016-2018","label":"2016–2018","until":"2018","numbered":false,"source":{"title":"Cambridge IGCSE Biology 0610, for examination in 2016, 2017 and 2018","url":"https://www.cambridgeinternational.org/images/167733-2016-2018-syllabus.pdf","via":"web.archive.org, 25 May 2022 (no longer on Cambridge's site)"},"topics":[{"n":"1","title":"Characteristics and classification of living organisms","sections":[{"n":"1.1","title":"Characteristics of living organisms","core":[{"text":"Describe the characteristics of living organisms by defining the terms:\n– movement as an action by an organism causing a change of position or place\n– respiration as the chemical reactions in cells that break down nutrient molecules and release energy\n– sensitivity as the ability to detect and respond to changes in the environment\n– growth as a permanent increase in size\n– reproduction as the processes that make more of the same kind of organism\n– excretion as removal from organisms of toxic materials and substances in excess of requirements\n– nutrition as taking in of materials for energy, growth and development"}],"supplement":[{"text":"Define the terms:\n– movement as an action by an organism or part of an organism causing a change of position or place\n– respiration as the chemical reactions in cells that break down nutrient molecules and release energy for metabolism\n– sensitivity as the ability to detect or sense stimuli in the internal or external environment and to make appropriate responses\n– growth as a permanent increase in size and dry mass by an increase in cell number or cell size or both\n– excretion as removal from organisms of the waste products of metabolism (chemical reactions in cells including respiration), toxic materials, and substances in excess of requirements\n– nutrition as taking in of materials for energy, growth and development; plants require light, carbon dioxide, water and ions; animals need organic compounds and ions and usually need water"}]},{"n":"1.2","title":"Concept and use of a classification system","core":[{"text":"State that organisms can be classified into groups by the features that they share"},{"text":"Define species as a group of organisms that can reproduce to produce fertile offspring"},{"text":"Define and describe the binomial system of naming species as an internationally agreed system in which the scientific name of an organism is made up of two parts showing the genus and species"}],"supplement":[{"text":"Explain that classification systems aim to reflect evolutionary relationships"},{"text":"Explain that classification is traditionally based on studies of morphology and anatomy"},{"text":"Explain that the sequences of bases in DNA and of amino acids in proteins are used as a more accurate means of classification"},{"text":"Explain that organisms which share a more recent ancestor (are more closely related) have base sequences in DNA that are more similar than those that share only a distant ancestor"}]},{"n":"1.3","title":"Features of organisms","core":[{"text":"List the features in the cells of all living organisms, limited to cytoplasm, cell membrane and DNA as genetic material"},{"text":"List the main features used to place animals and plants into the appropriate kingdoms"},{"text":"List the main features used to place organisms into groups within the animal kingdom, limited to:\n– the main groups of vertebrates: mammals, birds, reptiles, amphibians, fish\n– the main groups of arthropods: myriapods, insects, arachnids, crustaceans"}],"supplement":[{"text":"List the features in the cells of all living organisms, limited to ribosomes for protein synthesis and enzymes involved in respiration"},{"text":"List the main features used to place all organisms into one of the five kingdoms: Animal, Plant, Fungus, Prokaryote, Protoctist"},{"text":"List the main features used to place organisms into groups within the plant kingdom, limited to ferns and flowering plants (dicotyledons and monocotyledons)"},{"text":"List the features of viruses, limited to protein coat and genetic material"}]},{"n":"1.4","title":"Dichotomous keys","core":[{"text":"Construct and use simple dichotomous keys based on easily identifiable features"}],"supplement":[]}]},{"n":"2","title":"Organisation of the organism","sections":[{"n":"2.1","title":"Cell structure and organisation","core":[{"text":"Describe and compare the structure of a plant cell with an animal cell, as seen under a light microscope, limited to cell wall, nucleus, cytoplasm, chloroplasts, vacuoles and location of the cell membrane"},{"text":"State the functions of the structures seen under the light microscope in the plant cell and in the animal cell"}],"supplement":[{"text":"State that the cytoplasm of all cells contains structures, limited to ribosomes on rough endoplasmic reticulum and vesicles"},{"text":"State that almost all cells, except prokaryotes, have mitochondria and rough endoplasmic reticulum"},{"text":"Identify mitochondria and rough endoplasmic reticulum in diagrams and images of cells"},{"text":"State that aerobic respiration occurs in mitochondria"},{"text":"State that cells with high rates of metabolism require large numbers of mitochondria to provide sufficient energy"}]},{"n":"2.2","title":"Levels of organisation","core":[{"text":"Relate the structure of the following to their functions:\n– ciliated cells – movement of mucus in the trachea and bronchi\n– root hair cells – absorption\n– xylem vessels – conduction and support\n– palisade mesophyll cells – photosynthesis\n– nerve cells – conduction of impulses\n– red blood cells – transport of oxygen\n– sperm and egg cells – reproduction"},{"text":"Define tissue as a group of cells with similar structures, working together to perform a shared function"},{"text":"Define organ as a structure made up of a group of tissues, working together to perform specific functions"},{"text":"Define organ system as a group of organs with related functions, working together to perform body functions"},{"text":"State examples of tissues, organs and organ systems from sections 6 to 16"},{"text":"Identify the different levels of organisation in drawings, diagrams and images of familiar material"}],"supplement":[{"text":"Identify the different levels of organisation in drawings, diagrams and images of unfamiliar material"}]},{"n":"2.3","title":"Size of specimens","core":[{"text":"Calculate magnification and size of biological specimens using millimetres as units"}],"supplement":[{"text":"Calculate magnification and size of biological specimens using millimetres and micrometres as units"}]}]},{"n":"3","title":"Movement in and out of cells","sections":[{"n":"3.1","title":"Diffusion","core":[{"text":"Define diffusion as the net movement of particles from a region of their higher concentration to a region of their lower concentration down a concentration gradient, as a result of their random movement"},{"text":"Describe the importance of diffusion of gases and solutes"},{"text":"State that substances move into and out of cells by diffusion through the cell membrane"}],"supplement":[{"text":"State that the energy for diffusion comes from the kinetic energy of random movement of molecules and ions"},{"text":"Investigate the factors that influence diffusion, limited to surface area, temperature, concentration gradients and distance"}]},{"n":"3.2","title":"Osmosis","core":[{"text":"State that water diffuses through partially permeable membranes by osmosis"},{"text":"State that water moves in and out of cells by osmosis through the cell membrane"},{"text":"Investigate and describe the effects on plant tissues of immersing them in solutions of different concentrations"},{"text":"State that plants are supported by the pressure of water inside the cells pressing outwards on the cell wall"}],"supplement":[{"text":"Define osmosis as the net movement of water molecules from a region of higher water potential (dilute solution) to a region of lower water potential (concentrated solution), through a partially permeable membrane"},{"text":"Explain the effects on plant tissues of immersing them in solutions of different concentrations by using the terms turgid, turgor pressure, plasmolysis and flaccid"},{"text":"Explain the importance of water potential and osmosis in the uptake of water by plants"},{"text":"Explain the importance of water potential and osmosis on animal cells and tissues"},{"text":"Explain how plants are supported by the turgor pressure within cells, in terms of water pressure acting against an inelastic cell wall"}]},{"n":"3.3","title":"Active transport","core":[{"text":"Define active transport as the movement of particles through a cell membrane from a region of lower concentration to a region of higher concentration using energy from respiration"}],"supplement":[{"text":"Discuss the importance of active transport as a process for movement across membranes:\n– e.g. ion uptake by root hairs and uptake of glucose by epithelial cells of villi and kidney tubules"},{"text":"Explain how protein molecules move particles across a membrane during active transport"}]}]},{"n":"4","title":"Biological molecules","sections":[{"n":"4","title":"Biological molecules","core":[{"text":"List the chemical elements that make up:\n– carbohydrates\n– fats\n– proteins"},{"text":"State that large molecules are made from smaller molecules, limited to:\n– starch and glycogen from glucose\n– cellulose from glucose\n– proteins from amino acids\n– fats and oils from fatty acids and glycerol"},{"text":"Describe the use of:\n– iodine solution to test for starch\n– Benedict’s solution to test for reducing sugars\n– biuret test for proteins\n– ethanol emulsion test for fats and oils\n– DCPIP test for vitamin C 4. Biological molecules continued"},{"text":"State that water is important as a solvent"}],"supplement":[{"text":"Explain that different sequences of amino acids give different shapes to protein molecules"},{"text":"Relate the shape and structure of protein molecules to their function, limited to the active site of enzymes and the binding site of antibodies cont."},{"text":"Describe the structure of DNA as:\n– two strands coiled together to form a double helix\n– each strand contains chemicals called bases\n– cross-links between the strands are formed by pairs of bases\n– the bases always pair up in the same way: A with T, and C with G (full names are not required)"},{"text":"Describe the roles of water as a solvent in organisms with respect to digestion, excretion and transport"}]}]},{"n":"5","title":"Enzymes","sections":[{"n":"5","title":"Enzymes","core":[{"text":"Define the term catalyst as a substance that increases the rate of a chemical reaction and is not changed by the reaction"},{"text":"Define enzymes as proteins that function as biological catalysts"},{"text":"Describe why enzymes are important in all living organisms in terms of reaction speed necessary to sustain life"},{"text":"Describe enzyme action with reference to the complementary shape of an enzyme and its substrate and the formation of a product (knowledge of the term active site is not required)"},{"text":"Investigate and describe the effect of changes in temperature and pH on enzyme activity"}],"supplement":[{"text":"Explain enzyme action with reference to the active site, enzyme-substrate complex, substrate and product"},{"text":"Explain the specificity of enzymes in terms of the complementary shape and fit of the active site with the substrate"},{"text":"Explain the effect of changes in temperature on enzyme activity in terms of kinetic energy, shape and fit, frequency of effective collisions and denaturation"},{"text":"Explain the effect of changes in pH on enzyme activity in terms of shape and fit and denaturation"}]}]},{"n":"6","title":"Plant nutrition","sections":[{"n":"6.1","title":"Photosynthesis","core":[{"text":"Define photosynthesis as the process by which plants manufacture carbohydrates from raw materials using energy from light"},{"text":"State the word equation for photosynthesis: carbon dioxide + water → glucose + oxygen, in the presence of light and chlorophyll"},{"text":"Investigate the necessity for chlorophyll, light and carbon dioxide for photosynthesis, using appropriate controls"},{"text":"Investigate and describe the effects of varying light intensity, carbon dioxide concentration and temperature on the rate of photosynthesis, e.g. in submerged aquatic plants"}],"supplement":[{"text":"State the balanced chemical equation for photosynthesis light 6CO + 6H O → C H O + 6O 2 2 chlorophyll 6 12 6 2"},{"text":"Explain that chlorophyll transfers light energy into chemical energy in molecules, for the synthesis of carbohydrates"},{"text":"Outline the subsequent use and storage of the carbohydrates made in photosynthesis"},{"text":"Define the term limiting factor as something present in the environment in such short supply that it restricts life processes"},{"text":"Identify and explain the limiting factors of photosynthesis in different environmental conditions"},{"text":"Describe the use of carbon dioxide enrichment, optimum light and optimum temperatures in glasshouses in temperate and tropical countries"},{"text":"Use hydrogencarbonate indicator solution to investigate the effect of gas exchange of an aquatic plant kept in the light and in the dark"}]},{"n":"6.2","title":"Leaf structure","core":[{"text":"Identify chloroplasts, cuticle, guard cells and stomata, upper and lower epidermis, palisade mesophyll, spongy mesophyll, vascular bundles, xylem and phloem in leaves of a dicotyledonous plant"}],"supplement":[{"text":"Explain how the internal structure of a leaf is adapted for photosynthesis"}]},{"n":"6.3","title":"Mineral requirements","core":[{"text":"Describe the importance of:\n– nitrate ions for making amino acids\n– magnesium ions for making chlorophyll"}],"supplement":[{"text":"Explain the effects of nitrate ion and magnesium ion deficiency on plant growth"}]}]},{"n":"7","title":"Human nutrition","sections":[{"n":"7.1","title":"Diet","core":[{"text":"State what is meant by the term balanced diet for humans"},{"text":"Explain how age, gender and activity affect the dietary needs of humans including during pregnancy and whilst breast-feeding"},{"text":"Describe the effects of malnutrition in relation to starvation, constipation, coronary heart disease, obesity and scurvy"},{"text":"List the principal sources of, and describe the dietary importance of:\n– carbohydrates\n– fats\n– proteins\n– vitamins, limited to C and D\n– mineral salts, limited to calcium and iron\n– fibre (roughage)\n– water"}],"supplement":[{"text":"Explain the causes and effects of vitamin D and iron deficiencies"},{"text":"Explain the causes and effects of protein-energy malnutrition, e.g. kwashiorkor and marasmus"}]},{"n":"7.2","title":"Alimentary canal","core":[{"text":"Define ingestion as the taking of substances, e.g. food and drink, into the body through the mouth"},{"text":"Define mechanical digestion as the breakdown of food into smaller pieces without chemical change to the food molecules"},{"text":"Define chemical digestion as the breakdown of large, insoluble molecules into small, soluble molecules"},{"text":"Define absorption as the movement of small food molecules and ions through the wall of the intestine into the blood"},{"text":"Define assimilation as the movement of digested food molecules into the cells of the body where they are used, becoming part of the cells"},{"text":"Define egestion as the passing out of food that has not been digested or absorbed, as faeces, through the anus"},{"text":"Describe diarrhoea as the loss of watery faeces"},{"text":"Outline the treatment of diarrhoea using oral rehydration therapy"},{"text":"Describe cholera as a disease caused by a bacterium"},{"text":"Identify the main regions of the alimentary canal and associated organs, limited to mouth, salivary glands, oesophagus, stomach, small intestine (duodenum and ileum), pancreas, liver, gall bladder and large intestine (colon, rectum, anus)"},{"text":"Describe the functions of the regions of the alimentary canal listed above, in relation to ingestion, digestion, absorption, assimilation and egestion of food"}],"supplement":[{"text":"Explain that the cholera bacterium produces a toxin that causes secretion of chloride ions into the small intestine, causing osmotic movement of water into the gut, causing diarrhoea, dehydration and loss of salts from blood"}]},{"n":"7.3","title":"Mechanical digestion","core":[{"text":"Identify the types of human teeth (incisors, canines, premolars and molars)"},{"text":"Describe the structure of human teeth, limited to enamel, dentine, pulp, nerves and cement, as well as the gums"},{"text":"Describe the functions of the types of human teeth in mechanical digestion of food"},{"text":"State the causes of dental decay in terms of a coating of bacteria and food on teeth, the bacteria respiring sugars in the food, producing acid which dissolves the enamel and dentine"},{"text":"Describe the proper care of teeth in terms of diet and regular brushing"}],"supplement":[]},{"n":"7.4","title":"Chemical digestion","core":[{"text":"State the significance of chemical digestion in the alimentary canal in producing small, soluble molecules that can be absorbed"},{"text":"State the functions of enzymes as follows:\n– amylase breaks down starch to simpler sugars\n– protease breaks down protein to amino acids\n– lipase breaks down fats to fatty acids and glycerol"},{"text":"State where, in the alimentary canal, amylase, protease and lipase are secreted"},{"text":"State the functions of the hydrochloric acid in gastric juice, limited to killing bacteria in food and giving an acid pH for enzymes"}],"supplement":[{"text":"Describe the digestion of starch in the alimentary canal:\n– amylase is secreted into the alimentary canal and breaks down starch to maltose\n– maltose is broken down by maltase to glucose on the membranes of the epithelium lining the small intestine"},{"text":"Describe pepsin and trypsin as two protease enzymes that function in different parts of the alimentary canal:\n– pepsin in the stomach\n– trypsin in the small intestine"},{"text":"Explain the functions of the hydrochloric acid in gastric juice, limited to the low pH:\n– denaturing enzymes in harmful microorganisms in food\n– giving the optimum pH for pepsin activity"},{"text":"Outline the role of bile in neutralising the acidic mixture of food and gastric juices entering the duodenum from the stomach, to provide a suitable pH for enzyme action"},{"text":"Outline the role of bile in emulsifying fats to increase the surface area for the chemical digestion of fat to fatty acids and glycerol by lipase"}]},{"n":"7.5","title":"Absorption","core":[{"text":"Identify the small intestine as the region for the absorption of digested food"},{"text":"State that water is absorbed in both the small intestine and the colon, but that most absorption of water happens in the small intestine"}],"supplement":[{"text":"Explain the significance of villi and microvilli in increasing the internal surface area of the small intestine"},{"text":"Describe the structure of a villus"},{"text":"Describe the roles of capillaries and lacteals in villi"}]}]},{"n":"8","title":"Transport in plants","sections":[{"n":"8.1","title":"Transport in plants","core":[{"text":"State the functions of xylem and phloem"},{"text":"Identify the position of xylem and phloem as seen in sections of roots, stems and leaves, limited to non-woody dicotyledonous plants"}],"supplement":[]},{"n":"8.2","title":"Water uptake","core":[{"text":"Identify root hair cells, as seen under the light microscope, and state their functions"},{"text":"State the pathway taken by water through root, stem and leaf as root hair cell, root cortex cells, xylem and mesophyll cells"},{"text":"Investigate, using a suitable stain, the pathway of water through the above ground parts of a plant"}],"supplement":[{"text":"Explain that the large surface area of root hairs increases the rate of the absorption of water by osmosis and ions by active transport"}]},{"n":"8.3","title":"Transpiration","core":[{"text":"State that water is transported from the roots to leaves through the xylem vessels"},{"text":"Define transpiration as loss of water vapour from plant leaves by evaporation of water at the surfaces of the mesophyll cells followed by diffusion of water vapour through the stomata"},{"text":"Investigate and describe the effects of variation of temperature and humidity on transpiration rate"}],"supplement":[{"text":"Explain how water vapour loss is related to the large surface area of cell surfaces, interconnecting air spaces and stomata"},{"text":"Explain the mechanism by which water moves upwards in the xylem in terms of a transpiration pull that draws up a column of water molecules, held together by cohesion"},{"text":"Explain how and why wilting occurs"},{"text":"Explain the effects of variation of temperature and humidity on transpiration rate"}]},{"n":"8.4","title":"Translocation","core":[],"supplement":[{"text":"Define translocation in terms of the movement of sucrose and amino acids in phloem:\n– from regions of production (source)\n– to regions of storage OR to regions where they are used in respiration or growth (sink)"},{"text":"Explain that some parts of a plant may act as a source and a sink at different times during the life of a plant"}]}]},{"n":"9","title":"Transport in animals","sections":[{"n":"9.1","title":"Transport in animals","core":[{"text":"Describe the circulatory system as a system of blood vessels with a pump and valves to ensure one-way flow of blood"}],"supplement":[{"text":"Describe the single circulation of a fish"},{"text":"Describe the double circulation of a mammal"},{"text":"Explain the advantages of a double circulation"}]},{"n":"9.2","title":"Heart","core":[{"text":"Name and identify the structures of the mammalian heart, limited to the muscular wall, the septum, the left and right ventricles and atria, one-way valves and coronary arteries"},{"text":"State that blood is pumped away from the heart into arteries and returns to the heart in veins"},{"text":"State that the activity of the heart may be monitored by ECG, pulse rate and listening to sounds of valves closing"},{"text":"Investigate and state the effect of physical activity on the pulse rate"},{"text":"Describe coronary heart disease in terms of the blockage of coronary arteries and state the possible risk factors as diet, stress, smoking, genetic predisposition, age and gender"}],"supplement":[{"text":"Name and identify the atrioventricular and semilunar valves in the mammalian heart"},{"text":"Explain the relative thickness:\n– of the muscle wall of the left and right ventricles\n– of the muscle wall of the atria compared to that of the ventricles"},{"text":"Explain the importance of the septum in separating oxygenated and deoxygenated blood"},{"text":"Describe the functioning of the heart in terms of the contraction of muscles of the atria and ventricles and the action of the valves"},{"text":"Explain the effect of physical activity on the heart rate"},{"text":"Discuss the roles of diet and exercise in the prevention of coronary heart disease"},{"text":"Describe ways in which coronary heart disease may be treated, limited to drug treatment with aspirin and surgery (stents, angioplasty and by-pass)"}]},{"n":"9.3","title":"Blood and lymphatic vessels","core":[{"text":"Describe the structure and functions of arteries, veins and capillaries"},{"text":"Name the main blood vessels to and from the:\n– heart, limited to vena cava, aorta, pulmonary artery and pulmonary vein\n– lungs, limited to the pulmonary artery and pulmonary vein\n– kidney, limited to the renal artery and renal vein"}],"supplement":[{"text":"Explain how the structures of arteries, veins and capillaries are adapted for their functions"},{"text":"State the function of arterioles, venules and shunt vessels"},{"text":"Outline the lymphatic system in terms of lymphatic vessels and lymph nodes"},{"text":"Describe the function of the lymphatic system in the circulation of body fluids and the protection of the body from infection"}]},{"n":"9.4","title":"Blood","core":[{"text":"List the components of blood as red blood cells, white blood cells, platelets and plasma"},{"text":"Identify red and white blood cells, as seen under the light microscope, on prepared slides and in diagrams and photomicrographs"},{"text":"State the functions of the following components of blood:\n– red blood cells in transporting oxygen, including the role of haemoglobin\n– white blood cells in phagocytosis and antibody production\n– platelets in clotting (details are not required)\n– plasma in the transport of blood cells, ions, soluble nutrients, hormones and carbon dioxide"}],"supplement":[{"text":"Identify lymphocyte and phagocyte white blood cells, as seen under the light microscope, on prepared slides and in diagrams and photomicrographs"},{"text":"State the functions of:\n– lymphocytes – antibody production\n– phagocytes – phagocytosis"},{"text":"Describe the process of clotting as the conversion of fibrinogen to fibrin to form a mesh"},{"text":"State the roles of blood clotting as preventing blood loss and preventing the entry of pathogens"},{"text":"Describe the transfer of materials between capillaries and tissue fluid (details of the roles of water potential and hydrostatic pressure are not required)"}]}]},{"n":"10","title":"Diseases and immunity","sections":[{"n":"10","title":"Diseases and immunity","core":[{"text":"Define pathogen as a disease-causing organism"},{"text":"Define transmissible disease as a disease in which the pathogen can be passed from one host to another"},{"text":"State that the pathogen for a transmissible disease may be transmitted either through direct contact, e.g. through blood or other body fluids, or indirectly, e.g. from contaminated surfaces or food, from animals, or from the air"},{"text":"State that the body has defences:\n– mechanical barriers, limited to skin and hairs in the nose\n– chemical barriers, limited to mucus and stomach acid\n– cells, limited to phagocytosis and antibody production by white blood cells\n– which can be enhanced by vaccination"},{"text":"Explain the importance of hygienic food preparation, good personal hygiene, waste disposal and sewage treatment in controlling the spread of disease"}],"supplement":[{"text":"State that antibodies lock on to antigens leading to direct destruction of pathogens, or marking of pathogens for destruction by phagocytes"},{"text":"Explain how each pathogen has its own antigens, which have specific shapes, so specific antibodies which fit the specific shapes of the antigens are needed"},{"text":"Define active immunity as defence against a pathogen by antibody production in the body"},{"text":"Explain that active immunity is gained after an infection by a pathogen, or by vaccination"},{"text":"Explain the process of vaccination:\n– harmless pathogen given which has antigens\n– antigens trigger an immune response by lymphocytes which produce antibodies\n– memory cells are produced that give long-term immunity"},{"text":"Explain the role of vaccination in controlling the spread of diseases"},{"text":"Explain that passive immunity is short-term defence against a pathogen by antibodies acquired from another individual, e.g. mother to infant"},{"text":"State that memory cells are not produced in passive immunity"},{"text":"Explain the importance of passive immunity for breast-fed infants"},{"text":"State that some diseases are caused by the immune system targeting and destroying body cells, limited to Type 1 diabetes"}]}]},{"n":"11","title":"Gas exchange in humans","sections":[{"n":"11","title":"Gas exchange in humans","core":[{"text":"List the features of gas exchange surfaces in humans, limited to large surface area, thin surface, good blood supply and good ventilation with air"},{"text":"Name and identify the lungs, diaphragm, ribs, intercostal muscles, larynx, trachea, bronchi, bronchioles, alveoli and associated capillaries"},{"text":"State the differences in composition between inspired and expired air, limited to oxygen, carbon dioxide and water vapour"},{"text":"Use limewater as a test for carbon dioxide to investigate the differences in composition between inspired and expired air"},{"text":"Investigate and describe the effects of physical activity on rate and depth of breathing"}],"supplement":[{"text":"Name and identify the internal and external intercostal muscles"},{"text":"State the functions of the cartilage in the trachea"},{"text":"Explain the role of the ribs, the internal and external intercostal muscles and the diaphragm in producing volume and pressure changes in the thorax leading to the ventilation of the lungs"},{"text":"Explain the differences in composition between inspired and expired air"},{"text":"Explain the link between physical activity and rate and depth of breathing in terms of the increased carbon dioxide concentration in the blood, detected by the brain, causing an increased rate of breathing"},{"text":"Explain the role of goblet cells, mucus and ciliated cells in protecting the gas exchange system from pathogens and particles"}]}]},{"n":"12","title":"Respiration","sections":[{"n":"12.1","title":"Respiration","core":[{"text":"State the uses of energy in the body of humans: muscle contraction, protein synthesis, cell division, active transport, growth, the passage of nerve impulses and the maintenance of a constant body temperature"},{"text":"State that respiration involves the action of enzymes in cells"}],"supplement":[]},{"n":"12.2","title":"Aerobic respiration","core":[{"text":"Define aerobic respiration as the chemical reactions in cells that use oxygen to break down nutrient molecules to release energy"},{"text":"State the word equation for aerobic respiration as glucose + oxygen → carbon dioxide + water"},{"text":"Investigate the uptake of oxygen by respiring organisms, such as arthropods and germinating seeds"}],"supplement":[{"text":"State the balanced chemical equation for aerobic respiration as C6H12O6 + 6O2 → 6CO2 + 6H2O"},{"text":"Investigate the effect of temperature on the rate of respiration of germinating seeds"}]},{"n":"12.3","title":"Anaerobic respiration","core":[{"text":"Define anaerobic respiration as the chemical reactions in cells that break down nutrient molecules to release energy without using oxygen"},{"text":"State the word equations for anaerobic respiration in muscles during vigorous exercise (glucose → lactic acid) and the microorganism yeast (glucose → alcohol + carbon dioxide)"},{"text":"State that anaerobic respiration releases much less energy per glucose molecule than aerobic respiration"}],"supplement":[{"text":"State the balanced chemical equation for anaerobic respirati on in the microorganism yeast as C6H12O6 → 2C2H5OH + 2CO2"},{"text":"State that lactic acid builds up in muscles and blood during vigorous exercise causing an oxygen debt"},{"text":"Outline how the oxygen debt is removed during recovery, limited to:\n– aerobic respiration of lactic acid in the liver\n– continuation, after exercise, of fast heart rate to transport lactic acid in blood from muscles to the liver\n– continuation, after exercise, of deeper breathing supplying oxygen for aerobic respiration of lactic acid"}]}]},{"n":"13","title":"Excretion in humans","sections":[{"n":"13","title":"Excretion in humans","core":[{"text":"State that urea is formed in the liver from excess amino acids"},{"text":"State that carbon dioxide is excreted through the lungs"},{"text":"State that the kidneys excrete urea and excess water and salts"},{"text":"Explain that the volume and concentration of urine produced is affected by water intake, temperature and exercise"},{"text":"Identify on drawings, diagrams and images, the ureters, bladder and urethra"}],"supplement":[{"text":"Describe the role of the liver in the assimilation of amino acids by converting them to proteins, including plasma proteins, e.g. fibrinogen"},{"text":"Define deamination as the removal of the nitrogen-containing part of amino acids to form urea"},{"text":"Explain the need for excretion, limited to toxicity of urea and carbon dioxide"},{"text":"Outline the structure of the kidney, limited to the cortex, medulla and ureter"},{"text":"Outline the structure and functioning of a kidney tubule, including:\n– the role of the glomerulus in the filtration from the blood of water, glucose, urea and salts\n– the role of the tubule in the reabsorption of all of the glucose, most of the water and some salts back into the blood, leading to the concentration of urea in the urine as well as loss of excess water and salts (details of these processes are not required)"},{"text":"Explain dialysis in terms of salt balance, the maintenance of glucose concentration and the removal of urea"},{"text":"Describe the use of dialysis in kidney machines"},{"text":"Discuss the advantages and disadvantages of kidney transplants, compared with dialysis"}]}]},{"n":"14","title":"Coordination and response","sections":[{"n":"14.1","title":"Nervous control in humans","core":[{"text":"Describe a nerve impulse as an electrical signal that passes along nerve cells called neurones"},{"text":"Describe the human nervous system in terms of:\n– the central nervous system consisting of brain and spinal cord\n– the peripheral nervous system\n– coordination and regulation of body functions"},{"text":"Identify motor (effector), relay (connector) and sensory neurones from diagrams"},{"text":"Describe a simple reflex arc in terms of receptor, sensory neurone, relay neurone, motor neurones and effector"},{"text":"Describe a reflex action as a means of automatically and rapidly integrating and coordinating stimuli with the responses of effectors (muscles and glands)"},{"text":"Define a synapse as a junction between two neurones"}],"supplement":[{"text":"Distinguish between voluntary and involuntary actions"},{"text":"Describe the structure of a synapse, including the presence of neurotransmitter containing vesicles, the synaptic cleft and neurotransmitter receptor molecules"},{"text":"Describe how an impulse triggers the release of a neurotransmitter from vesicles into the synaptic gap and how the neurotransmitter diffuses across to bind with receptor molecules, in the membrane of the neurone after the synaptic gap, causing the impulse to continue"},{"text":"State that in a reflex arc the synapses ensure that impulses travel in one direction only"},{"text":"State that many drugs, e.g. heroin act upon synapses"}]},{"n":"14.2","title":"Sense organs","core":[{"text":"Define sense organs as groups of receptor cells responding to specific stimuli: light, sound, touch, temperature and chemicals"},{"text":"Identify the structures of the eye, limited to cornea, iris, pupil, lens, retina, optic nerve and blind spot"},{"text":"Describe the function of each part of the eye, limited to:\n– cornea – refracts light\n– iris – controls how much light enters pupil\n– lens – focuses light onto retina\n– retina – contains light receptors, some sensitive to light of different colours\n– optic nerve – carries impulses to the brain"},{"text":"Explain the pupil reflex in terms of light intensity and pupil diameter only"}],"supplement":[{"text":"Explain the pupil reflex in terms of light intensity and antagonistic action of circular and radial muscles in the iris"},{"text":"Explain accommodation to view near and distant objects in terms of the contraction and relaxation of the ciliary muscles, tension in the suspensory ligaments, shape of the lens and refraction of light"},{"text":"State the distribution of rods and cones in the retina of a human"},{"text":"Outline the function of rods and cones, limited to greater sensitivity of rods for night vision and three different kinds of cones absorbing light of different colours for colour vision"},{"text":"Identify the position of the fovea"}]},{"n":"14.3","title":"Hormones in humans","core":[{"text":"Define a hormone as a chemical substance, produced by a gland and carried by the blood, which alters the activity of one or more specific target organs"},{"text":"Identify specific endocrine glands and their secretions, limited to adrenal glands and adrenaline, pancreas and insulin, testes and testosterone and ovaries and oestrogen"},{"text":"Describe adrenaline as the hormone secreted in ‘fight or flight’ situations and its effects, limited to increased breathing and pulse rate and widened pupils"},{"text":"Give examples of situations in which adrenaline secretion increases"},{"text":"State the functions of insulin, oestrogen and testosterone"}],"supplement":[{"text":"Discuss the role of the hormone adrenaline in the chemical control of metabolic activity, including increasing the blood glucose concentration and pulse rate"},{"text":"Compare nervous and hormonal control systems in terms of speed and longevity of action"}]},{"n":"14.4","title":"Homeostasis","core":[{"text":"Define homeostasis as the maintenance of a constant internal environment"},{"text":"Name and identify on a diagram of the skin: hairs, hair erector muscles, sweat glands, receptors, sensory neurones, blood vessels and fatty tissue"},{"text":"Describe the maintenance of a constant internal body temperature in humans in terms of insulation, sweating, shivering and the role of the brain (limited to blood temperature receptors and coordination)"}],"supplement":[{"text":"Explain that homeostasis is the control of internal conditions within set limits"},{"text":"Explain the concept of control by negative feedback"},{"text":"Describe the control of the glucose concentration of the blood by the liver and the roles of insulin and glucagon from the pancreas"},{"text":"Outline the symptoms and treatment of Type 1 diabetes (detail of β cells is not required)"},{"text":"Describe the maintenance of a constant internal body temperature in humans in terms of vasodilation and vasoconstriction of arterioles supplying skin surface capillaries"}]},{"n":"14.5","title":"Tropic responses","core":[{"text":"Define gravitropism as a response in which parts of a plant grow towards or away from gravity"},{"text":"Define phototropism as a response in which parts of a plant grow towards or away from the direction from which light is coming"},{"text":"Investigate gravitropism and phototropism in shoots and roots"}],"supplement":[{"text":"Explain phototropism and gravitropism of a shoot as examples of the chemical control of plant growth"},{"text":"Explain the role of auxin in controlling shoot growth, limited to:\n– auxin made in shoot tip (only)\n– auxin spreads through the plant from the shoot tip\n– auxin is unequally distributed in response to light and gravity\n– auxin stimulates cell elongation"},{"text":"Describe the use in weedkillers of the synthetic plant hormone 2,4-D"}]}]},{"n":"15","title":"Drugs","sections":[{"n":"15.1","title":"Drugs","core":[{"text":"Define a drug as any substance taken into the body that modifies or affects chemical reactions in the body"}],"supplement":[]},{"n":"15.2","title":"Medicinal drugs","core":[{"text":"Describe the use of antibiotics for the treatment of bacterial infection"},{"text":"State that some bacteria are resistant to antibiotics which reduces the effectiveness of antibiotics"},{"text":"State that antibiotics kill bacteria but do not affect viruses"}],"supplement":[{"text":"Explain how development of resistant bacteria such as MRSA can be minimised, limited to using antibiotics only when essential and ensuring treatment is completed"},{"text":"Explain why antibiotics kill bacteria, but do not affect viruses"}]},{"n":"15.3","title":"Misused drugs","core":[{"text":"Describe the effects of excessive alcohol consumption and abuse of heroin, limited to:\n– powerful depressant drugs\n– effect on reaction times and self-control\n– addiction and withdrawal symptoms\n– negative social implications, e.g. crime"},{"text":"State that injecting heroin can cause infections such as HIV"},{"text":"State that excessive alcohol consumption can cause liver damage"},{"text":"State that tobacco smoking can cause chronic obstructive pulmonary disease (COPD), lung cancer and coronary heart disease"},{"text":"Describe the effects on the gas exchange system of tobacco smoke and its major toxic components, limited to carbon monoxide, nicotine and tar"},{"text":"State that the liver is the site of break down of alcohol and other toxins"}],"supplement":[{"text":"Explain how heroin affects the nervous system, limited to its effect on the function of synapses"},{"text":"Discuss the evidence for the link between smoking and lung cancer"},{"text":"Discuss the use of hormones to improve sporting performance, limited to testosterone and anabolic steroids"}]}]},{"n":"16","title":"Reproduction","sections":[{"n":"16.1","title":"Asexual reproduction","core":[{"text":"Define asexual reproduction as a process resulting in the production of genetically identical offspring from one parent"},{"text":"Identify examples of asexual reproduction from information provided"}],"supplement":[{"text":"Discuss the advantages and disadvantages of asexual reproduction:\n– to a population of a species in the wild\n– to crop production"}]},{"n":"16.2","title":"Sexual reproduction","core":[{"text":"Define sexual reproduction as a process involving the fusion of the nuclei of two gametes (sex cells) to form a zygote and the production of offspring that are genetically different from each other"},{"text":"Define fertilisation as the fusion of gamete nuclei"}],"supplement":[{"text":"State that the nuclei of gametes are haploid and that the nucleus of a zygote is diploid"},{"text":"Discuss the advantages and disadvantages of sexual reproduction:\n– to a population of a species in the wild\n– to crop production"}]},{"n":"16.3","title":"Sexual reproduction in plants","core":[{"text":"Identify and draw, using a hand lens if necessary, the sepals, petals, stamens, filaments and anthers, carpels, style, stigma, ovary and ovules, of an insect-pollinated flower"},{"text":"State the functions of the sepals, petals, anthers, stigmas and ovaries"},{"text":"Use a hand lens to identify and describe the anthers and stigmas of a wind-pollinated flower"},{"text":"Distinguish between the pollen grains of insect-pollinated and wind-pollinated flowers"},{"text":"Define pollination as the transfer of pollen grains from the anther to the stigma"},{"text":"State that fertilisation occurs when a pollen nucleus fuses with a nucleus in an ovule"},{"text":"Describe the structural adaptations of insect-pollinated and wind-pollinated flowers"},{"text":"Investigate and state the environmental conditions that affect germination of seeds, limited to the requirement for water, oxygen and a suitable temperature"}],"supplement":[{"text":"Define self-pollination as the transfer of pollen grains from the anther of a flower to the stigma of the same flower or different flower on the same plant"},{"text":"Define cross-pollination as transfer of pollen grains from the anther of a flower to the stigma of a flower on a different plant of the same species"},{"text":"Discuss the implications to a species of self-pollination and cross-pollination in terms of variation, capacity to respond to changes in the environment and reliance on pollinators"},{"text":"Describe the growth of the pollen tube and its entry into the ovule followed by fertilisation (details of production of endosperm and development are not required)"}]},{"n":"16.4","title":"Sexual reproduction in humans","core":[{"text":"Identify and name on diagrams of the male reproductive system: the testes, scrotum, sperm ducts, prostate gland, urethra and penis, and state the functions of these parts"},{"text":"Identify and name on diagrams of the female reproductive system: the ovaries, oviducts, uterus, cervix and vagina, and state the functions of these parts"},{"text":"Describe fertilisation as the fusion of the nuclei from a male gamete (sperm) and a female gamete (egg cell/ovum)"},{"text":"State the adaptive features of sperm, limited to flagellum and the presence of enzymes"},{"text":"State the adaptive features of egg cells, limited to energy stores and a jelly coating that changes after fertilisation"},{"text":"State that in early development, the zygote forms an embryo which is a ball of cells that implants into the wall of the uterus"},{"text":"State the functions of the umbilical cord, placenta, amniotic sac and amniotic fluid"},{"text":"Outline the growth and development of the fetus in terms of increasing complexity in the early stages and increasing size towards the end of pregnancy"},{"text":"Describe the ante-natal care of pregnant women, limited to special dietary needs and the harm from smoking and alcohol consumption"},{"text":"Outline the processes involved in labour and birth, limited to:\n– breaking of the amniotic sac\n– contraction of the muscles in the uterus wall\n– dilation of the cervix\n– passage through the vagina\n– tying and cutting the umbilical cord\n– delivery of the afterbirth"}],"supplement":[{"text":"Compare male and female gametes in terms of size, structure, motility and numbers"},{"text":"Explain the adaptive features of sperm, limited to flagellum, mitochondria and enzymes in the acrosome"},{"text":"Explain the adaptive features of egg cells, limited to energy stores and the jelly coat that changes at fertilisation"},{"text":"Describe the function of the placenta and umbilical cord in relation to exchange of dissolved nutrients, gases and excretory products and providing a barrier to toxins and pathogens (structural details are not required)"},{"text":"State that some toxins, e.g. nicotine, and pathogens, e.g. rubella virus, can pass across the placenta and affect the fetus"},{"text":"Discuss the advantages and disadvantages of breast-feeding compared with bottle-feeding using formula milk"}]},{"n":"16.5","title":"Sex hormones in humans","core":[{"text":"Describe the roles of testosterone and oestrogen in the development and regulation of secondary sexual characteristics during puberty"},{"text":"Describe the menstrual cycle in terms of changes in the ovaries and in the lining of the uterus"}],"supplement":[{"text":"Describe the sites of production of oestrogen and progesterone in the menstrual cycle and in pregnancy"},{"text":"Explain the role of hormones in controlling the menstrual cycle and pregnancy, limited to FSH, LH, progesterone and oestrogen"}]},{"n":"16.6","title":"Methods of birth control in humans","core":[{"text":"Outline the following methods of birth control:\n– natural, limited to abstinence, monitoring body temperature and cervical mucus\n– chemical, limited to IUD, IUS, contraceptive pill, implant and injection\n– barrier, limited to condom, femidom, diaphragm\n– surgical, limited to vasectomy and female sterilisation"}],"supplement":[{"text":"Outline the use of hormones in contraception and fertility treatments"},{"text":"Outline artificial insemination (AI)"},{"text":"Outline in vitro fertilisation (IVF)"},{"text":"Discuss the social implications of contraception and fertility treatments"}]},{"n":"16.7","title":"Sexually transmitted infections (STIs)","core":[{"text":"Define sexually transmitted infection as an infection that is transmitted via body fluids through sexual contact"},{"text":"State that human immunodeficiency virus (HIV) is an example of an STI"},{"text":"Explain how the spread of STIs is controlled"},{"text":"Describe the methods of transmission of HIV"},{"text":"State that HIV infection may lead to AIDS"}],"supplement":[{"text":"Outline how HIV affects the immune system, limited to decreased lymphocyte numbers and reduced ability to produce antibodies"}]}]},{"n":"17","title":"Inheritance","sections":[{"n":"17.1","title":"Inheritance","core":[{"text":"Define inheritance as the transmission of genetic information from generation to generation"}],"supplement":[]},{"n":"17.2","title":"Chromosomes, genes and proteins","core":[{"text":"Define chromosome as a thread-like structure of DNA, carrying genetic information in the form of genes"},{"text":"Define gene as a length of DNA that codes for a protein"},{"text":"Define allele as a version of a gene"},{"text":"Describe the inheritance of sex in humans with reference to XX and XY chromosomes"}],"supplement":[{"text":"Explain that the sequence of bases in a gene is the genetic code for putting together amino acids in the correct order to make a specific protein (knowledge of the details of nucleotide structure is not required)"},{"text":"Explain that DNA controls cell function by controlling the production of proteins (some of which are enzymes), antibodies and receptors for neurotransmitters"},{"text":"Explain how a protein is made, limited to:\n– the gene coding for the protein remains in the nucleus\n– mRNA molecules carry a copy of the gene to the cytoplasm\n– the mRNA passes through ribosomes\n– the ribosome assembles amino acids into protein molecules\n– the specific order of amino acids is determined by the sequence of bases in the mRNA (knowledge of the details of transcription or translation is not required)"},{"text":"Explain that all body cells in an organism contain the same genes, but many genes in a particular cell are not expressed because the cell only makes the specific proteins it needs cont."},{"text":"Define a haploid nucleus as a nucleus containing a single set of unpaired chromosomes, e.g. in gametes"},{"text":"Define a diploid nucleus as a nucleus containing two sets of chromosomes, e.g. in body cells"},{"text":"State that in a diploid cell, there is a pair of each type of chromosome and in a human diploid cell there are 23 pairs"}]},{"n":"17.3","title":"Mitosis","core":[{"text":"Define mitosis as nuclear division giving rise to genetically identical cells (details of stages are not required)"},{"text":"State the role of mitosis in growth, repair of damaged tissues, replacement of cells and asexual reproduction"}],"supplement":[{"text":"State that the exact duplication of chromosomes occurs before mitosis"},{"text":"State that during mitosis, the copies of chromosomes separate, maintaining the chromosome number (details of stages of mitosis are not required)"},{"text":"Describe stem cells as unspecialised cells that divide by mitosis to produce daughter cells that can become specialised for specific functions"}]},{"n":"17.4","title":"Meiosis","core":[{"text":"Define meiosis as nuclear division giving rise to cells that are genetically different (details of stages are not required)"},{"text":"State that meiosis is involved in the production of gametes"}],"supplement":[{"text":"Define meiosis as reduction division in which the chromosome number is halved from diploid to haploid resulting in genetically different cells (details of stages are not required)"},{"text":"Explain how meiosis produces variation by forming new combinations of maternal and paternal chromosomes (specific details are not required)"}]},{"n":"17.5","title":"Monohybrid inheritance","core":[{"text":"Define genotype as the genetic make-up of an organism in terms of the alleles present"},{"text":"Define phenotype as the observable features of an organism"},{"text":"Define homozygous as having two identical alleles of a particular gene"},{"text":"State that two identical homozygous individuals that breed together will be pure-breeding"},{"text":"Define heterozygous as having two different alleles of a particular gene"},{"text":"State that a heterozygous individual will not be pure-breeding"},{"text":"Define dominant as an allele that is expressed if it is present"},{"text":"Define recessive as an allele that is only expressed when there is no dominant allele of the gene present"},{"text":"Interpret pedigree diagrams for the inheritance of a given characteristic"},{"text":"Use genetic diagrams to predict the results of monohybrid crosses and calculate phenotypic ratios, limited to 1:1 and 3:1 ratios"},{"text":"Use Punnett squares in crosses which result in more than one genotype to work out and show the possible different genotypes"}],"supplement":[{"text":"Explain how to use a test cross to identify an unknown genotype"},{"text":"Explain co-dominance by reference to the inheritance of ABO blood groups – phenotypes being A, B, AB and O blood groups and alleles being IA, IB and Io"},{"text":"Define a sex-linked characteristic as a characteristic in which the gene responsible is located on a sex chromosome and that this makes it more common in one sex than in the other"},{"text":"Describe colour blindness as an example of sex linkage"},{"text":"Use genetic diagrams to predict the results of monohybrid crosses involving co-dominance or sex linkage and calculate phenotypic ratios"}]}]},{"n":"18","title":"Variation and selection","sections":[{"n":"18.1","title":"Variation","core":[{"text":"Define variation as differences between individuals of the same species"},{"text":"Distinguish between phenotypic variation and genetic variation"},{"text":"State that continuous variation results in a range of phenotypes between two extremes, e.g. height in humans"},{"text":"State that discontinuous variation results in a limited number of phenotypes with no intermediates, e.g. tongue rolling"},{"text":"Record and present the results of investigations into continuous and discontinuous variation"},{"text":"Define mutation as genetic change"},{"text":"State that mutation is the way in which new alleles are formed"},{"text":"State that ionising radiation and some chemicals increase the rate of mutation"}],"supplement":[{"text":"State that phenotypic variation is caused by both genetic and environmental factors"},{"text":"State that discontinuous variation is mostly caused by genes alone, e.g. A, B, AB and O blood groups in humans"},{"text":"Define gene mutation as a change in the base sequence of DNA"},{"text":"Describe the symptoms of sickle-cell anaemia"},{"text":"Explain how a change in the base sequence of the gene for haemoglobin results in abnormal haemoglobin and sickle-shaped red blood cells"},{"text":"Use genetic diagrams to show how sickle-cell anaemia is inherited"},{"text":"State that people who are heterozygous (HbS HbA) for the sickle-cell allele have a resistance to malaria"},{"text":"Explain the distribution of the sickle-cell allele in human populations with reference to the distribution of malaria (Teaching of human inherited conditions should be done with sensitivity at all times.)"}]},{"n":"18.2","title":"Adaptive features","core":[{"text":"Define adaptive feature as an inherited feature that helps an organism to survive and reproduce in its environment"},{"text":"Interpret images or other information about a species to describe its adaptive features"}],"supplement":[{"text":"Define adaptive feature as the inherited functional features of an organism that increase its fitness"},{"text":"Define fitness as the probability of an organism surviving and reproducing in the environment in which it is found"},{"text":"Explain the adaptive features of hydrophytes and xerophytes to their environments"}]},{"n":"18.3","title":"Selection","core":[{"text":"Describe natural selection with reference to:\n– variation within populations\n– production of many offspring\n– competition for resources\n– struggle for survival\n– reproduction by individuals that are better adapted to the environment than others\n– passing on of their alleles to the next generation"},{"text":"Describe selective breeding with reference to:\n– selection by humans of individuals with desirable features\n– crossing these individuals to produce the next generation\n– selection of offspring showing the desirable features"}],"supplement":[{"text":"Describe evolution as the change in adaptive features of a population over time as the result of natural selection"},{"text":"Define the process of adaptation as the process, resulting from natural selection, by which populations become more suited to their environment over many generations"},{"text":"Describe the development of strains of antibiotic resistant bacteria as an example of evolution by natural selection"},{"text":"State the differences between natural and artificial selection"},{"text":"Outline how selective breeding by artificial selection is carried out over many generations to improve crop plants and domesticated animals"}]}]},{"n":"19","title":"Organisms and their environment","sections":[{"n":"19.1","title":"Energy flow","core":[{"text":"State that the Sun is the principal source of energy input to biological systems"}],"supplement":[{"text":"Describe the flow of energy through living organisms including light energy from the sun and chemical energy in organisms and its eventual transfer to the environment"}]},{"n":"19.2","title":"Food chains and food webs","core":[{"text":"Define a food chain as showing the transfer of energy from one organism to the next, beginning with a producer"},{"text":"State that energy is transferred between organisms in a food chain by ingestion"},{"text":"Construct simple food chains"},{"text":"Define a food web as a network of interconnected food chains"},{"text":"Define producer as an organism that makes its own organic nutrients, usually using energy from sunlight, through photosynthesis"},{"text":"Define consumer as an organism that gets its energy by feeding on other organisms"},{"text":"State that consumers may be classed as primary, secondary and tertiary according to their position in a food chain"},{"text":"Define herbivore as an animal that gets its energy by eating plants"},{"text":"Define carnivore as an animal that gets its energy by eating other animals"},{"text":"Define decomposer as an organism that gets its energy from dead or waste organic material"},{"text":"Interpret food chains and food webs in terms of identifying producers and consumers"},{"text":"Use food chains and food webs to describe the impacts humans have through over-harvesting of food species and through introducing foreign species to a habitat"},{"text":"Draw, describe and interpret pyramids of numbers"}],"supplement":[{"text":"Describe how energy is transferred between trophic levels"},{"text":"Define trophic level as the position of an organism in a food chain, food web, pyramid of numbers or pyramid of biomass"},{"text":"Explain why the transfer of energy from one trophic level to another is inefficient"},{"text":"Explain why food chains usually have fewer than five trophic levels"},{"text":"Explain why there is a greater efficiency in supplying plants as human food, and that there is a relative inefficiency in feeding crop plants to livestock that will be used as food"},{"text":"Identify producers, primary consumers, secondary consumers, tertiary consumers and quaternary consumers as the trophic levels in food webs, food chains, pyramids of numbers and pyramids of biomass cont."},{"text":"Draw, describe and interpret pyramids of biomass"},{"text":"Discuss the advantages of using a pyramid of biomass rather than a pyramid of numbers to represent a food chain"}]},{"n":"19.3","title":"Nutrient cycles","core":[{"text":"Describe the carbon cycle, limited to photosynthesis, respiration, feeding, decomposition, fossilisation and combustion"},{"text":"Discuss the effects of the combustion of fossil fuels and the cutting down of forests on the carbon dioxide concentrations in the atmosphere"},{"text":"Describe the water cycle, limited to evaporation, transpiration, condensation and precipitation"}],"supplement":[{"text":"Describe the nitrogen cycle in terms of:\n– decomposition of plant and animal protein to ammonium ions\n– nitrification\n– nitrogen fixation by lightning and bacteria\n– absorption of nitrate ions by plants\n– production of amino acids and proteins\n– feeding and digestion of proteins\n– deamination\n– denitrification"},{"text":"State the roles of microorganisms in the nitrogen cycle, limited to decomposition, nitrification, nitrogen fixation and denitrification (generic names of individual bacteria, e.g. Rhizobium, are not required)"}]},{"n":"19.4","title":"Population size","core":[{"text":"Define population as a group of organisms of one species, living in the same area, at the same time"},{"text":"Identify and state the factors affecting the rate of population growth for a population of an organism, limited to food supply, predation and disease"},{"text":"Discuss the increase in human population size over the past 250 years and its social and environmental implications"},{"text":"Interpret graphs and diagrams of human population growth"}],"supplement":[{"text":"Define community as all of the populations of different species in an ecosystem"},{"text":"Define ecosystem as a unit containing the community of organisms and their environment, interacting together, e.g. a decomposing log, or a lake"},{"text":"Identify the lag, exponential (log), stationary and death phases in the sigmoid population growth curve for a population growing in an environment with limited resources"},{"text":"Explain the factors that lead to each phase in the sigmoid curve of population growth, making reference, where appropriate, to the role of limiting factors"}]}]},{"n":"20","title":"Biotechnology and genetic engineering","sections":[{"n":"20.1","title":"Biotechnology and genetic engineering","core":[{"text":"State that bacteria are useful in biotechnology and genetic engineering due to their rapid reproduction rate and their ability to make complex molecules"}],"supplement":[{"text":"Discuss why bacteria are useful in biotechnology and genetic engineering, limited to:\n– lack of ethical concerns over their manipulation and growth\n– genetic code shared with all other organisms\n– presence of plasmids"}]},{"n":"20.2","title":"Biotechnology","core":[{"text":"Describe the role of anaerobic respiration in yeast during production of ethanol for biofuels"},{"text":"Describe the role of anaerobic respiration in yeast during bread-making"},{"text":"Investigate and describe the use of pectinase in fruit juice production"},{"text":"Investigate and describe the use of biological washing powders that contain enzymes"}],"supplement":[{"text":"Investigate and explain the use of lactase to produce lactose-free milk"},{"text":"Describe the role of the fungus Penicillium in the production of the antibiotic penicillin"},{"text":"Explain how fermenters are used in the production of penicillin"}]},{"n":"20.3","title":"Genetic engineering","core":[{"text":"Define genetic engineering as changing the genetic material of an organism by removing, changing or inserting individual genes"},{"text":"State examples of genetic engineering:\n– the insertion of human genes into bacteria to produce human insulin\n– the insertion of genes into crop plants to confer resistance to herbicides\n– the insertion of genes into crop plants to confer resistance to insect pests\n– the insertion of genes into crop plants to provide additional vitamins"}],"supplement":[{"text":"Outline genetic engineering using bacterial production of a human protein as an example, limited to:\n– isolation of the DNA making up a human gene using restriction enzymes, forming sticky ends\n– cutting of bacterial plasmid DNA with the same restriction enzymes, forming complementary sticky ends\n– insertion of human DNA into bacterial plasmid DNA using DNA ligase to form a recombinant plasmid\n– insertion of plasmid into bacteria (specific detail is not required)\n– replication of bacteria containing recombinant plasmids which make human protein as they express the gene"},{"text":"Discuss the advantages and disadvantages of genetically modifying crops, such as soya, maize and rice"}]}]},{"n":"21","title":"Human influences on ecosystems","sections":[{"n":"21.1","title":"Food supply","core":[{"text":"State how modern technology has resulted in increased food production in terms of:\n– agricultural machinery to use larger areas of land and improve efficiency\n– chemical fertilisers to improve yields\n– insecticides to improve quality and yield\n– herbicides to reduce competition with weeds\n– selective breeding to improve production by crop plants and livestock, e.g. cattle, fish and poultry"},{"text":"Describe the negative impacts to an ecosystem of large-scale monocultures of crop plants"},{"text":"Describe the negative impacts to an ecosystem of intensive livestock production"}],"supplement":[{"text":"Discuss the social, environmental and economic implications of providing sufficient food for an increasing human global population"},{"text":"Discuss the problems which contribute to famine including unequal distribution of food, drought and flooding, increasing population and poverty"}]},{"n":"21.2","title":"Habitat destruction","core":[{"text":"Describe the reasons for habitat destruction, limited to:\n– increased area for food crop growth, livestock production and housing\n– extraction of natural resources\n– marine pollution"},{"text":"State that through altering food webs and food chains, humans can have a negative impact on habitats"},{"text":"List the undesirable effects of deforestation as an example of habitat destruction, to include extinction, loss of soil, flooding and increase of carbon dioxide in the atmosphere"}],"supplement":[{"text":"Explain the undesirable effects of deforestation on the environment"}]},{"n":"21.3","title":"Pollution","core":[{"text":"State the sources and effects of pollution of land and water, e.g. rivers, lakes and the sea, by insecticides, herbicides and by nuclear fall-out"},{"text":"State the sources and effects of pollution of water (rivers, lakes and the sea) by chemical waste, discarded rubbish, untreated sewage and fertilisers"},{"text":"State the sources and effects of pollution of the air by methane and carbon dioxide, limited to the enhanced greenhouse effect and climate change"}],"supplement":[{"text":"Explain the process of eutrophication of water in terms of:\n– increased availability of nitrate and other ions\n– increased growth of producers\n– increased decomposition after death of producers\n– increased aerobic respiration by decomposers\n– reduction in dissolved oxygen\n– death of organisms requiring dissolved oxygen in water"},{"text":"Discuss the effects of non-biodegradable plastics in the environment, in both aquatic and terrestrial ecosystems"},{"text":"Discuss the causes and effects on the environment of acid rain"},{"text":"State the measures that are taken to reduce sulfur dioxide pollution and reduce the impact of acid rain"},{"text":"Explain how increases in carbon dioxide and methane concentrations in the atmosphere cause an enhanced greenhouse effect that leads to climate change"},{"text":"Describe the negative impacts of female contraceptive hormones in water courses, limited to reduced sperm count in men and feminisation of aquatic organisms"}]},{"n":"21.4","title":"Conservation","core":[{"text":"Define a sustainable resource as one which is produced as rapidly as it is removed from the environment so that it does not run out"},{"text":"Explain the need to conserve non-renewable resources, limited to fossil fuels"},{"text":"State that some resources can be maintained, limited to forests and fish stocks"},{"text":"State that products can be reused or recycled, limited to paper, glass, plastic and metal"},{"text":"Outline how sewage is treated to make the water that it contains safe to return to the environment or for human use"},{"text":"Explain why organisms become endangered or extinct, limited to climate change, habitat destruction, hunting, pollution and introduced species"},{"text":"Describe how endangered species can be conserved, limited to monitoring and protecting species and habitats, education, captive breeding programmes and seed banks"}],"supplement":[{"text":"Define the term sustainable development as development providing for the needs of an increasing human population without harming the environment"},{"text":"Explain how forests and fish stocks can be sustained using education, legal quotas and re-stocking"},{"text":"Explain that sustainable development requires:\n– management of conflicting demands\n– planning and co-operation at local, national and international levels"},{"text":"Explain the risks to a species if the population size drops, reducing variation (knowledge of genetic drift is not required)"},{"text":"Explain reasons for conservation programmes, to include:\n– reducing extinction\n– protecting vulnerable environments\n– maintaining ecosystem functions, limited to nutrient cycling and resource provision, e.g. food, drugs, fuel and genes"}]}]}]},{"id":"2015","label":"2015","until":"2015","numbered":false,"source":{"title":"Cambridge IGCSE Biology 0610, for examination in 2015","url":"http://www.cie.org.uk/Images/128334-2015-syllabus.pdf","via":"web.archive.org, 16 March 2015"},"topics":[{"n":"I.1","title":"Characteristics of living organisms","sections":[{"n":"1","title":"Characteristics of living organisms","core":[{"text":"List and describe the characteristics of living organisms"},{"text":"Define the terms:\n• nutrition as taking in of nutrients which are organic substances and mineral ions, containing raw materials or energy for growth and tissue repair, absorbing and assimilating them\n• excretion as removal from organisms of toxic materials, the waste products of metabolism (chemical reactions in cells including respiration) and substances in excess of requirements\n• respiration as the chemical reactions that break down nutrient molecules in living cells to release energy\n• sensitivity as the ability to detect or sense changes in the environment (stimuli) and to make responses\n• reproduction as the processes that make more of the same kind of organism\n• growth as a permanent increase in size and dry mass by an increase in cell number or cell size or both\n• movement as an action by an organism or part of an organism causing a change of position or place"}],"supplement":[]}],"group":"Section I: Characteristics and classification of living organisms"},{"n":"I.2","title":"Classification and diversity of living organisms","sections":[{"n":"2.1","title":"Concept and use of a classificatory system","core":[{"text":"Define and describe the binomial system of naming species as a system in which the scientific name of an organism is made up of two parts showing the genus and species"},{"text":"List the main features of the following vertebrates: bony fish, amphibians, reptiles, birds and mammals"}],"supplement":[{"text":"• Know that there are other classification systems e.g. cladistics (based on RNA/ DNA sequencing data)\n• List the main features used in the classification of the following groups: viruses, bacteria and fungi, and their adaptation to the environment, as appropriate"}]},{"n":"2.2","title":"Adaptations of organisms to their environment","core":[{"text":"(to be illustrated by examples wherever possible)"},{"text":"List the main features used in the classification of the following groups: flowering plants (monocotyledons and eudicotyledons (dicotyledons)), arthropods (insects, crustaceans, arachnids and myriapods), annelids, nematodes and molluscs"}],"supplement":[]}],"group":"Section I: Characteristics and classification of living organisms"},{"n":"I.3","title":"Simple keys","sections":[{"n":"3","title":"Simple keys","core":[{"text":"Use simple dichotomous keys based on easily identifiable features"}],"supplement":[]}],"group":"Section I: Characteristics and classification of living organisms"},{"n":"II.1","title":"Cell structure and organisation","sections":[{"n":"1","title":"Cell structure and organisation","core":[{"text":"State that living organisms are made of cells"},{"text":"Identify and describe the structure of a plant cell (palisade cell) and an animal cell (liver cell), as seen under a light microscope"},{"text":"Describe the differences in structure between typical animal and plant cells"}],"supplement":[{"text":"Relate the structures seen under the light microscope in the plant cell and in the animal cell to their functions"}]}],"group":"Section II: Organisation and maintenance of the organism"},{"n":"II.2","title":"Levels of organisation","sections":[{"n":"2","title":"Levels of organisation","core":[{"text":"Relate the structure of the following to their functions:\n• ciliated cells – in respiratory tract\n• root hair cells – absorption\n• xylem vessels – conduction and support\n• muscle cells – contraction\n• red blood cells – transport"},{"text":"Define:\n• tissue as a group of cells with similar structures, working together to perform a shared function\n• organ as a structure made up of a group of tissues, working together to perform specific functions\n• organ system as a group of organs with related functions, working together to perform body functions using examples covered in Sections II and III"}],"supplement":[]}],"group":"Section II: Organisation and maintenance of the organism"},{"n":"II.3","title":"Size of specimens","sections":[{"n":"3","title":"Size of specimens","core":[{"text":"Calculate magnification and size of biological specimens using millimetres as units"}],"supplement":[]}],"group":"Section II: Organisation and maintenance of the organism"},{"n":"II.4","title":"Movement in and out of cells","sections":[{"n":"4.1","title":"Diffusion","core":[{"text":"Define diffusion as the net movement of molecules from a region of their higher concentration to a region of their lower concentration down a concentration gradient, as a result of their random movement"},{"text":"Describe the importance of diffusion of gases and solutes and of water as a solvent"}],"supplement":[]},{"n":"4.2","title":"Active Transport","core":[],"supplement":[{"text":"Define active transport as movement of ions in or out of a cell through the cell membrane, from a region of their lower concentration to a region of their higher concentration against a concentration gradient, using energy released during respiration"},{"text":"Discuss the importance of active transport as an energy-consuming process by which substances are transported against a concentration gradient, e.g. ion uptake by root hairs and uptake of glucose by epithelial cells of villi"}]},{"n":"4.3","title":"Osmosis","core":[{"text":"Define osmosis as the diffusion of water molecules from a region of their higher concentration (dilute solution) to a region of their lower concentration (concentrated solution), through a partially permeable membrane"},{"text":"Describe the importance of osmosis in the uptake of water by plants, and its effects on plant and animal tissues"}],"supplement":[{"text":"Describe and explain the importance of a water potential gradient in the uptake of water by plants"}]}],"group":"Section II: Organisation and maintenance of the organism"},{"n":"II.5","title":"Enzymes","sections":[{"n":"5","title":"Enzymes","core":[{"text":"Define the term catalyst as a substance that speeds up a chemical reaction and is not changed by the reaction"},{"text":"Define enzymes as proteins that function as biological catalysts"},{"text":"Investigate and describe the effect of changes in temperature and pH on enzyme activity"}],"supplement":[{"text":"Explain enzyme action in terms of the ‘lock and key’ model"},{"text":"Explain the effect of changes in temperature and pH on enzyme activity"},{"text":"Describe the role of enzymes in the germination of seeds, and their uses in biological washing products and in the food industry (including pectinase and fruit juice)"},{"text":"Outline the use of microorganisms and fermenters to manufacture the antibiotic penicillin and enzymes for use in biological washing powders"},{"text":"Describe the role of the fungus Penicillium in the production of antibiotic penicillin"}]}],"group":"Section II: Organisation and maintenance of the organism"},{"n":"II.6","title":"Nutrition","sections":[{"n":"6","title":"Nutrition","core":[{"text":"Define nutrition as taking in of nutrients which are organic substances and mineral ions, containing raw materials or energy for growth and tissue repair, absorbing and assimilating them"}],"supplement":[]},{"n":"6.1","title":"Nutrients","core":[{"text":"List the chemical elements that make up:\n• carbohydrates\n• fats\n• proteins"},{"text":"Describe the synthesis of large molecules from smaller basic units, i.e.\n• simple sugars to starch and glycogen\n• amino acids to proteins\n• fatty acids and glycerol to fats and oils"},{"text":"Describe tests for:\n• starch (iodine solution)\n• reducing sugars (Benedict’s solution)\n• protein (Biuret test)\n• fats (ethanol)"},{"text":"List the principal sources of, and describe the importance of:\n• carbohydrates\n• fats\n• proteins\n• vitamins (C and D only)\n• mineral ions (calcium and iron only)\n• fibre (roughage)\n• water"},{"text":"Describe the deficiency symptoms for:\n• vitamins (C and D only)\n• mineral ions (calcium and iron only)"}],"supplement":[{"text":"Describe the use of microorganisms in the food industry, with reference to yoghurt and single cell protein"},{"text":"Describe the uses, benefits and health hazards associated with food additives, including colourings"}]},{"n":"6.2","title":"Plant nutrition","core":[],"supplement":[]},{"n":"6.2.1","title":"Photosynthesis","core":[{"text":"Define photosynthesis as the fundamental process by which plants manufacture carbohydrates from raw materials using energy from light"},{"text":"State the word equation for the production of simple sugars and oxygen"},{"text":"Investigate the necessity for chlorophyll, light and carbon dioxide for photosynthesis, using appropriate controls"},{"text":"Describe the intake of carbon dioxide and water by plants"},{"text":"Explain that chlorophyll traps light energy and converts it into chemical energy for the formation of carbohydrates and their subsequent storage"}],"supplement":[{"text":"State the balanced equation for photosynthesis in symbols light 6CO + 6H O → C H O + 6O 2 2 chlorophyll 6 12 6 2"},{"text":"Investigate and state the effect of varying light intensity, carbon dioxide concentration and temperature on the rate of photosynthesis (e.g. in submerged aquatic plants)"},{"text":"Define the term limiting factor as something present in the environment in such short supply that it restricts life processes"},{"text":"Explain the concept of limiting factors in photosynthesis"},{"text":"Explain the use of carbon dioxide enrichment, optimum light and optimum temperatures in glasshouse systems"}]},{"n":"6.2.2","title":"Leaf structure","core":[{"text":"Identify and label the cuticle, cellular and tissue structure of a dicotyledonous leaf, as seen in cross-section under the light microscope, and describe the significance of these features in terms of functions, to include:\n• distribution of chloroplasts – photosynthesis\n• stomata and mesophyll cells – gas exchange\n• vascular bundles (xylem and phloem) – transport and support"}],"supplement":[]},{"n":"6.2.3","title":"Mineral requirements","core":[{"text":"Describe the importance of:\n• nitrate ions for protein synthesis\n• magnesium ions for chlorophyll synthesis"},{"text":"Describe the uses, and the dangers of overuse, of nitrogen fertilisers"}],"supplement":[{"text":"Explain the effects of nitrate ion and magnesium ion deficiency on plant growth"}]},{"n":"6.3","title":"Animal nutrition","core":[],"supplement":[]},{"n":"6.3.1","title":"Diet","core":[{"text":"State what is meant by the term balanced diet and describe a balanced diet related to age, sex and activity of an individual"},{"text":"Describe the effects of malnutrition in relation to starvation, coronary heart disease, constipation and obesity"}],"supplement":[]},{"n":"6.3.2","title":"Food supply","core":[{"text":"Discuss ways in which the use of modern technology has resulted in increased food production (to include modern agricultural machinery, chemical fertilisers, pesticides and herbicides, artificial selection)"}],"supplement":[{"text":"Discuss the problems of world food supplies"},{"text":"Discuss the problems which contribute to famine (unequal distribution of food, drought and flooding and increasing population)"}]},{"n":"6.3.3","title":"Human alimentary canal","core":[{"text":"Define ingestion as taking substances (e.g. food, drink) into the body through the mouth"},{"text":"Define egestion as passing out of food that has not been digested, as faeces, through the anus"},{"text":"Identify the main regions of the alimentary canal and associated organs including mouth, salivary glands, oesophagus, stomach, small intestine: duodenum and ileum, pancreas, liver, gall bladder, large intestine: colon and rectum, anus"},{"text":"Describe the functions of the regions of the alimentary canal listed above, in relation to ingestion, digestion, absorption, assimilation and egestion of food (cross reference 6.3.4, 6.3.5, 6.3.6 and 6.3.7)"}],"supplement":[]},{"n":"6.3.4","title":"Mechanical and physical digestion","core":[{"text":"Define digestion as the break-down of large, insoluble food molecules into small, water-soluble molecules using mechanical and chemical processes"},{"text":"Identify the types of human teeth and describe their structure and functions"},{"text":"State the causes of dental decay and describe the proper care of teeth"},{"text":"Describe the process of chewing"},{"text":"Describe the role of longitudinal and circular muscles in peristalsis"},{"text":"Outline the role of bile in emulsifying fats, to increase the surface area for the action of enzymes"}],"supplement":[{"text":"Describe how fluoride reduces tooth decay and explain arguments for and against the addition of fluoride to public water supplies"}]},{"n":"6.3.5","title":"Chemical digestion","core":[{"text":"State the significance of chemical digestion in the alimentary canal in producing small, soluble molecules that can be absorbed"},{"text":"State where, in the alimentary canal, amylase, protease and lipase enzymes are secreted"},{"text":"State the functions of a typical amylase, a protease and a lipase, listing the substrate and end-products"}],"supplement":[]},{"n":"6.3.6","title":"Absorption","core":[{"text":"Define absorption as movement of digested food molecules through the wall of the intestine into the blood or lymph"},{"text":"Identify the small intestine as the region for the absorption of digested food"},{"text":"Describe the significance of villi in increasing the internal surface area of the small intestine"}],"supplement":[{"text":"Describe the structure of a villus, including the role of capillaries and lacteals"},{"text":"State the role of the hepatic portal vein in the transport of absorbed food to the liver"},{"text":"Identify the role of the small intestine and colon in absorption of water (the small intestine absorbs 5–10 dm3 per day, the colon 0.3–0.5 dm3 per day)"}]},{"n":"6.3.7","title":"Assimilation","core":[{"text":"Define assimilation as movement of digested food molecules into the cells of the body where they are used, becoming part of the cells"},{"text":"Describe the role of the liver in the metabolism of glucose (glucose → glycogen) and amino acids (amino acids → proteins and destruction of excess amino acids)"},{"text":"Describe the role of fat as an energy storage substance"}],"supplement":[{"text":"Define deamination as removal of the nitrogen-containing part of amino acids to form urea, followed by release of energy from the remainder of the amino acid"},{"text":"State that the liver is the site of breakdown of alcohol and other toxins"}]}],"group":"Section II: Organisation and maintenance of the organism"},{"n":"II.7","title":"Transportation","sections":[{"n":"7.1","title":"Transport in plants","core":[{"text":"State the functions of xylem and phloem"},{"text":"Identify the positions of xylem and phloem tissues as seen in transverse sections of unthickened, herbaceous, dicotyledonous roots, stems and leaves"}],"supplement":[]},{"n":"7.1.1","title":"Water uptake","core":[{"text":"Identify root hair cells, as seen under the light microscope, and state their functions"},{"text":"State the pathway taken by water through root, stem and leaf (root hair, root cortex cells, xylem, mesophyll cells)"},{"text":"Investigate, using a suitable stain, the pathway of water through the above-ground parts of a plant"}],"supplement":[{"text":"Relate the structure and functions of root hairs to their surface area and to water and ion uptake"}]},{"n":"7.1.2","title":"Transpiration","core":[{"text":"Define transpiration as evaporation of water at the surfaces of the mesophyll cells followed by loss of water vapour from plant leaves, through the stomata"},{"text":"Describe how water vapour loss is related to cell surfaces, air spaces and stomata"},{"text":"Describe the effects of variation of temperature, humidity and light intensity on transpiration rate"},{"text":"Describe how wilting occurs"}],"supplement":[{"text":"Explain the mechanism of water uptake and movement in terms of transpiration producing a tension (‘pull’) from above, creating a water potential gradient in the xylem, drawing cohesive water molecules up the plant."},{"text":"Discuss the adaptations of the leaf, stem and root to three contrasting environments, to include pond, garden and desert, with emphasis on local examples (where appropriate) and the factors described in the core"}]},{"n":"7.1.3","title":"Translocation","core":[{"text":"Define translocation in terms of the movement of sucrose and amino acids in phloem;\n• from regions of production\n• to regions of storage OR to regions of utilisation in respiration or growth"}],"supplement":[{"text":"Describe translocation throughout the plant of applied chemicals, including systemic pesticides"},{"text":"Compare the role of transpiration and translocation in the transport of materials from sources to sinks, within plants at different seasons"}]},{"n":"7.2","title":"Transport in humans","core":[{"text":"Describe the circulatory system as a system of tubes with a pump and valves to ensure one-way flow of blood"},{"text":"Describe the double circulation in terms of a low pressure circulation to the lungs and a high pressure circulation to the body tissues and relate these differences to the different functions of the two circuits"}],"supplement":[]},{"n":"7.2.1","title":"Heart","core":[{"text":"Describe the structure of the heart including the muscular wall and septum, chambers, valves and associated blood vessels"},{"text":"Describe the function of the heart in terms of muscular contraction and the working of the valves"},{"text":"Investigate, state and explain the effect of physical activity on pulse rate"},{"text":"Describe coronary heart disease in terms of the blockage of coronary arteries and state the possible causes (diet, stress and smoking) and preventive measures"}],"supplement":[]},{"n":"7.2.2","title":"Arteries, veins and capillaries","core":[{"text":"Name the main blood vessels to and from the heart, lungs, liver and kidney"},{"text":"Describe the structure and functions of arteries, veins and capillaries"}],"supplement":[{"text":"Explain how structure and function are related in arteries, veins and capillaries"},{"text":"Describe the transfer of materials between capillaries and tissue fluid"}]},{"n":"7.2.3","title":"Blood","core":[{"text":"Identify red and white blood cells as seen under the light microscope on prepared slides, and in diagrams and photomicrographs"},{"text":"List the components of blood as red blood cells, white blood cells, platelets and plasma"},{"text":"State the functions of blood:\n• red blood cells – haemoglobin and oxygen transport\n• white blood cells – phagocytosis and antibody formation\n• platelets – causing clotting (no details)\n• plasma – transport of blood cells, ions, soluble nutrients, hormones, carbon dioxide, urea and plasma proteins"}],"supplement":[{"text":"Describe the immune system in terms of antibody production, tissue rejection and phagocytosis"},{"text":"Describe the function of the lymphatic system in circulation of body fluids, and the production of lymphocytes"},{"text":"Describe the process of clotting (fibrinogen to fibrin only)"}]}],"group":"Section II: Organisation and maintenance of the organism"},{"n":"II.8","title":"Respiration","sections":[{"n":"8","title":"Respiration","core":[{"text":"Define respiration as the chemical reactions that break down nutrient molecules in living cells to release energy"},{"text":"State the uses of energy in the body of humans: muscle contraction, protein synthesis, cell division, active transport, growth, the passage of nerve impulses and the maintenance of a constant body temperature"}],"supplement":[]},{"n":"8.1","title":"Aerobic respiration","core":[{"text":"Define aerobic respiration as the release of a relatively large amount of energy in cells by the breakdown of food substances in the presence of oxygen"},{"text":"State the word equation for aerobic respiration"}],"supplement":[{"text":"State the equation for aerobic respiration using symbols (C6H12O6 + 6O2 → 6CO2 + 6H2O)"}]},{"n":"8.2","title":"Anaerobic respiration","core":[{"text":"Define anaerobic respiration as the release of a relatively small amount of energy by the breakdown of food substances in the absence of oxygen"},{"text":"State the word equation for anaerobic respiration in muscles during hard exercise (glucose → lactic acid) and the microorganism yeast (glucose → alcohol + carbon dioxide)"},{"text":"Describe the role of anaerobic respiration in yeast during brewing and bread-making"},{"text":"Compare aerobic respiration and anaerobic respiration in terms of relative amounts of energy released"}],"supplement":[{"text":"State the balanced equation for anaerobic respiration in muscles (C6H12O6 → 2C3H6O3) and the microorganism yeast (C6H12O6 → 2C2H5OH + 2CO2), using symbols"},{"text":"Describe the effect of lactic acid in muscles during exercise (include oxygen debt in outline only)"}]},{"n":"8.3","title":"Gas exchange","core":[{"text":"List the features of gas exchange surfaces in animals"},{"text":"Identify on diagrams and name the larynx, trachea, bronchi, bronchioles, alveoli and associated capillaries"},{"text":"State the differences in composition between inspired and expired air"},{"text":"Use lime water as a test for carbon dioxide to investigate the differences in composition between inspired and expired air"},{"text":"Investigate and describe the effects of physical activity on rate and depth of breathing"}],"supplement":[{"text":"Describe the role of the ribs, the internal and external intercostal muscles and the diaphragm in producing volume and pressure changes leading to the ventilation of the lungs"},{"text":"Explain the role of mucus and cilia in protecting the gas exchange system from pathogens and particles"},{"text":"Explain the link between physical activity and rate and depth of breathing in terms of changes in the rate at which tissues respire and therefore of carbon dioxide concentration and pH in tissues and in the blood"}]}],"group":"Section II: Organisation and maintenance of the organism"},{"n":"II.9","title":"Excretion in humans","sections":[{"n":"9","title":"Excretion in humans","core":[{"text":"Define excretion as the removal from organisms of toxic materials, the waste products of metabolism (chemical reactions in cells including respiration) and substances in excess of requirements. Substances should include carbon dioxide, urea and salts"},{"text":"Describe the function of the kidney in terms of the removal of urea and excess water and the reabsorption of glucose and some salts (details of kidney structure and nephron are not required)"},{"text":"State the relative positions of ureters, bladder and urethra in the body"},{"text":"State that urea is formed in the liver from excess amino acids"},{"text":"State that alcohol, drugs and hormones are broken down in the liver"}],"supplement":[{"text":"Outline the structure of a kidney (cortex, medulla, and the start of the ureter) and outline the structure and functioning of a kidney tubule including:\n• role of renal capsule in filtration from blood of water, glucose, urea and salts\n• role of tubule in reabsorption of glucose, most of the water and some salts back into the blood, leading to concentration of urea in the urine as well as loss of excess water and salts"},{"text":"Explain dialysis in terms of maintenance of glucose and protein concentration in blood and diffusion of urea from blood to dialysis fluid"},{"text":"Discuss the application of dialysis in kidney machines"},{"text":"Discuss the advantages and disadvantages of kidney transplants, compared with dialysis"}]}],"group":"Section II: Organisation and maintenance of the organism"},{"n":"II.10","title":"Coordination and response","sections":[{"n":"10.1","title":"Nervous control in humans","core":[{"text":"Describe the human nervous system in terms of the central nervous system (brain and spinal cord as areas of coordination) and the peripheral nervous system which together serve to coordinate and regulate body functions"},{"text":"Identify motor (effector), relay (connector) and sensory neurones from diagrams"},{"text":"Describe a simple reflex arc in terms of sensory, relay and motor neurones, and a reflex action as a means of automatically and rapidly integrating and coordinating stimuli with responses"},{"text":"State that muscles and glands can act as effectors"},{"text":"Describe the action of antagonistic muscles to include the biceps and triceps at the elbow joint"},{"text":"Define sense organs as groups of receptor cells responding to specific stimuli: light, sound, touch, temperature and chemicals"},{"text":"Describe the structure and function of the eye, including accommodation and pupil reflex"}],"supplement":[{"text":"Distinguish between voluntary and involuntary actions"},{"text":"Distinguish between rods and cones, in terms of function and distribution"}]},{"n":"10.2","title":"Hormones","core":[{"text":"Define a hormone as a chemical substance, produced by a gland, carried by the blood, which alters the activity of one or more specific target organs and is then destroyed by the liver"},{"text":"State the role of the hormone adrenaline in chemical control of metabolic activity, including increasing the blood glucose concentration and pulse rate"},{"text":"Give examples of situations in which adrenaline secretion increases"},{"text":"Compare nervous and hormonal control systems"}],"supplement":[{"text":"Discuss the use of hormones in food production"}]},{"n":"10.3","title":"Tropic responses","core":[{"text":"Define and investigate geotropism (as a response in which a plant grows towards or away from gravity) and phototropism (as a response in which a plant grows towards or away from the direction from which light is coming)"}],"supplement":[{"text":"Explain the chemical control of plant growth by auxins including geotropism and phototropism in terms of auxins regulating differential growth, and the effects of synthetic plant hormones used as weedkillers"}]},{"n":"10.4","title":"Homeostasis","core":[{"text":"Define homeostasis as the maintenance of a constant internal environment"},{"text":"Identify, on a diagram of the skin: hairs, sweat glands, temperature receptors, blood vessels and fatty tissue"},{"text":"Describe the maintenance of a constant body temperature in humans in terms of insulation and the role of temperature receptors in the skin, sweating, shivering, vasodilation and vasoconstriction of arterioles supplying skin-surface capillaries and the coordinating role of the brain"}],"supplement":[{"text":"Explain the concept of control by negative feedback"},{"text":"Describe the control of the glucose content of the blood by the liver, and by insulin and glucagon from the pancreas"}]},{"n":"10.5","title":"Drugs","core":[{"text":"Define a drug as any substance taken into the body that modifies or affects chemical reactions in the body"},{"text":"Describe the medicinal use of antibiotics for the treatment of bacterial infection"},{"text":"Describe the effects of the abuse of heroin: a powerful depressant, problems of addiction, severe withdrawal symptoms and associated problems such as crime and infection e.g. HIV/AIDS"},{"text":"Describe the effects of excessive consumption of alcohol: reduced self-control, depressant, effect on reaction times, damage to liver and social implications"},{"text":"Describe the effects of tobacco smoke and its major toxic components (tar, nicotine, carbon monoxide, smoke particles) on the gas exchange system"}],"supplement":[{"text":"Explain why antibiotics kill bacteria but not viruses"}]}],"group":"Section II: Organisation and maintenance of the organism"},{"n":"III.1","title":"Reproduction","sections":[{"n":"1.1","title":"Asexual reproduction","core":[{"text":"Define asexual reproduction as the process resulting in the production of genetically identical offspring from one parent"},{"text":"Describe asexual reproduction in bacteria, spore production in fungi and tuber formation in potatoes"}],"supplement":[{"text":"Discuss the advantages and disadvantages to a species of asexual reproduction"}]},{"n":"1.2","title":"Sexual reproduction","core":[{"text":"Define sexual reproduction as the process involving the fusion of haploid nuclei to form a diploid zygote and the production of genetically dissimilar offspring"}],"supplement":[{"text":"Discuss the advantages and disadvantages to a species of sexual reproduction"}]},{"n":"1.2.1","title":"Sexual reproduction in plants","core":[{"text":"Identify and draw, using a hand lens if necessary, the sepals, petals, stamens, anthers, carpels, ovaries and stigmas of one, locally available, named, insect-pollinated, dicotyledonous flower, and examine the pollen grains under a light microscope or in photomicrographs"},{"text":"State the functions of the sepals, petals, anthers, stigmas and ovaries"},{"text":"Use a hand lens to identify and describe the anthers and stigmas of one, locally available, named, wind-pollinated flower, and examine the pollen grains under a light microscope or in photomicrographs"},{"text":"Candidates should expect to apply their understanding of the flowers they have studied to unfamiliar flowers"},{"text":"Define pollination as the transfer of pollen grains from the male part of the plant (anther of stamen) to the female part of the plant (stigma)"},{"text":"Name the agents of pollination"},{"text":"Compare the different structural adaptations of insect-pollinated and wind-pollinated flowers"},{"text":"Describe the growth of the pollen tube and its entry into the ovule followed by fertilisation (production of endosperm and details of development are not required)"},{"text":"Investigate and describe the structure of a non-endospermic seed in terms of the embryo (radicle, plumule and cotyledons) and testa, protected by the fruit"},{"text":"Outline the formation of a seed (limited to embryo, cotyledons, testa and role of mitosis) and fruit (produced from the ovary wall)"},{"text":"State that seed and fruit dispersal by wind and by animals provides a means of colonising new areas"},{"text":"Describe, using named examples, seed and fruit dispersal by wind and by animals"}],"supplement":[{"text":"Distinguish between self-pollination and cross-pollination"},{"text":"Discuss the implications to a species of self-pollination and cross-pollination"}]},{"n":"1.2.2","title":"Sexual reproduction in humans","core":[{"text":"Identify on diagrams of the male reproductive system, the testes, scrotum, sperm ducts, prostate gland, urethra and penis, and state the functions of these parts"},{"text":"Identify on diagrams of the female reproductive system, the ovaries, oviducts, uterus, cervix and vagina, and state the functions of these parts"},{"text":"Describe the menstrual cycle in terms of changes in the uterus and ovaries"},{"text":"Outline sexual intercourse and describe fertilisation in terms of the joining of the nuclei of male gamete (sperm) and the female gamete (egg)"},{"text":"Outline early development of the zygote simply in terms of the formation of a ball of cells that becomes implanted in the wall of the uterus"},{"text":"Outline the development of the fetus"},{"text":"Describe the function of the placenta and umbilical cord in relation to exchange of dissolved nutrients, gases and excretory products (no structural details are required)"},{"text":"Describe the ante-natal care of pregnant women including special dietary needs and maintaining good health"},{"text":"Outline the processes involved in labour and birth"}],"supplement":[{"text":"Compare male and female gametes in terms of size, numbers and mobility"},{"text":"Explain the role of hormones in controlling the menstrual cycle (including FSH, LH, progesterone and oestrogen)"},{"text":"Indicate the functions of the amniotic sac and amniotic fluid"},{"text":"Describe the advantages and disadvantages of breast-feeding compared with bottle-feeding using formula milk"}]},{"n":"1.3","title":"Sex hormones","core":[{"text":"Describe the roles of testosterone and oestrogen in the development and regulation of secondary sexual characteristics at puberty"}],"supplement":[{"text":"Describe the sites of production and the roles of oestrogen and progesterone in the menstrual cycle and in pregnancy (cross reference 1.2.2)"}]},{"n":"1.4","title":"Methods of birth control","core":[{"text":"Outline the following methods of birth control:\n• natural (abstinence, rhythm method)\n• chemical (contraceptive pill, spermicide)\n• mechanical (condom, diaphragm, femidom, IUD)\n• surgical (vasectomy, female sterilisation)"}],"supplement":[{"text":"Outline artificial insemination and the use of hormones in fertility drugs, and discuss their social implications"}]},{"n":"1.5","title":"Sexually transmissible diseases","core":[{"text":"Describe the symptoms, signs, effects and treatment of gonorrhoea"},{"text":"Describe the methods of transmission of human immunodeficiency virus (HIV), and the ways in which HIV/AIDS can be prevented from spreading"}],"supplement":[{"text":"Outline how HIV affects the immune system in a person with HIV/AIDS"}]}],"group":"Section III: Development of the organism and the continuity of life"},{"n":"III.2","title":"Growth and development","sections":[{"n":"2","title":"Growth and development","core":[{"text":"Define growth in terms of a permanent increase in size and dry mass by an increase in cell number or cell size or both"},{"text":"Define development in terms of increase in complexity"},{"text":"Investigate and state the environmental conditions that affect germination of seeds: requirement for water and oxygen, suitable temperature"}],"supplement":[]}],"group":"Section III: Development of the organism and the continuity of life"},{"n":"III.3","title":"Inheritance","sections":[{"n":"3","title":"Inheritance","core":[{"text":"Define inheritance as the transmission of genetic information from generation to generation"}],"supplement":[]},{"n":"3.1","title":"Chromosomes","core":[{"text":"Define the terms:\n• chromosome as a thread of DNA, made up of a string of genes\n• gene as a length of DNA that is the unit of heredity and codes for a specific protein. A gene may be copied and passed on to the next generation\n• allele as any of two or more alternative forms of a gene\n• haploid nucleus as a nucleus containing a single set of unpaired chromosomes (e.g. sperm and egg)\n• diploid nucleus as a nucleus containing two sets of chromosomes (e.g. in body cells)"},{"text":"Describe the inheritance of sex in humans (XX and XY chromosomes)"}],"supplement":[]},{"n":"3.2","title":"Mitosis","core":[{"text":"Define mitosis as nuclear division giving rise to genetically identical cells in which the chromosome number is maintained by the exact duplication of chromosomes (details of stages are not required)"},{"text":"State the role of mitosis in growth, repair of damaged tissues, replacement of worn out cells and asexual reproduction"}],"supplement":[]},{"n":"3.3","title":"Meiosis","core":[{"text":"Define meiosis as reduction division in which the chromosome number is halved from diploid to haploid (details of stages are not required)"},{"text":"State that gametes are the result of meiosis"},{"text":"State that meiosis results in genetic variation so the cells produced are not all genetically identical"}],"supplement":[]},{"n":"3.4","title":"Monohybrid inheritance","core":[{"text":"Define the terms:\n• genotype as genetic makeup of an organism in terms of the alleles present (e.g. Tt or GG)\n• phenotype as the physical or other features of an organism due to both its genotype and its environment (e.g. tall plant or green seed)\n• homozygous as having two identical alleles of a particular gene (e.g. TT or gg). Two identical homozygous individuals that breed together will be pure-breeding\n• heterozygous as having two different alleles of a particular gene (e.g. Tt or Gg), not pure-breeding\n• dominant as an allele that is expressed if it is present (e.g. T or G)\n• recessive as an allele that is only expressed when there is no dominant allele of the gene present (e.g. t or g)"},{"text":"Calculate and predict the results of monohybrid crosses involving 1 : 1 and 3 : 1 ratios"}],"supplement":[{"text":"Explain codominance by reference to the inheritance of ABO blood groups – phenotypes, A, B, AB and O blood groups and genotypes IA, IB, and IO"}]},{"n":"3.5","title":"Variation","core":[{"text":"State that continuous variation is influenced by genes and environment, resulting in a range of phenotypes between two extremes, e.g. height in humans"},{"text":"State that discontinuous variation is caused by genes alone and results in a limited number of distinct phenotypes with no intermediates e.g. A, B, AB and O blood groups in humans"},{"text":"Define mutation as a change in a gene or chromosome"},{"text":"Describe mutation as a source of variation, as shown by Down’s syndrome"},{"text":"Outline the effects of ionising radiation and chemicals on the rate of mutation"}],"supplement":[{"text":"Describe sickle cell anaemia, and explain its incidence in relation to that of malaria"}]},{"n":"3.6","title":"Selection","core":[{"text":"Describe the role of artificial selection in the production of varieties of animals and plants with increased economic importance"},{"text":"Define natural selection as the greater chance of passing on of genes by the best adapted organisms"}],"supplement":[{"text":"Describe variation and state that competition leads to differential survival of, and reproduction by, those organisms best fitted to the environment"},{"text":"Assess the importance of natural selection as a possible mechanism for evolution"},{"text":"Describe the development of strains of antibiotic resistant bacteria as an example of natural selection"}]},{"n":"3.7","title":"Genetic Engineering","core":[{"text":"Define genetic engineering as taking a gene from one species and putting it into another species"}],"supplement":[{"text":"Explain why, and outline how, human insulin genes were put into bacteria using genetic engineering"}]}],"group":"Section III: Development of the organism and the continuity of life"},{"n":"IV.1","title":"Energy flow","sections":[{"n":"1","title":"Energy flow","core":[{"text":"State that the Sun is the principal source of energy input to biological systems"},{"text":"Describe the non-cyclical nature of energy flow"}],"supplement":[]}],"group":"Section IV: Relationships of organisms with one another and with their environment"},{"n":"IV.2","title":"Food chains and food webs (emphasis on examples occurring locally)","sections":[{"n":"2","title":"Food chains and food webs (emphasis on examples occurring locally)","core":[{"text":"Define the terms:\n• food chain as a chart showing the flow of energy (food) from one organism to the next beginning with a producer (e.g. mahogany tree → caterpillar → song bird → hawk)\n• food web as a network of interconnected food chains showing the energy flow through part of an ecosystem\n• producer as an organism that makes its own organic nutrients, usually using energy from sunlight, through photosynthesis\n• consumer as an organism that gets its energy by feeding on other organisms\n• herbivore as an animal that gets its energy by eating plants\n• carnivore as an animal that gets its energy by eating other animals\n• decomposer as an organism that gets its energy from dead or waste organic matter\n• ecosystem as a unit containing all of the organisms and their environment, interacting together, in a given area e.g. decomposing log or a lake\n• trophic level as the position of an organism in a food chain, food web or pyramid of biomass, numbers or energy"},{"text":"Describe energy losses between trophic levels"},{"text":"Draw, describe and interpret pyramids of biomass and numbers"}],"supplement":[{"text":"Explain why food chains usually have fewer than five trophic levels"},{"text":"Explain why there is an increased efficiency in supplying green plants as human food and that there is a relative inefficiency, in terms of energy loss, in feeding crop plants to animals"}]}],"group":"Section IV: Relationships of organisms with one another and with their environment"},{"n":"IV.3","title":"Nutrient cycles","sections":[{"n":"3","title":"Nutrient cycles","core":[{"text":"Describe the carbon and the water cycles"}],"supplement":[{"text":"Describe the nitrogen cycle in terms of:\n• the role of microorganisms in providing usable nitrogen-containing substances by decomposition and by nitrogen fixation in roots\n• the absorption of these substances by plants and their conversion to protein\n• followed by passage through food chains, death, decay\n• nitrification and denitrification and the return of nitrogen to the soil or the atmosphere (names of individual bacteria are not required)"},{"text":"Discuss the effects of the combustion of fossil fuels and the cutting down of forests on the oxygen and carbon dioxide concentrations in the atmosphere"}]}],"group":"Section IV: Relationships of organisms with one another and with their environment"},{"n":"IV.4","title":"Population size","sections":[{"n":"4","title":"Population size","core":[{"text":"Define population as a group of organisms of one species, living in the same area at the same time"},{"text":"State the factors affecting the rate of population growth for a population of an organism (limited to food supply, predation and disease), and describe their importance"},{"text":"Identify the lag, exponential (log), stationary and death phases in the sigmoid population growth curve for a population growing in an environment with limited resources"},{"text":"Describe the increase in human population size and its social implications"},{"text":"Interpret graphs and diagrams of human population growth"}],"supplement":[{"text":"Explain the factors that lead to the lag phase, exponential (log) phase and stationary phase in the sigmoid curve of population growth making reference, where appropriate, to the role of limiting factors"}]}],"group":"Section IV: Relationships of organisms with one another and with their environment"},{"n":"IV.5","title":"Human influences on the ecosystem","sections":[{"n":"5","title":"Human influences on the ecosystem","core":[{"text":"Outline the effects of humans on ecosystems, with emphasis on examples of international importance (tropical rain forests, oceans and important rivers)"}],"supplement":[]},{"n":"5.1","title":"Agriculture","core":[{"text":"List the undesirable effects of deforestation (to include extinction, loss of soil, flooding, carbon dioxide build up)"},{"text":"Describe the undesirable effects of overuse of fertilisers (to include eutrophication of lakes and rivers)"}],"supplement":[]},{"n":"5.2","title":"Pollution","core":[{"text":"Describe the undesirable effects of pollution to include:\n• water pollution by sewage and chemical waste\n• air pollution by sulfur dioxide\n• air pollution by greenhouse gases (carbon dioxide and methane) contributing to global warming\n• pollution due to pesticides including insecticides and herbicides\n• pollution due to nuclear fall-out"}],"supplement":[{"text":"Discuss the effects of non-biodegradable plastics in the environment"},{"text":"Discuss the causes and effects on the environment of acid rain, and the measures that might be taken to reduce its incidence"},{"text":"Explain how increases in greenhouse gases (carbon dioxide and methane) are thought to cause global warming"}]},{"n":"5.3","title":"Conservation","core":[{"text":"Describe the need for conservation of:\n• species and their habitats\n• natural resources (limited to water and non-renewable materials including fossil fuels)"}],"supplement":[{"text":"Explain how limited and non-renewable resources can be recycled (including recycling of paper and treatment of sewage to make the water that it contains safe to return to the environment or for human use)"}]}],"group":"Section IV: Relationships of organisms with one another and with their environment"}]}]};
